window.__D("text/torat-chaim/c025",{"p":[[2300540668,"והמן הי' בבחי' הפנימי' דח\"ע וכל בחי' פנימי' שובת בשבת ע\"כ לא הי' יורד למטה בשבת כמ\"ש היום לא תמצאוהו בשדה כנ\"ל (ואע\"פ שבסעודת השבת בא עונג העליון במורגש בעונג וטעם גשמי' ואו' דא היא סעודתא דע\"י כו' כנ\"ל, אבל לא ירד שפע דסעודת השבת ביום השבת כ\"א מאשר אפו ובשלו בע\"ש דמי שטרח בע\"ש יאכל בשבת כו', וכך הוא באכילת המן שאכל[ו] בשבת מאשר הוכן בע\"ש כמ\"ש והי' ביום הששי כו' וד\"ל) (ומה שנמשך עונג העליון הנעלם העצמי שבפנימי' ע\"י ופנימי' דאבא להוליד נשמות בשבת יחוד פנימי דאו\"א כגוונא<sup data-n=\"10482\">355</sup> דחכימין למטה כנ\"ל שבא בהגשמה, זהו הכל בבחי' פנימי' ועצמי' שלמעלה מן השפע החיצוניות דחו\"ב בעולמות).\n<b>ועדיין</b> אין כ\"ז מתיישב נכון דמ\"מ הרי בסעודת השבת מלובש מעונג העליון כמו שהוא<sup data-n=\"10483\">356</sup> ואו' דא ה[י]א כו' כמו אכלו ריעים לעילא שהוא [ב]פנימי' המזון דחו\"ב דאצי' למעלה, א\"כ גם המן שנק' לחם מן השמים הי' יכול לבוא למטה כמו שהוא למעלה בפנימי' דאו\"א כו'. אך התירוץ האמיתי לזה <span data-k=\"pg\">626</span> ּ יובן ממ\"ש במ\"א בענין העדן דעוה\"ב<sup data-n=\"10484\">357</sup> שיש בו ב' מדרגות [ש]בכתר (גימ' תר\"ך<sup data-n=\"10485\">359</sup> והחכ'<sup data-n=\"10486\">360</sup> נק' יש<sup data-n=\"10487\">361</sup> והוא שנק' פר\"ס<sup data-n=\"10488\">358</sup> ונחלק לחו\"ב וזהו קנה חכמה<sup data-n=\"10489\">362</sup> ב\"פ קנה גימ' יש<sup data-n=\"10490\">363</sup>, וחצי התחתון הוא שכר של המצות בתענוג מורגש שבא מן התענוג הנעלם שבפנימי' רצה\"ע שבמצות למעלה (והוא בחי' חסד דע\"י שמלובש בגלגלתא<sup data-n=\"10491\">364</sup> כו') שנק' י\"ג חוורתי<sup data-n=\"10492\">365</sup> כו'), וז\"ש יאר ה' פניו<sup data-n=\"10493\">366</sup> כו' וכתי' בי' להנחיל אוהבי יש<sup data-n=\"10494\">367</sup>, וחצי העליון הוא בבחי' העדן עצמו דעין לא ראתה רק למחכה לו<sup data-n=\"10495\">368</sup> כו' שהוא ענין עליות הנשמות דת\"ח שאין להם מנוחה<sup data-n=\"10496\">369</sup> אפילו בעוה\"ב כענין וקדושים<sup data-n=\"10497\">370</sup> כו' שעולים בעילוי אחר עילוי בעצמות השעשועי' שלמעלה מכל חיי העוה\"ב כו', ועלי' זו היא רק ביטול העצמות מכל וכל שאינו יכול לבא בעונג מורגש כלל רק בהיפוך בעלי' והסתלקות למעלה וזהו עיקר חיות[ם] כמ\"ש ילכו מחיל אל<sup data-n=\"10498\">371</sup> כו' וכמו להחיותם ברעב<sup data-n=\"10499\">372</sup> שהרעב זהו עיקר החיות ולא השביעה במורגש כו'. ודוגמא לזה כחיות העני בפרוטה א' רק להחיות עצמיות נפשו ולא כעשיר שישבע בלחם ומזון ומיני מעדנים כו'. וכך הוא ההפרש בין צ\"ג לבע\"ת דצ\"ג ישבעו ויתענגו בעוה\"ב",[["10482","355","<b>כגוונא</b>: בה: (כ)זווגא."],["10483","356","<b>כמו שהוא</b>: ה: בסעודה זו."],["10484","357","<b>העדן דעוה\"ב. . ב' מדרגות [ש]בכתר</b>: ראה גם מאמרי אדה\"א נ\"ך ע' תעא. לעיל פ' שמות ח, סע\"ד ואילך."],["10485","359","<b>[ש]בכתר. . תר\"ך</b>: ראה ע\"ח (שער ז\"א) שי\"ז, ספ\"א. מאמרי אדה\"א דברים ח\"ד ע' א'רצט. וש\"נ."],["10486","360","<b>והחכ'</b>: ה: והחצי."],["10487","361","<b>[ש]בכתר. . והחצי נק' יש</b>: ראה הקדמת הראב\"ד לס\"י [ירושלים תשכ\"ב ד, א]."],["10488","358","<b>דעוה\"ב. . שנק' פר\"ס</b>: ראה גם תו\"ח מקץ רכא, ב ובהערה 18. לקמן פ' תצוה שדמ, ב."],["10489","362","<b>קנה חכמה</b>: משלי ד, ה. ז."],["10490","363","<b>ב\"פ קנה גימ' יש</b>: נסמן לעיל פ' שמות לג, ג."],["10491","364","<b>חסד דע\"י שמלובש בגלגלתא</b>: ראה ע\"ח (שער א\"א) שי\"ג, פ\"ו. פ\"ז."],["10492","365","<b>י\"ג חוורתי</b>: ראה זהר (אד\"ר) נשא קכח, ב. מאמרי אדה\"א דברים ח\"ג ע' תתנ. וש\"נ."],["10493","366","<b>יאר ה' פניו</b>: נשא ו, כה."],["10494","367","<b>להנחיל אוהבי יש</b>: ראה גם לעיל פ' שמות ט, א. וש\"נ."],["10495","368","<b>העדן. . דעין לא ראתה. . למחכה לו</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["10496","369","<b>דת\"ח שאין להם מנוחה</b>: ראה גם לעיל פ' שמות ד, ג. וש\"נ."],["10497","370","<b>וקדושים</b>: נוסח שמו\"ע. עירובין נד, א."],["10498","371","<b>ילכו מחיל אל </b>[ב: ניתוסף: חיל. ה: ליתא]: תהלים פד, ח."],["10499","372","<b>להחיותם ברעב</b>: נסמן לעיל קסא, א."]]],[2300540680,"משכר המצות שעשו בעוה\"ז כעשיר והיינו מעונג הנעלם שבא במורגש כנ\"ל ובע\"ת נק' אביוני אדם<sup data-n=\"10500\">373</sup> שאין להם מצות כלל רק חיות עצמיות נפשם הוא בבחי' הביטול והסתלקות שלהם במקורא דכולא כו' שהוא כמו הרעבון והצמאון היפך השביעה (וז\"ש ישא ה' פניו כו' על שמחמירים על עצמם לברך גם כשאוכלים פחות מכדי שביעה רק בכזית<sup data-n=\"10501\">374</sup> כו'). ובזה יובן גם ההפרש שבין מזון המן למזון דסעודת השבת (ומעין<sup data-n=\"10502\">375</sup> עוה\"ב שישבעו ויתענגו בשביעה במורגש כנ\"ל, אבל המן<sup data-n=\"10503\">376</sup> שרשו מבחי' גבורות דע\"י שבפנימית ח\"ס כנ\"ל שהוא בבחי' העלמות וביטול במציאות בתכלית האין שעולה בעילוי אחר עילוי (בשבת דוקא) כענין הילוך ועילוי הנשמות בעדן העצמי' הנ\"ל שלמעלה מחיי העוה\"ב וכמו בחי' התוש\"ב<sup data-n=\"10504\">377</sup> וכמו העני וד\"ל כנ\"ל.\n<b>וז\"ש</b> במן ויענך וירעיבך ויאכילך את המן כו' דמשמע מלשון זה דויענך וירעיבך שלא הי' במן כדי שביעה<sup data-n=\"10505\">378</sup> כלל אלא אדרבה הי' עינוי ורעבון כמ\"ש ויענך וירעיבך ויאכילך את המן כו', ולכאורה איך שייך רעבון ועינוי הנפש במזון לחם דמן שנק' לחם מן השמים כו'. אלא מפני שהי' שרשו למעלה מבחי' הרגשה בנפש באו\"כ וכמ\"ש בזהר שהוא מזונא דקיק יתיר כו' ועכ\"ז נק' מזונא דנר\"נ כו'. והענין הוא שלא הי' כמזון דלחם מן הארץ שבא במורגש בשביעה בהיותו בא בכרס בעיכול ונהפך להיות<sup data-n=\"10506\">379</sup> מורגש במוח ולב ואברים בדם הוא הנפש<sup data-n=\"10507\">380</sup> כו', אבל המן הרי הי' נבלע ברמ\"ח אברים, ופי' נבלע שנבלע כמו שהוא ברוחניות בהעלם החיות בלתי מורגש למזון לשובע הנפש כלל. וכמו הדוגמא מטעימת טעם המתיקות דפירות הטובי' וכטעם השמן והדבש שאין בו הרגשה לגוף ונפש כלל רק פיקוח החיות בהעלם עצם הנפש כמו שהוא לחזק עצמיות כחה הנעלם (וראי' ממה שא' ועתה נפשנו יבישה<sup data-n=\"10508\">381</sup> אין כל בלתי כו' לחם הקלוקל<sup data-n=\"10509\">382</sup> כו' יבישה בלא הרגש החיות בשביעה כלל בנפש היבישה מרעבון כו'), וכמו מתיקו' טעמים וסודות התורה הפנימי' <span data-k=\"pg\">שיג</span> ּ שלא תשבע הנפש כלל במורגש רק אדרבה שתכלה הנפש מרוב עונג בכלות הנפש ברעבון וצמאון כו' כידוע). וזהו ויענ\"ך וירעיב\"ך שהי' האכילה דמן בבחי' רעבון ועינוי הנפש, [ו]אמנם זה הי' עיקר חיותם וקיומם דוקא כמו להחיותם ברעב כנ\"ל שהרעב הוא עיקר החיות דעצמיות הנפש והוא בחי' ביטול והתכללות דעצם הנשמה במקורה, כמו ביטול והתכללות דניצוץ באבוקה או באש היסודי כמו חיות העני ובע\"ת וכנ\"ל בענין",[["10500","373","<b>ובע\"ת נק' אביוני אדם</b>: נסמן לעיל פ' שמות ט, א."],["10501","374","<b>ישא ה' פניו. . בכזית</b>: נשא ו, כו. ראה ברכות כ, ב. מאמרי אדה\"א הנחות תקע\"ז ע' קכח. וש\"נ."],["10502","375","<b>(ומעין</b>: בה: דסעודת השבת מעין."],["10503","376","<b>המן</b>: ב: ניתוסף: הרי. ה: ניתוסף: הי'."],["10504","377","<b>התוש\"ב</b>: בה: התשובה."],["10505","378","<b>ויענך וירעיבך. . שלא הי' במן כדי שביעה</b>: ראה לק\"ט עקב ח, ב-ג. קה\"ר פ\"ה, י (א)."],["10506","379","<b>להיות</b>: בה: לחיות."],["10507","380","<b>בדם הוא הנפש</b>: פ' ראה יב, כג."],["10508","381","<b>ועתה נפשנו יבישה</b>: בהעלותך יא, ו."],["10509","382","<b>לחם הקלוקל</b>: חוקת כא, ה. ראה גם מאמרי אדה\"א שמות ח\"א ס\"ע רג. במדבר ח\"ב ע' תשעא."]]],[2300540692,"הילוך ועליי' הנשמות לע\"ל כו' וד\"ל. וזהו שהי' מזונא דנר\"נ בעצם מהותם למעלה מחיבור הנר\"נ בכלים, אך שעי\"ז ממילא הי' החיבור החיות דנר\"נ במוחא ולבא כו' מבחי' המקיפי' דחי' יחידה בלי הרגשה כלל היפוך דישבעו ויתענגו בשבת ובעוה\"ב, והיינו ענין הטל דתח\"ה שנק' טהרה שמביאה לידי קדושה דעוה\"ב כו' (להיותו מבחי' טה\"ע<sup data-n=\"10510\">383</sup> שאע\"פ שנמשך לשמים העליונים בכל שבת דוקא על כל הוי\"ו יומי' דחול כנ\"ל אבל לא בא למטה במורגש כסעודת השבת וד\"ל).\n<b>וזהו</b> למען הודיעך<sup data-n=\"10511\">384</sup> כי לא על הלחם לבדו יחיה האדם כו' גם לא בלחמה של תורה הנגלית שנק' לחם מן הארץ<sup data-n=\"10512\">*385</sup> שבא במורגש בשביעה כמו ותורתך בתו\"ך מע\"י כו' (כמו ממלא כריס\"ו בתלמוד<sup data-n=\"10513\">385</sup> כו') כי על כל מוצא פי ה' דוקא יחיה האדם. והענין הוא דמה שהתורה נק' מזון לנשמות זהו הבא בבחי' או\"כ כחכ' מוחא ובינה ליבא<sup data-n=\"10514\">386</sup> כו' להבדיל בין טו\"ר בגשמיות בסומ\"ר וע\"ט, אבל מקור ושרש הראשון לבירור והבדלה זו שיחיה האדם בנר\"נ שבו באו\"כ זהו הי' המן דוקא שז\"ש על כל מוצא פי ה', פי' על<sup data-n=\"10515\">387</sup> כל מוצא כו' כי מוצא פי הוי' דח\"ע הוא שנמשך מן ההעלם דח\"ס לגילוי באו\"כ דחו\"ב שהן תושב\"כ ושבע\"פ<sup data-n=\"10516\">388</sup> וזהו מצות דיבור בפה בד\"ת<sup data-n=\"10517\">389</sup> שיחי' האדם כמו אמרתך חייתני וכן כי הוא חייך ואורך ימיך כו' וחיים הם למוצאיהם בפה<sup data-n=\"10518\">390</sup> דוקא. אך מקור מוצא פי ה' שבתורה הוא בבחי' פנימי' דחכ'<sup data-n=\"10519\">391</sup> שהוא שרש המן שנק' לחם מן השמים דוקא כו', ונק' כל מוצא פי ה' שאינו בא בעונג מורגש גם בטעמי מצות שיתגלו בעוה\"ב אלא הוא בחי' ביטול והתכללות בעונג הפשוט הנעלם (שלמעלה גם מטעם כמוס לרצון כידוע) שלמעלה מחיי העוה\"ב בשכר המצות כנ\"ל, מזה יחיה האדם גם בבחי' נר\"נ שבו לברר לעה\"ד בתורה הנגלית וד\"ל (וזהו שבמוצא פי ה' בד\"ת גם בשבת מצוה כמו<sup data-n=\"10520\">392</sup> בחול<sup data-n=\"10521\">393</sup> כמ\"ש ודברת בם<sup data-n=\"10522\">394</sup> כו' אע\"פ שבא בהתלבשות בעה\"ד טו\"ר שהוא בחי' הבירורי' ובשבת בורר אסור כו', אמנם הרי מלובש בזה מבחי' העונג העליון הפנימי דעוה\"ב ביום שכולו שבת כו' וכסעודת השבת כו' ואדרבה ישבע בלחם דתו' ויתענג על ה' שבחכמה דתורה להמשיך חידוש השפע דחכמה דתורה על כל וי\"ו ימים דחול (כמו בחידוש בפנימי' התורה שהוא בשבת דוקא כנ\"ל) וראי' לזה ממה שהיו חכמי ישראל ראשי הדור דורשי' בכל שבת דוקא כמו שבת של מי היתה<sup data-n=\"10523\">395</sup> כו'). אבל המן לא ירד בשבת רק",[["10510","383","<b>טה\"ע</b>: ה: טל העליון."],["10511","384","<b>למען הודיעך</b>: ב: ליתא. ה: להודיעך."],["10512","*385","<b>בלחמה של תורה הנגלית שנק' לחם מן הארץ</b>: ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תתיז."],["10513","385","<b>ממלא כריס\"ו בתלמוד</b>: ראה אור נערב ח\"ג, פ\"א [ושם: למלא כריסו בדיני הגמרא]. ש\"ך שו\"ע יו\"ד סרמ\"ו, ס\"ו. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תקעה (נו\"ש). מאמרי אדה\"א ויקרא ח\"ב ע' תרפג. במדבר ח\"ב ע' תעב. לקמן פ' ויקהל תמא, א."],["10514","386","<b>ובינה ליבא</b>: ת\"ז בהקדמה (יז, א)."],["10515","387","<b>על</b>: בה: ליתא."],["10516","388","<b>דחו\"ב שהן תושב\"כ ושבע\"פ</b>: נסמן לעיל פ' בא צד, ד."],["10517","389","<b>מצות דיבור בפה בד\"ת</b>: נסמן לעיל פ' וארא פ, ג."],["10518","390","<b>וחיים הם למוצאיהם בפה</b>: משלי ד, כב. עירובין נד, א."],["10519","391","<b>דחכ'</b>: בה: (ד)ח\"ס."],["10520","392","<b>בד\"ת גם בשבת מצוה כמו בחול</b>: ראה גם פיה\"מ ספ\"ח (ה, ב). ספל\"ה (כ, ג). מאמרי אדה\"א נ\"ך ע' קנו. וש\"נ. לקמן פ' יתרו רסו, ב. ויקהל תטז, א. אוה\"ת נ\"ך כרך ג ע' א'קפט."],["10521","393","<b>בחול</b>: ה: בימות החול."],["10522","394","<b>ודברת בם</b>: ואתחנן ו, ז."],["10523","395","<b>שבת של מי היתה</b>: ברכות כח, א."]]],[2300540704,"למעלה בלבד במקומו<sup data-n=\"10524\">396</sup> ולא ירד המן מ[ן ה]שמים לארץ בהגשמה כלחם דתורה בנגלה וכמ\"ש שבת לא יהיה בו כו', מטעם הנ\"ל <span data-k=\"pg\">628</span> ּ שבשבת דוקא שהוא בפנימי' אבא שהוא פנימי' ע\"י עולה במקורו בעדן העצמי הנעלם שלא יבא במורגש כלל רק שנמשך ברכתו על כל הוי\"ו ימים בשמים העליונים כנ\"ל וד\"ל (רק שמתחדש השפע הפנימית דמן כמו<sup data-n=\"10525\">397</sup> למעלה ברוחניות [כמו בחי'] ההסתכלות כו' ברזין דאוריי' כנ\"ל). ועכ\"ז אמר במן למען אנסנו הילך כו' שהי' מקור הבירור דעה\"ד טו\"ר שע\"י התורה הנגלית בזמן ומקום לפי שנק' כל מוצא פי ה' שבתורה כו' (כמשה שהי' כבד פה ולשון בתושבע\"פ ושבכתב<sup data-n=\"10526\">398</sup> לפי שהי' מבחי' מ\"ע<sup data-n=\"10527\">399</sup> שמעל השמים כו', וגם במן א' שהי' כמו כפור דק<sup data-n=\"10528\">400</sup> כו' וחם השמש ונמס<sup data-n=\"10529\">401</sup> הרי הי' גליד[ת] מ\"ע דפנימי' ח\"ע שאינו נראה במציאות יש ודבר כלל בפ\"ע<sup data-n=\"10530\">402</sup> כו', וכמו טעם המתיקות שהחיך טועם ולא הפה ושיניים טוחני' כו' (והוא פנימי' העדן שאמר יעשה למחכה לו<sup data-n=\"10531\">404</sup> כמו נפשינו חכתה<sup data-n=\"10532\">403</sup> כו' וכמ\"ש במ\"א), [ו]עכ\"ז ירד המן להיות מקור לבירור דתו\"מ בכלל נש\"י בכל הדורות בכ\"א ימים שאכלו המן קודם מ\"ת שנבלע ברמ\"ח אברים כו' כמו שא' לא ניתנה [התורה] אלא לאוכלי המן<sup data-n=\"10533\">405</sup> דוקא, כי לח\"ם לאכול ובג\"ד ללבוש שהן התו\"מ<sup data-n=\"10534\">406</sup> בגשמיות שרשם נמשך מבחי' המזון דמן לעצם חיות הנשמות כנ\"ל שעי\"ז הי' בכח נר\"נ שלהם לברר לעה\"ד טו\"ר שבתו\"מ שנק' לחם לאכול ובגד ללבוש כידוע וד\"ל).\n<b>וזהו</b> ויברך אלקי' את יום הז' כו' ואמר בזהר מאי ברכתא הוי' כו'<sup data-n=\"10535\">407</sup> שלא ירד המן בשבת כו'. ולכאורה זהו דבר פלא איך יקרא מניעת יריד' השבע<sup data-n=\"10536\">408</sup> דמן מן השמים לארץ בשבת בשם ברכה אחר שהוא בחי' צמצום ומניעת השפע והברכה למטה כו'. אך הענין הוא דאדרבה ממה שלא ירד המן בשבת מורה על היות עיקר ומקור הברכה דשפע המן למעלה הוא ביום השבת דוקא דהיינו בחי' ברכה בראש, שזהו ענין ירידתו והמשכתו מלמעלה לשמים העליוני' בבחי' הרוחניות בשרש המן כמו שהוא במקומו בפנימי' דח\"ס הוא שנמשך בשבת להיות מזה בחי' הברכה בסוף<sup data-n=\"10537\">409</sup> שזהו בחי' ירידת בהגשמה למטה מן השמים לארץ בכל וי\"ו ימי החול. וז\"ש הוא אשר דבר ה' שבתון שבת קדש היום<sup data-n=\"10538\">410</sup> לה' כו' עד היום לא תמצאוהו בשדה למטה כי בשבת שנק' קדש העליון דפנימי' א\"ס<sup data-n=\"10539\">411</sup> כנ\"ל לא ירד המן בהגשמה מאין ליש בחיצוניות השפע כ\"א עיקר ירידתו הוא למעלה בפנימיות השפע ובכללו' על כל הוי\"ו ימים דחול, לפי שהשבת והמן שרשם א' הוא בבחי' פנימי' ומקור החכמה בבחי' אין דכתר שהוא בחי' טלא דבדולחא הנ\"ל שהוא",[["10524","396","<b>במקומו</b>: ה: במקורו."],["10525","397","<b>כמו</b>: ה: ליתא."],["10526","398","<b>כמשה שהי' כבד פה. . ושבכתב</b>: ראה גם לעיל פ' שמות מז, ד. וש\"נ."],["10527","399","<b>כמשה. . מ\"ע</b>: נסמן לעיל פ' שמות מג, א הערה 5."],["10528","400","<b>כמו כפור דק</b>: בשלח טז, יד."],["10529","401","<b>וחם השמש ונמס</b>: בשלח שם, כא."],["10530","402","<b>בפ\"ע</b>: בה: בפה."],["10531","404","<b>יעשה למחכה לו</b>: ישעי' סד, ג."],["10532","403","<b>שהחיך טועם. . נפשינו חכתה</b>: תהלים לג, כ. ראה ביאוה\"ז שמיני סה, ד. מאמרי אדה\"א במדבר ח\"ב ע' תג וע' תתלז. וש\"נ."],["10533","405","<b>לא ניתנה [התורה] אלא לאוכלי המן</b>: ראה מכילתא בשלח יג, יז. טז, ד."],["10534","406","<b>לח\"ם לאכול ובג\"ד ללבוש. . התו\"מ</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תתכ. וש\"נ. שע\"ת סח, ד ובהערה 18. לקמן פ' תצוה שלא, ב. ויקהל תיט, ד. תכא, רע\"ג."],["10535","407","<b>הוי' כו'</b>: בה: הוה בי'."],["10536","408","<b>השבע</b>: בה: השפע."],["10537","409","<b>ברכה בראש. . הברכה בסוף</b>: ראה גם בסמוך ד\"ה וזהו ענין. לקמן פ' ויקהל תיד, ד. מאמרי אדה\"א הנחות תקע\"ז ע' קל. וש\"נ."],["10538","410","<b>היום</b>: בה: ליתא."],["10539","411","<b>א\"ס</b>: שם: ח\"ס."]]],[2300540716,"למעלה מן ההשתל' דזמן ומקום כנ\"ל, וע\"כ שפע המן דוקא הוא שלא ירדה למטה בשבת משא\"כ שארי שפע חיצוניות דמע\"ב יורד ונמשך בשבת כמו בחול כנ\"ל הטעם וד\"ל.\n<b>(וביאור</b> הדברים הנה תחלה י\"ל בשרש בחי' השבת דהנה לכאורה עיקר בחי' השבת הוא ענין המנוחה והשביתה ששובת מכל השפעה למטה וכמ\"ש כי בו שבת<sup data-n=\"10540\">412</sup> כו' וא\"כ מהו שא' ויברך אלקים את יום הז' כו', הרי הברכה הוא ההשפעה למטה וכמו ברכת הארץ שתצמיח כל צמח ותבואה בריבוי גדול <span data-k=\"pg\">שיד</span> ּ ובשבת ה\"ז בבחי' או\"ח לעצמותו דוקא שהוא היפוך ירידה והמשכה. ואם מפני שביום השבת נמשך שפע כללית על כל הוי\"ו ימים כנ\"ל, ה[י]א גופא קשיא מאחר שעיקר בחי' השבת הוא רק העלי' וההסתלקות בעצמותו איך יומשך משבת גם ברכה ושפע כללית ליומין דחול כו'. ועוד י\"ל דהלא ידוע שהשבת נק' קד\"ש כמ\"ש ושמרתם את השבת<sup data-n=\"10541\">413</sup> כו'<sup data-n=\"10542\">414</sup> קד\"ש היא כו' וקדש הוא מלה בגרמי' דהיינו שהוא קדוש ומובדל מכל בחי' המשכה והשתלשלות ולכך נק' מל\"ה בגרמי' כידוע, והוא בחי' אי\"ן דח\"ע שנק' קדש העליון כו', וכמו שאו' המבדיל בין קד\"ש לחו\"ל<sup data-n=\"10543\">415</sup> והבדלה זו הוא ענין הקדושה דשבת כי כל קדושה הוא ענין הבדלה בערך כידוע, וא\"כ איך יומשך מקדש זה דשבת על כל וי\"ו ימים דחול מאחר שהבדיל בין הקדש ובין החול כו'. אך צ\"ל דעיקר בחי' קדושה והבדלה זו דשבת הוא דוקא בבחי' הפנימי' ועצמיות השפע שהוא בחי' פנימי' דח\"ע ופנימי' דרצון ותענוג העליון שאינו אלא בשבת דוקא ולא בחול, כי בשבת שובת ונח מכל שפע חיצוניות דחכ' ומדות דמע\"ב שכולם בחכמה עשית כו' שאינו אלא בבחי' חיצוניות דחו\"ב כו' כידוע, וע\"כ אומר[ים] אחר כלו\"ת יום השבת דוקא המבדיל בין קדש לחול מפני שאין בחי' פנימי דקדש העליון נמשך בחול כלל רק החיצוניות וכו'. אך עכ\"ז נמשך ביום השבת דוקא ברכה כללית על כל הו' ימים דחול, ואע\"פ שעיקר ברכה זו דשבת א' ויברך את יום הז' כו' זהו דוקא בבחי' הפנימי' כנ\"ל ולא בחיצוניות כלל. אמנם הא בהא תליא דכאשר יש ברכה ושפע פנימי' בשבת עצמו שנק' קדש מלה בגרמי' כנ\"ל אזי נמשך מזה שפע וברכה החיצוניות על כל הוי\"ו ימים דחול אחר ההבדלה בין קדש לחול דוקא שזהו ההבדלה בין פנימי' לחיצוניות.\n<b>וזהו</b> ענין ברכה בראש וברכה בסוף, דברכה בסוף בחיצוניות תלוי' בברכה בראש דח\"ע הפנימי' דוקא, וכמשל הרב המשפיע חכמה ושכל לתלמידיו שאין שפע זו רק בחי' החיצוניות שבא ע\"י צמצום אור עצם חכמתו כו')<sup data-n=\"10544\">416</sup>, וצ\"ל בחי'",[["10540","412","<b>כי בו שבת</b>: בראשית ב, ג."],["10541","413","<b>ושמרתם את השבת</b>: תשא לא, יד."],["10542","414","<b>כו'</b>: בה: כי."],["10543","415","<b>המבדיל בין קד\"ש לחו\"ל</b>: נוסח הבדלה."],["10544","416","<b>כו')</b>: בה: כו'."]]],[2300540728,"הבדלה בין זל\"ז שנק' צמצום דאל\"כ לא הי' יכול לבוא להמשכה ושפע חיצוניות זו כי בחי' הפנימי' שבו א\"א לירד למקבלים כלל (וכמו דלא קאים<sup data-n=\"10545\">417</sup> אדעתי' דרבי'<sup data-n=\"10546\">418</sup> כו'), וכל זמן שעסוק וטרוד בפנימי' החכמה כמו שהוא בעצמו לא הי' יכול לבא להשפעה זו החיצוניות רק ע\"י הבדלה וצמצום כו'. ועכ\"ז אינו משפיע שפע החיצוניות של החכמה כ\"א כאשר נתברך תחלה בעצמו בפנימי' השפע דחכמה כענין ברכות לראש צדיק<sup data-n=\"10547\">419</sup> כו' כמ\"ש בזהר דזהו בחי' ברכה בראש צדיק שנמשך עי\"ז ברכה בסוף שז\"ש ברכות כו' (כענין אגברא חמרא<sup data-n=\"10548\">420</sup> כו' כי היכי דלימרו מלתא כו') שכאשר אינו מתברך ברוב שפע הפנימי' בעצמו לא יתצמצם להשפיע למקבלים לפי ערכם כידוע וד\"ל. וכך יובן כאן בענין ברכה פנימי' בראש דח\"ע שנתברך בפנימי' ומקורא דכולא כמ\"ש ויברך אלקי' את יום הז' שהוא <span data-k=\"pg\">630</span> ּ בחי' החכ' הפנימי' בחי' חכמה שבכתר כנ\"ל אז עי\"ז יומשך שפע וברכה בסוף בחיצוניות על כל הוי\"ו ימים דחול דהא בהא תליא כנ\"ל. ובזה יתורץ הקושיא דלעיל דאע\"פ שהשבת נק' קדש מלה בגרמי' ואו' הבדלה שמבדיל בין קדש לחול כנ\"ל עכ\"ז מקור הברכה דחול נמשך ביום השבת דוקא לפי שהשבת נתברך בברכה הפנימי' לעצמו וד\"ל.\n<b>אך</b> עדיין אין זה מובן דמאחר שעיקר בחי' השבת הוא בחי' או\"ח לעצמותו ממש כנ\"ל שהוא היפוך השפע והברכה לגמרי אפי' בדרך כלל א\"כ איך עיקר ומקור הברכה דחול נמשך בשבת הרי גם מקור ברכה זו שייך לחול דוקא וא\"כ למה נק' קדש מלה בגרמי' כו' ואין כאן הבדלה בין קדש לחול כו'. ועוד י\"ל דאם ימי החול צריכים לקבל דוקא מיום השבת איך הי' ענין ההמשכה דוימ\"ב הראשונים שלא הי' יום שבת מקודם כי לא הי' מלאכ' והמשכ' שיהי' נק' שביתה ומאין קיבלו וימ\"ב מקור הברכה הכללי' שלהם כו' (ואע\"פ שגם עכשיו בכ\"י מחדש מע\"ב כמו [ב]וימ\"ב הראשוני' וכל שבת נקרא שבת בראשית כמשי\"ת מ\"מ כל שבת נק' מקור הברכה דוי\"מ החול שאחריו). אמנם כ\"ז יובן בהקדים תחלה להבין שרש ענין הברכה בראש הנ\"ל במ\"ש ויברך את יום הז' ה\"ז בבחי' הפנימי' כו', דהנה ענין ברכה פנימי' זו היינו ממקורא דכולא שהוא בחי' עצמו' אור א\"ס ממש כמו שהוא קודם הצמצום הראשון הנק' מקו\"פ<sup data-n=\"10549\">421</sup> כו'. וז\"ש ברכת ה' היא תעשיר<sup data-n=\"10550\">422</sup> כו' עושר העליון דא\"ס עצמו שהוא בלתי גבול כלל כמו שיהי' בעוה\"ב שנק' יום שכולו שבת<sup data-n=\"10551\">423</sup> בחי' מנוחה לחה\"ע כו' שזהו בחי' מנוחה עצמי'<sup data-n=\"10552\">424</sup> (ולא מנוחה מן המלאכה והמשכה כלל כמ\"ש במ\"א<sup data-n=\"10553\">425</sup>. וכך הי' קודם שעלה ברצה\"פ להאציל ולברוא בחכמה כו' שהיו כל הע\"ס דאבי\"ע",[["10545","417","<b>דלא קאים</b>: ב: ניתוסף: אינש. ה: ניתוסף: עד מ\"ם שנין."],["10546","418","<b>דלא קאים. . דרבי'</b>: ראה ע\"ז ה, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. הנחות תקע\"ז ע' קמג. וש\"נ. שה\"א צב, ב. לקמן פ' ויקהל תכד, סע\"ב ואילך."],["10547","419","<b>ברכות לראש צדיק</b>: משלי י, ו. ראה זהר ויצא קסב, א. רע\"מ עקב רעא, א. ש\"א כ, א."],["10548","420","<b>אגברא </b>[בה: אגברו]<b> חמרא</b>: נסמן לעיל פ' בא צו, א."],["10549","421","<b>הצמצום הראשון הנק' מקו\"פ</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א, ענף ב."],["10550","422","<b>ברכת ה' היא תעשיר</b>: משלי י, כב. ראה שע\"ת סו, א ואילך ובהנסמן במ\"מ לשם."],["10551","423","<b>בעוה\"ב שנק' יום שכולו שבת</b>: ראה תמיד בסופה. מכילתא תשא לא, יג. מאמרי אדה\"א דברים ח\"ד ע' א'קפ. וש\"נ."],["10552","424","<b>מנוחה עצמי'</b>: ראה גם מאמרי אדה\"ז תקס\"ו ע' רנט. תקס\"ח ח\"א ע' תקלג. שע\"ת צז, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תקמח."],["10553","425","<b>במ\"א</b>: כנצ\"ל: במ\"א)."]]],[2300540740,"כלולים בעצמות ממש בלי ניכר למהות דבר מה ונק' ע\"ס בלי מ\"ה כנ\"ל, שזהו בחי' ההתכללות האמיתי דע\"ס בעצמות המאציל דלאו דאית לי'<sup data-n=\"10554\">426</sup> מכל אינון מדות כלל אפי' בהעלם כו'. ואמנם גם לאחר שנמשך ע\"י צמצום הראשון בקו\"ח הע\"ס דאצי' ובריאה כו' עד מע\"ב דעולם העשי' הגשמיי' [ו]כאשר כלה כל מלאכת[ו] ביום הוי\"ו שנא' ויכולו השמים<sup data-n=\"10555\">427</sup> כו' ויכל אלקים<sup data-n=\"10556\">428</sup> כו' שזהו בליל שבת דוקא שעלה הכל בבחי' או\"ח אל העצמו' כמ\"ש כי בו שבת וינפש, דהיינו שבחי' מהו\"ע ית' ממש כמו השובת ממלאכתו שגם פנימית רצונו וחכמתו שהי' בצמצום מלאכה זו עולה ונכלל בעצמו' הנפש ממש, שזהו כמו שהי' הוא ושמו בלבד<sup data-n=\"10557\">429</sup> קודם הצמצום הראשון, אז עי\"ז דוקא חוזר ונמשך המשכה וברכה עליונה שנק' ברכת הוי' כו' ביום השבת שנק' ברכה בראש הפנימי' הנ\"ל שהוא בפנימי' דח\"ע ורצון ותענוג העליון מעצמו' הא\"ס ממש כו' וכמ\"ש ויכולו השמים כו' וישבות כו' אז דוקא ויברך אלקי' את יום הז', דברכה זו אינו אלא אחר ההעלאה והתכללו' דאו\"ח בתחלה בעצמו' כמשמעות הפשוט דויברך אלקי' כו' כי בו שבת וינפש ע\"כ <span data-k=\"pg\">שטו</span> ּ בירך אלקים ליום הז' כו' וד\"ל. ומזה יובן דזהו דוקא מצד [ה]מנוחה ושביתה מן המלאכה לפי שעולה בבחי' או\"ח לעצמותו ובא הברכה ליום השבת תחלה כו', אבל קודם שעלה ברצונו הפשוט להאציל ולברוא כו' שהי' כל הע\"ס בביטול במציאות בעצמותו ממש כנ\"ל גם הרצון הפנימי' כו' ונק' מנוחה עצמי' כנ\"ל, א\"כ הברכה שנמשך מעצמותו דהיינו מקדושת עצמותו אחר ההבדלה בין קדש כו' שהוא צמצום הראשון הי' ג\"כ בדרך כללות תחלה על כל וימ\"ב ממנוחה העצמי', ולא יתכן לומר שיברך לשבת תחלה מאחר שאינו שובת ממלאכה כלל והוא בחי' מחשבה הכללי' שכוללת כל וא\"ש דהוי עלמא ואח\"כ נתחלק בדרך פרט כמו בכל וי\"ו יומין דחול שמתחלקים מכללות דיום השבת כו' (וזהו בחי' התכללות הב' שכולל כל הע\"ס ונק' ע\"ס הגנוזות [בהעלם] דמח' אחת<sup data-n=\"10558\">430</sup> כו'). ואע\"פ שזהו צמצום וירידה מן העצמות גם להיות המשכה כללי' זאת דמח' אחת מ\"מ מתאחדת מחשבה זו הכללי' בעצמותו והוא ענין הברכה הפנימי' שנמשך לבחי' חכמה בראש ביום הז' כמו בעוה\"ב שנק' ברכת ה' היא תעשיר כנ\"ל וד\"ל.\n<b>ונמצא</b> שיש ב' ברכות בשבת, א' ברכה בראש בח\"ע הפנימי' מעצמו' המאציל דלית מחשבה תפיסא בי' כלל<sup data-n=\"10559\">431</sup> אפי' מח' הקדומה [כו'], והב' ברכה בסוף שהוא המשכה הכללי' לוי\"ו יומין דחול ובכלל לוא\"ש כו'. ובכ\"ז יתורץ הקושיא הנ\"ל דאדרבה שמפני שהשבת הוא בבחי' או\"ח לעצמו' ע\"כ נמשך",[["10554","426","<b>דלאו דאית לי'</b>: ב: דלאו דאית. ה: דלאו — ראה ת\"ז בהקדמה (יז, ב)."],["10555","427","<b>ויכולו השמים</b>: בראשית ב, א."],["10556","428","<b>ויכל אלקים</b>: שם ב, ב."],["10557","429","<b>שהי' הוא ושמו בלבד</b>: נסמן לעיל פ' וארא נג, ב."],["10558","430","<b>דמח' אחת</b>: נסמן לעיל קסג, ג."],["10559","431","<b>דלית מחשבה תפיסא בי' כלל</b>: ראה ת\"ז בהקדמה (יז, א)."]]],[2300540752,"המשכה הכללי' לוימ\"ב בכלל וכן בכל שבת, ואע\"פ ששייך לחול מ\"מ מתאחד בעצמו' וצ\"ל הבדלה בין קדש לחול בליל מ\"ש. וכך הוא בענין הברכה הכללי' בוימ\"ב בוא\"ש כו'. ומתורץ ג\"כ הקושיא הב' בוימ\"ב הראשונים דאע\"פ שלא הי' בבחי' או\"ח ושביתה תחלה נמשך המשכה דמחשבה א' הכללי' ממנוחה העצמי' מצד כי חפץ חסד הי'<sup data-n=\"10560\">432</sup> וצדיק ה' צדקות אהב<sup data-n=\"10561\">433</sup>, וז\"ש ברכות לראש צדיק בכלל וד\"ל) (ואמנם בזה יש הפרש בין ברכה כללי' דשבת בראשית שאינו רק לוי\"ו ימי' דחול ולו\"א שני' בכלל [ו]בין ברכת ה' תעשיר דלע\"ל באלף הז' דעוה\"ב שהוא המשכה חיי' נצחי' דא\"ס עצמו שנק' חיי עולם כידוע, ובכל שבת יש מיום שכולו שבת דעוה\"ב ע\"כ א' ויקדש אותו בקדושת העצמו' דא\"ס דעוה\"ב שגם הברכה הוא בבחי' עושר דא\"ס בלתי גבול, וזהו ברכה בסוף שנמשך מברכה בראש דעצמות ממש וד\"ל. וזהו איהו ברוך ואיהי ברכה<sup data-n=\"10562\">434</sup>, דשבת נק' ברכה שמקבל[ת] [מ]ברכת הוי' דעצמות א\"ס שנק' ברוך בעצם כמו והמלך שלמה ברוך<sup data-n=\"10563\">435</sup> לשון נפעל כמ\"ש במ\"א בפי' הקב\"ה, וכאן הזכיר הברכה קודם הקדושה כמ\"ש ויברך אלקים את יום הז' ואח\"כ ויקדש אותו דאע\"פ שהשבת נק' קדש מצד עצמו כמ\"ש כי קדש הוא כו', אבל לאחר הברכה מן העצמות כנ\"ל [א'] ויקדש אותו בקדוש' העצמו' דא\"ס כמו שיהי' בעוה\"ב, והטעם לברכה וקדושה זו כי בו שבת כו'. ואע\"פ ששביתה זו מן המלאכה ואין לה ערך כלל <span data-k=\"pg\">632</span> ּ לבחי' המנוחה העצמי' דעוה\"ב שלמעלה מן השביתה דוא\"ש כו', מ\"מ הא בהא תליא לפי שבחי' העליי' דאו\"ח דוימ\"ב הוא שעולה בבחי' העצמות ממש (כמשי\"ת) וד\"ל.\n<b>(ולפי\"ז</b> הרי יובן דגם בתחלת ההשתלשלו' דוימ\"ב הראשוני' שלא הי' [ע\"י] בחי' או\"ח כלל רק ע\"י בחי' חפץ חסד מעצמו שמטבע הטוב להטיב כמ\"ש בע\"ח<sup data-n=\"10564\">436</sup> הי' נמשך הברכה בכלל [ל]וימ\"ב ואח\"כ נתחלקו כל יום בפ\"ע כו', שזהו מצד בחי' הברכה בראש שמצד העצמות ממש (כמשל הרב המשפיע או המלך בעת ריבוי התענוג והחסד בעצמו, ע\"כ מתעורר להטיב שיהי' עולה ברצונו להאציל ולברוא בכלל כמו שאו' ברוך שאמר כו'<sup data-n=\"10565\">437</sup> ע\"י שהוא ברוך בעצמו אמר ברצונו<sup data-n=\"10566\">438</sup> הפשוט בכלל שיצא מן ההעלם דעצמו' לידי גילוי והי' העולם בכלל שהוא הברכה לוימ\"ב בכלל, ואח\"כ [מ]תחלק כל רצון ורצון בפרט כו' מדת רצון<sup data-n=\"10567\">439</sup> של חסד ביום א' במאמר יהי אור<sup data-n=\"10568\">440</sup> ורצון של דין במאמר יהי רקיע<sup data-n=\"10569\">441</sup> ביום הב' כו', וכה\"ג בוא\"ש אלף הא' בבחי' החסד<sup data-n=\"10570\">442</sup> כו' כידוע וכמ\"ש ברכות לראש צדיק כנ\"ל (אך מה שברכה זו בסוף רק לוימ\"ב לבד זהו הי' ע\"י צמצום בעצמו משא\"כ בעוה\"ב וד\"ל) (וזהו השמים מספרים<sup data-n=\"10571\">443</sup> כו' בחי'",[["10560","432","<b>כי חפץ חסד הי' </b>[בה: הוא]: מיכה ז, יח."],["10561","433","<b>וצדיק ה' צדקות אהב</b>: תהלים יא, ז."],["10562","434","<b>איהו ברוך ואיהי ברכה</b>: נסמן לעיל קלד, ג."],["10563","435","<b>והמלך שלמה ברוך</b>: נסמן לעיל קס, ג."],["10564","436","<b>שמטבע הטוב להטיב כמ\"ש בע\"ח</b>: נסמן לעיל פ' שמות לד, ג."],["10565","437","<b>כו'</b>: ה: והי' העולם בכלל."],["10566","438","<b>ברוך. . אמר ברצונו</b>: ראה גם לעיל פ' בא קכו, ב. וש\"נ."],["10567","439","<b>כו' מדת רצון</b>: ה: בוי\"ו מדות ורצון."],["10568","440","<b>חסד. . יהי אור</b>: ראה סידור שער הק\"ש עו, ב. ש\"א פ, א. שעה\"י קמד, א ובהערה 9. לקמן פ' ויקהל תיז, ג. תכה, ד."],["10569","441","<b>דין. . יהי רקיע</b>: בראשית א, ו. ראה גם ש\"א שם. לקמן שם."],["10570","442","<b>אלף הא' בבחי' החסד</b>: נסמן לעיל פ' שמות טו, ג הערה 668."],["10571","443","<b>השמים מספרים</b>: תהלים יט, ב."]]],[2300540764,"טה\"ע<sup data-n=\"10572\">444</sup>, שהוא מה ששיער בעצמו בכח בהעלם מה שיבא בפועל בקו\"ח להאציל ולברוא כו' ושם הוא בבחי' ההתכללו' כל הע\"ל<sup data-n=\"10573\">445</sup> בגילוי דקו\"ח כמ\"ש גליף גליפו כו' וכמ\"ש יום ליום יביע אמר אין אמר ואין דברים כי הכל כלול בהעלם העצמות רק בכל הארץ ע\"י צמצום דמל' דא\"ס הוא שיצא קום לבד שהוא בחי' קו\"ה<sup data-n=\"10574\">446</sup> דקו\"ח שיהי' התחלקות דע\"ס באו\"כ שזהו התחלקות שאחר ההתכללו' כנ\"ל וד\"ל).\n<b>וזהו</b> שא' ויברך אלקים כו' דזהו מה שלא ירד המן בשבת דמזה הי' הוראה גמורה שהי' ביום השבת עיקר הברכה הכללית על כל הוי\"ו ימים כמו ביום השבת שכללו' ההמשכ[ה] על כל הוי\"ו ימים דחול נמשך בשבת דוקא. וזהו ויברך אלקים כו' והוא עצמו למעלה מבחי' השפעה והמשכה למטה כי נק' קדש מלה בגרמי' כנ\"ל, ומ\"מ ממנו נמשך מקור ההמשכה למטה (ע\"י הבדלה בין קדש לחול בין יום הז' שמטעם זה קבעו הבדלה לומר בחונן הדעת מפני שאם אין דעת אין הבדלה מטעם הנ\"ל). וכמו\"כ בירידת המן הי' בשבת במקורו למעלה על כל הוי\"ו ימי' דחול כנ\"ל דהשבת והמן שרשם א' הוא בפנימי' דח\"ס שלמעלה מן הזמן שמשם דוקא נמשך בהתחלקו' הזמן בפרטי הוי\"ו ימים בכל יום בפ\"ע וכמ\"ש ולקטו דבר יום ביומו<sup data-n=\"10575\">447</sup> דוקא, וע\"כ נאמרו שבת ומן בענין א' וכמ\"ש הוא אשר דיבר ה' שבת<sup data-n=\"10576\">448</sup> שבתון שבת קדש לה' כו' וד\"ל (אך א\"כ הי' ראוי שיאמר הוא אשר דיבר ה' בברכה דשבת שא' ויברך אלקי' את יום הז' כו' ומה זה שתלה דבר זה במניעת שפע ירידת המן בשבת בבחי' הקדושה דשבת כמ\"ש [הוא] אשר דיבר ה' שבתון כו'<sup data-n=\"10577\">449</sup> קדש לה', דהקדושה הוא בחי' ההבדלה לגמרי כנ\"ל בקדש דשבת <span data-k=\"pg\">שטז</span> ּ שנק' מלה בגרמי' כנ\"ל וד\"ל. וצ\"ל דהברכה והקדושה הזאת הכל ענין א' והא בה\"ת<sup data-n=\"10578\">450</sup> מטעם הנ\"ל וד\"ל.\n<b>אך</b> פי' הפשוט הוא דמטעם הקדושה דשבת דוקא הוא שלא הי' ירידת שפע המן בשבת כמ\"ש שבת לא יהי' בו<sup data-n=\"10579\">451</sup> כו', כי שרש המן הוא בבחי' הפנימי' דח\"ע כנ\"ל ועיקר קדושת דשבת הוא בבחי' הפנימי' דוקא ולא בבחי' החיצוניות שהרי בבחי' החיצוניות נמשך השפע במע\"ב בשבת כמו בחול מבחי' חיצוניות דחכמה כנ\"ל. וז\"ש כי בו שבת מכל מלאכתו כו' ואע\"פ שמוריד גשמים ומצמיח תבואות בשבת וכל בריאת העולמות מאין ליש מתחדש בשבת כמו בחול זהו הכל בחיצוניות השפע כנ\"ל (אבל מה שנמשך השפע בכללות על כל הוי\"ו ימים הוא בבחי' פנימי' דוקא שמפני זה צ\"ל הבדלה בין קדש לחול אחר השבת כנ\"ל), כי בבחי' הפנימי' דוקא הוא שעולה בבחי' או\"ח לעצמותו כו',",[["10572","444","<b>השמים. . טה\"ע</b>: ראה גם שע\"ת כב, ד. ש\"א מח, א. תו\"ח ויגש רל, ד ובהערה 42."],["10573","445","<b>הע\"ל</b>: ה: העתיד לבוא."],["10574","446","<b>קו\"ה</b>: ב: קו המדה."],["10575","447","<b>ולקטו דבר יום ביומו</b>: בשלח טז, ד."],["10576","448","<b>הוא אשר דבר ה' שבת </b>[בה: ליתא]: בשלח שם, כג."],["10577","449","<b>כו'</b>: בה: שבת."],["10578","450","<b>בה\"ת</b>: ב: בהא תליא."],["10579","451","<b>שבת לא יהי' בו</b>: בשלח טז, כו."]]],[2300540776,"וע\"ז<sup data-n=\"10580\">452</sup> לא הי' עיקר האות ומופת לקדושה זאת כ\"א ממה שלא ירד המן בהגשמה למטה בשבת כמו בחול אע\"פ שבבחי' החיצוני' יורד השפע בעולמות בשבת כמו בחול והי' ראוי שגם המן ירד למטה בחיצוני' בשבת כמו בחול כשאר שפע החיצוני', אך מפני שהמן גם בירידתו למטה בארץ בהגשמה הי' כולו בחי' פנימי' שהרי הי' נבלע ברמ\"ח אברים כו' וכתי' בי' וחם השמש ונמס כו' כנ\"ל, ע\"כ גם בבחי' החיצוני' לא ירד המן בשבת כי הרי הוא בבחי' קדש העליון דפנימי' ח\"ע דהיינו שרש [בחי'] השבת כנ\"ל. ועכ\"ז הרי ברכה כללי' דירידת המן בשבת על כל הוי\"ו ימים כמו ברכה כללית דשבת על כל הוי\"ו ימים דחול שזהו בבחי' הפנימי' והרוחניות דהיינו לבחי' שמים העליונים כנ\"ל לפי ששרש המן והשבת א' הוא בפנימי' דח\"ע כנ\"ל. וז\"ש הוא אשר דבר ה' שבתון שבת קדש לה' כו' דמצד בחי' הקדושה דשבת דוקא הוא שלא יהי' ירידת המן למטה גם בחיצוניות שזהו עיקר המופת לבחי' הקדושה דשבת משא\"כ שאר שפע ששרשו מבחי' החיצוני' שנמשך בשבת כמו בחול כנ\"ל וד\"ל (כי לא הי' התגשמו' המן בדרך צמצום וחידוש מאין ליש שזהו בחי' החיצוני' דחכמה אלא כמו שהוא למעלה ממש בבחי' אין דחכמה רק שבא בדרך התלבשות למטה ככפור כו' וע\"כ וחם השמש ונמס (ועכ\"ז בא בהתלבשו' למטה למזון גשמי דנר\"נ דבנ\"י שיהי' להם כח לברר לעה\"ד טו\"ר כנ\"ל כמ\"ש למען אנסנ\"ו הילך כו', וזה לא נק' חיצוניות כלל שהי' יורד גם בשבת כמזון דתורה שיורד בשבת כנ\"ל אלא הוא שרש ומקור לבירור זה החיצוני' דעה\"ד כו') (ומפני שהוא עכ\"פ מקור לבירור דעה\"ד והוא כולו פנימי' ע\"כ לא ירד בשבת, ועכ\"ז אכלו המן בשבת כסעודת השבת דעכשיו ממה שירד ביום הוי\"ו שהוא שנק' העלא' ולא בירור דבורר אסור בשבת רק מי שטרח בע\"ש כו' כידוע וד\"ל).\n<b>והנה</b> עדיין יש להבין בטעם ענין המשכה הכללי' בשבת על כל הוי\"ו ימים שאחריו וכמו\"כ בשפע המן כנ\"ל, [מ]אחר שעיקר בחי' השבת אינו אלא השביתה מן העבודה ומלאכה דשבוע העבר והשביתה הוא בחי' או\"ח בבחי' העלי' אל העצמו' דוקא ואיך יהי' מזה היפוכו בחי' הירידה <span data-k=\"pg\">634</span> ּ וההמשכה על וימ\"ש<sup data-n=\"10581\">453</sup> הבאים, ומשמעות הכתובים מורים שמסיבת השביתה דוקא באה ההמשכה והברכה לשבוע הבאה כמ\"ש וישבות ביום הז'<sup data-n=\"10582\">454</sup> כו' על כן ויברך אלקי' כו' וכן למקראי קדש<sup data-n=\"10583\">455</sup> כו' כי בו שבת כו'. אך הנה אנו אומרים בקידוש דליל שבת אשר קדשנו במצותיו כו' ושבת קדשו באהבה וברצון הנחילנו זכרון למע\"ב תחלה למקראי קדש כו', דמ\"ש וש\"ק הנחילנו זהו מה שא' מתנה טובה יש לי בבית גנזי ושבת שמה<sup data-n=\"10584\">456</sup> והנחילה לישראל",[["10580","452","<b>וע\"ז</b>: ה: וע\"כ."],["10581","453","<b>וימ\"ש</b>: ב: ששת ימי השבוע."],["10582","454","<b>וישבות ביום הז'</b>: בראשית ב, ב."],["10583","455","<b>למקראי קדש</b>: בה: ויברך אלקים."],["10584","456","<b>מתנה טובה. . ושבת שמה</b>: שבת י, ב."]]],[2300540787,"דוקא, ומה שנק' זכרון למע\"ב זהו לפי שבכל שבת ושבת מתחדש השפע ממקורא דכולא על שבוע הבאה כמ\"ש ויברך אלקי' את יום הז' כו', וזהו זכרון למע\"ב בכל שבת כמו שבת בראשית כו', ואח\"כ א' תחלה למקראי קדש שזהו בחי' קדושת השבת שא' ויקדש אותו שהוא ראש ותחלה לכל מקראי קדש דיו\"ט כו'. והענין הוא כידוע דחידוש השפע מאין ליש הוא בכל יום ויום כמ\"ש ובטובו מחדש בכ\"י מע\"ב<sup data-n=\"10585\">457</sup> כמו בוימ\"ב הראשונים ממש, וע\"כ כל שבוע באה במספר הימים מחדש מיום הא' עד יום הז' שהוא יום השבת שנק' יום השביעי לעולם גם עתה בכל שבוע, אע\"פ שלפי מספר הימים והשנים מתחלת וימ\"ב הרי כבר עברו וחלפו כמה ריבוי שבועות בכל שנה ושנה והי' מהראוי לפי מספר הימים בכל שנה שיקרא רק יום השבת הראשון יום הז' לתחלת מע\"ב אבל יום השבת הב' שאחריו יקרא יום י\"ד ויום השבת הג' יום ך\"א לתחלת הבריאה, ועד\"ז כל שבתות השנים כו' (ואיך יקרא כל שבת<sup data-n=\"10586\">458</sup> ) עד מלאת נ' שבתות שהן שני'<sup data-n=\"10587\">459</sup> ימי' וכה\"ג הנוסף מדי שנה ימצא ריבוי המספר דימים [מ]זמן תחלת הבריאה כמו שסופרי' השני' כו' ואיך יקרא כל שבת ושבת יום הז' גם השבת האחרון שבכלות כמה אלפים שנים כעכשיו. אמנם מזה יש להוכיח הוכחה והוראה גמורה שמתחדש השפע בכל העולמות בכל יום ויום כימי בראשית ע\"כ כל שבת נק' יום הז' לתחלת הבריאה כמו שבת בראשית ממש, דהיינו שבו שובת ונח מכל מלאכתו אשר עשה בו' ימים הללו מיום הא' דשבוע זו עד יום הוי\"ו מאחר שמתחדש בכל יום ויום מע\"ב, והן הי\"מ שנאמרו כבר בוימ\"ב הראשוני' הוא שנתחדשו מאין ליש באותו מאמר עצמו שהי' כבר כמו מאמר יהי אור שהי' ביום א' דמע\"ב הוא שנמשך מחדש בכל יום א' דכל שבוע ושבוע וכן מאמר הב' דיהי רקיע בכל יום ב' דכל שבוע, וכה\"ג בכל המאמר[ות] בכל פרטי צירופיהם שהמה מתחדשי' בכל יום לכל התהוות הברואי' דדצח\"מ וד\"י ארמ\"ע<sup data-n=\"10588\">460</sup> וכן בעולמות העליוני' הרוחניי' כידוע, עד יום הששי שנאמר בו ויכולו השמים והארץ כו' שחוזר כל פנימי' האור וחיות האלקי שבכללות כל מע\"ב שנתחדשו בכל ימי השבוע הזאת למקורא דכולא כמ\"ש ויכל אלקים כו' וישבות כו' כי בו שבת כו' כאדם שנח ושובת מן המלאכה שחוזר כח ההתפשטו' (הפנימי' שבה<sup data-n=\"10589\">461</sup> ) למקורו בזו\"ר<sup data-n=\"10590\">462</sup> כו' ונק' נייחא דרוחא (ואע\"פ שלא יתכן לומר למעלה בעצמו'<sup data-n=\"10591\">463</sup> א\"ס ב\"ה ענין יגיעה ועייפות <span data-k=\"pg\">שיז</span> ּ עד שיצטרך למנוחה ושביתה כמ\"ש לא ייעף ולא ייגע<sup data-n=\"10592\">464</sup> כו', דברה תורה<sup data-n=\"10593\">465</sup> כו'<sup data-n=\"10594\">466</sup> כל' בנ\"א, שזהו שא' לעולמו די<sup data-n=\"10595\">467</sup> להגביל ולצמצם האור ושפע אלקי' שיחזור למקורו ושרשו כו', כי כל יכול הוא ויש בכח הא\"ס גם בחי' הדין והצמצום להגביל האור<sup data-n=\"10596\">468</sup> ושפע והוא בחי' שם שדי שא'",[["10585","457","<b>כמ\"ש ובטובו מחדש בכ\"י מע\"ב</b>: עד\"ז הובא בכ\"מ ומהם בש\"א כה, א ובהערה 18 — ראה ברכת יוצר. וראה גם מאמרי אדה\"א דברים ח\"א ע' רסו ואילך ובהנסמן בריש המאמר שם."],["10586","458","<b>השנים כו' (ואיך יקרא כל שבת)</b>: בה: שנה."],["10587","459","<b>שני'</b>: בה: שס\"ה. ואוצ\"ל: ש\"נ."],["10588","460","<b>ארמ\"ע</b>: נסמן לעיל פ' שמות ה, ד."],["10589","461","<b>(הפנימי' שבה)</b>: ב: ליתא. ה: הפנימי' שבה."],["10590","462","<b>בזו\"ר</b>: בה: בנפש ורוח."],["10591","463","<b>בעצמו'</b>: ב: באור."],["10592","464","<b>לא ייעף ולא ייגע</b>: ישעי' מ, כח."],["10593","465","<b>דברה תורה כו' כל' בנ\"א</b>: נסמן לעיל פ' שמות לט, א."],["10594","466","<b>כו'</b>: ב: חסר. גה: ליתא."],["10595","467","<b>שא' לעולמו די</b>: נסמן בהערה 469."],["10596","468","<b>בכח הא\"ס. . להגביל האור</b>: ראה עבודת הקודש — לר\"מ בן גבאי — ח\"א רפ\"ח. דרך אמונה — להנ\"ל — רפ\"ב [קה\"ת תשמ\"ח ע' יג]."]]],[2300540798,"לעולמו די<sup data-n=\"10597\">469</sup> כמ\"ש במ\"א, והן הן גבורותיו<sup data-n=\"10598\">470</sup> (ותיפח רוח האפיקורסים שהן מקשי' מפסוק זה דלא ייעף כו' על ענין המנוחה דשבת<sup data-n=\"10599\">471</sup> שאינו כפשוטו, וכל המאמין כפשוטו נותן הגשמ' באלקות בתואר אדם בע\"ג, דודאי כפשוטו הוא וכנ\"ל וכידוע בס' הקבלה).\n<b>והנה</b> ארז\"ל אלמלא שמרו ישראל<sup data-n=\"10600\">472</sup> ב' שבתות כהלכתן מיד היו נגאלין כו', ופי' ב' שבתות היינו בכל שבת ושבת יש ב' שבתות והיינו ליל שבת שנק' שבת דמעלי שבתא ושבת היום<sup data-n=\"10601\">473</sup> שבת תתאה ושבת עילאה<sup data-n=\"10602\">474</sup> כידוע בזהר. וזהו כהלכתן דוקא דשבת תתאה זהו בחי' העלייה דאו\"ח שעולה כל ההתפשטו' דחכ' ומדות שבי\"מ במע\"ב בכלות יום הוי\"ו שא' ויכל אלקים כו' שנק' הילוך מלמטה למעלה עד רום המעלות במהו\"ע ית' ממש כמו כי בו שבת וינפש כו' כנ\"ל, ובחי' העלאה זו עצמה בליל שבת בשביתה הוא דוקא שגורם בחי' הירידה וההמשכה למטה ביום השבת על כל הוי\"ו ימים דלהבא, וכמ\"ש וקראת לשבת עונג בחי' קריאה זו היינו בחי' ההמשכה דעונג העליון בחכמה ומדות במע\"ב בבחי' או\"ח ממש והוא שנק' הילוך מלמעלה למטה. וז\"ש כהלכתן ב' מיני הילוך הללו דאו\"ח ואו\"י דהא בהא תליא דוקא, וכידוע הכלל דכל בחי' העלאה גורם בחי' המשכה<sup data-n=\"10603\">475</sup> כמו בחי' רצוא ושוב, דבחי' הרצוא בבחי' או\"ח הוא שגורם בחי' השוב דאו\"י מלמעלה למטה (וההעלאה הי[א] מכל ו' הימים שעברו ע\"כ גורם ההמשכה ג\"כ על הוי\"ו ימים הבאים לחדש מע\"ב באור חיים<sup data-n=\"10604\">476</sup> חדש (ולא חידוש מעיקרו<sup data-n=\"10605\">477</sup> שהרי דבר<sup data-n=\"10606\">478</sup> אלקים<sup data-n=\"10607\">479</sup> יקום לעולם, ומאמר יהי אור הראשון יקום לעולם להוי'<sup data-n=\"10608\">480</sup> האור מאין ליש וכן מאמר יהי רקיע, דאל\"כ הרי הי' ראוי שיבוטל כל מע\"ב בכל שבת ויתהווה ביום א' אור חדש לגמרי ורקיע חדש לגמרי, ואנו רואים שאותו האור והרקיע ודשא והבהמה וחיה והאדם שכבר המה במציאותם הן קיימים רק שהן מתחדשי' בחיות חדש).\n<b>(וזהו</b> שאו' בקידוש זכרון למע\"ב דכל שבת הוא כמו שבת בראשית שמתחדש בו האור וחיות הכללי דכל מע\"ב על כל הוי\"ו ימים כי עולה הכל בבחי' או\"ח ביום הוי\"ו כמו ביום וי\"ו דוימ\"ב הראשונים כנ\"ל וד\"ל. וזהו וישבות כו' ואח\"כ ויברך כו' משום דהא בהא תליא שהשביתה בבחי' או\"ח אל העצמ[ו]' ממש הוא שגורם בחי' הירידה וההמשכה דכללו' הוי\"ו ימים שע\"ז א' ויברך כו' (בחי' ברכה בראש זהו שיברך ליום השבת עצמו בתחלה, והוא מבחי' עצמו' דא\"ס ממש שלמעלה מן החכ' במקור[ה] והוא כאשר הי' לפני מקור ההשתל' שהי' בבחי' מנוחה",[["10597","469","<b>שדי שא' לעולמו די</b>: לך יז, א. חגיגה יב, א. ראה לעיל סב, ב. ד ובהנסמן בהערה 1."],["10598","470","<b>והן הן גבורותיו</b>: יל\"ש נחמי' רמז תתרעא."],["10599","471","<b>דלא ייעף. . המנוחה דשבת</b>: ראה גם מאמרי אדה\"א במדבר ח\"א ע' נה. המשך תער\"ב ח\"ב ע' א'קג ואילך."],["10600","472","<b>אלמלא שמרו ישראל</b>: נסמן לעיל רח, ד."],["10601","473","<b>שבת דמעלי שבתא ושבת היום</b>: זהר בהקדמה ה, ב."],["10602","474","<b>שבת תתאה ושבת עילאה</b>: זהר שם."],["10603","475","<b>הכלל. . העלאה גורם בחי' המשכה</b>: ראה תו\"ח וישלח קצד, ב ובהערה 35."],["10604","476","<b>חיים</b>: בה: (ו)חיות."],["10605","477","<b>ולא חידוש מעיקרו</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' ערה ואילך ובהנסמן בריש המאמר שם."],["10606","478","<b>דבר אלקים יקום לעולם</b>: ישעי' מ, ח."],["10607","479","<b>אלקים</b>: ב: אלקי'. ה: אלקינו."],["10608","480","<b>להוי'</b>: ה: להוות."]]],[2300540808,"עצמי' כנ\"ל, <span data-k=\"pg\">636</span> ּ ואח\"כ נמשך ברכה בסוף מיום השבת על כל הוי\"ו ימים כנ\"ל), [ו]אחר בחי' ברכה כללי' זו דשבת על ו' ימים דחול אחר ההעלאה דאו\"ח כנ\"ל שזהו שנק' זכרון למע\"ב והוא מ\"ש ויברך אלקים כו', אח\"כ א' תחלה למקראי קדש שזהו מ\"ש ויקדש אותו למעלה מכל בחי' קדושה דיו\"ט כו' שהוא בבחי' בינה<sup data-n=\"10609\">481</sup> שהחכ' נמשך לבינה ביחוד חיצוני' דמע\"ב וביחוד פנימי' ביו\"ט ושבת עצמו נק' קדש מלה בגרמי' שנבדל מהיות מקור להמשכה בבינה, ועכ\"ז נק' תחלה למקראי קדש כו' דישראל קדשינהו לזמני'<sup data-n=\"10610\">482</sup> ושבת מקדשא וקיימא<sup data-n=\"10611\">483</sup> מוימ\"ב כו' כמ\"ש במ\"א וד\"ל). וכמו\"כ יובן ג\"כ בירידת המן ששרשו א' עם השבת כנ\"ל שהי' נמשך בשבת לשמים העליונים על כל הוי\"ו ימים ואח\"כ נתחלק בזמן דוי\"ו ימים כמ\"ש ולקטו דבר יום ביומו וע\"כ נאמרו שבת ומן בענין א' כנ\"ל וד\"ל.\n<b>אך</b> הנה לפ\"ז י\"ל מה שא' גבי מן והיה ביום הששי והכינו את אשר יביאו כו' וכתי' והי'<sup data-n=\"10612\">484</sup> ביום הששי לקטו לחם משנה שני העומר כו' ויאמר משה הוא אשר דבר ה' שבתון<sup data-n=\"10613\">485</sup> כו', דהנה לפי כל הנ\"ל בשרש המן שהיה בענין א' עם שרש השבת הרי הי' ביום הוי\"ו בחי' עלי' דאו\"ח מכל מע\"ב דוי\"ו ימים בליל שבת עי\"ז דוקא הי' ההמשכה ושפע החדשה מחדש בשבת על הוי\"ו ימים דשבוע דלהבא כנ\"ל. א\"כ גם בשפע המן הי' ראוי להיות כן ש[י]הי' בחי' עלי' והסתלקו' מכל אשר נמשך בכל וי\"ו ימי השבוע בבחי' או\"ח ועי\"ז דוקא הי' הברכה דמן בשבת על כל וי\"ו ימי' דשבוע דלהבא כמו בשפע דשבת על הוי\"ו ימים ש[ל]אחריו כנ\"ל, והרי כאן במ\"ש והיה ביום הששי והכינו כו' שלקטו לחם משנה ה\"ז להיפוך שהי' הכנה בהמשכה רבה בכפלים ביום הוי\"ו בשביל יום השבת שזהו הי' הכנה דע\"ש לשבת מלמעלה למטה היפוך הסתלקות דאו\"ח (ומה שגם במזון גשמי דלחם מן הארץ הרי מכינים בע\"ש לשבת ואין אופי' ומבשלי' בשבת, זהו משום איסור מלאכה בשבת אבל המן הרי הי' יורד מן השמים לארץ ביום הוי\"ו גם בשביל שבת כו'). אך הנה באמת י\"ל הטעם למה דוקא ביום הששי הי' הכנה זאת ליום השבת שנמשך בו לחם יומיים ולא יום אחר זולתו. ועוד זאת יפלא יותר על אשר ביום וא\"ו הי' להיפך משאר הימים שא' דבר יום ביומו דכל יום לא יהיב ולא יזיף לחברי' כלום, וע\"כ מה שנותר ממנו עד בקר דיום חבירו וירם תולעים ויבאש<sup data-n=\"10614\">486</sup>, ובעומר זה דשבת שנותר מיום וי\"ו א' ויניחו אותו עד הבוקר ולא הבאיש ורמה לא היתה בו<sup data-n=\"10615\">487</sup> כלל (ואע\"פ דמ\"ש בזהר דכל יומא לא יזיף ולא יהיב לחברי' היינו מדילי', אבל ע[ו]מר זה העודף מיום הוי\"ו לא משלו היה אלא של שבת. אך גם מה",[["10609","481","<b>דיו\"ט. . בינה</b>: נסמן לעיל קמט, ג. וראה גם לעיל פ' בא קטו, ג ואילך."],["10610","482","<b>דישראל קדשינהו לזמני'</b>: ברכות מט, א."],["10611","483","<b>ושבת מקדשא וקיימא</b>: ביצה יז, א. ראה גם מאמרי אדה\"א שמות ח\"א ע' רלב ואילך."],["10612","484","<b>והי'</b>: בה: ויהי."],["10613","485","<b>ויאמר משה הוא אשר דבר ה' שבתון</b>: בשלח טז, כג [ושם: ויאמר אלהם הוא]."],["10614","486","<b>וירם תולעים ויבאש</b>: בשלח טז, כ."],["10615","487","<b>ויניחו אותו. . לא היתה בו</b>: בשלח שם, כד."]]],[2300540817,"שעומר דשבת נמשך ביום וי\"ו זה היה הכנה בו ליום השבת, שאין יום מכין לחבירו כלום ויום הוי\"ו דוקא הוא שהכין לשבת, וכמו שבכל עומר דיום זה הנותר ממנו לבקר דיום חבירו יבאש וירם תולעים למה גם בעומר דשבת הנותר מיום וי\"ו לא הבאיש <span data-k=\"pg\">שיח</span> ּ מאחר שירד ביום וי\"ו ביחד עם עומר דע\"ש (ומ\"ש ויניחו אותו עד הבקר היינו לעומר דשבת ורמה לא היתה בו בעומר דשבת (ובאמת לכאורה<sup data-n=\"10616\">488</sup> אין הפשוט<sup data-n=\"10617\">489</sup> מובן במה שא' ורמה לא היתה בו דמה חידוש הי' שאין רמה נמצא בדבר האפוי או מבושל כי הרי א' את אשר תאפו אפו כו' והיינו לשני ימים כפרש\"י<sup data-n=\"10618\">490</sup> דבודאי לא הי' אופי' ומבשלים למן בשבת משא\"כ בנותר דשאר ימים).\n<b>והנה</b> באמת צ\"ל שהי' יום הששי מוכן דוקא להמשכה זו דעומר דשבת עצמו שממנו מקור מוצא הברכה הכללי' לכל וי\"ו ימים דשבוע דלהבא ולא יוכל להיות הכנה זאת ביום אחר זולת[ו רק ב]יום וא\"ו, ויש בזה ג' טעמים שהן ענין ושרש א'. והיינו מה שידוע דבחי' יום וי\"ו הוא בחי' יסוד<sup data-n=\"10619\">491</sup> שיש בו ג' דברים ביתרון מעלה על שאר המדות, הא' במה שהוא נק' גמר וגילוי ההשפעה דוקא, דהיינו לאחר כלות הכל שיבא לידי גמר וגילוי ההשפעה וההמשכה בכלל ובפרט שאין זה בשאר המדות שאינו נק' גמר [ה]שפע רק באותו פרט דכל מדה, וגם היא לא נגמרה עד בואה אל בחי' יסוד שנק' כנישו דכל נהורין כמ\"ש בזהר ע\"פ יקוו המים<sup data-n=\"10620\">493</sup> כו' אל מקום אחד כו'. והב' הוא מה שבבחי' יסוד יש בחי' ההתכללות [מ]כל המדות דחג\"ת ונו\"ה כו' וע\"כ נק' בשם כל<sup data-n=\"10621\">494</sup> כמו כי כל בשמים<sup data-n=\"10622\">495</sup> כו' כידוע, לפי שבחי' יסוד הוא בחי' גילוי אור השפע למקבל בגמר[ו] בפו\"מ שאז מוכרח שיקובץ בזה מכל מיני שפע דכל המדרגות דמדות חג\"ת כו' שיתכללו ויתחברו כולם כא' בגילוי אור שפע זו, כמו יקוו המים כו' שיתקבצו יחד ויוכללו ויומשכו [א]ל מקום אחד שזהו בחי' יסוד שנק' כנישו דכל נהורין (וכמו השפעת מ\"ד [ד]יסוד דדכורא שנכללו בו כל המוחין והמדות דחו\"ג יחד ע\"כ יוליד בצלמו כו'), והתכללות כזאת<sup data-n=\"10623\">496</sup> לא תמצא רק במ\"ד<sup data-n=\"10624\">497</sup> זו דבחי' יסוד ולא בשאר המדות שהן כ\"א במהות ומדרגה מיוחדת בפ\"ע כו' ואע\"פ שכלול כ\"א מזולתו, אבל התכללו' כלולים<sup data-n=\"10625\">498</sup> כא[חד] ממש זהו בבחי' יסוד דוקא וד\"ל<sup data-n=\"10626\">499</sup> ). והג' הוא מה שבבחי' יסוד יש ענין כללות<sup data-n=\"10627\">500</sup> של גמר גילוי השפע למטה במקבלי' שאין עוד ירידה והמשכה למטה יותר, וידוע שבבחי' כלות וגמר השפע",[["10616","488","<b>ובאמת לכאורה</b>: ה: ולכאורה. בג: כבפנים."],["10617","489","<b>הפשוט</b>: ב: הפירוש. ה: הפשט."],["10618","490","<b>את אשר תאפו. . כפרש\"י</b>: בשלח טז, כג."],["10619","491","<b>יום וא\"ו. . יסוד</b>: ראה זהר בשלח סג, ב ובמק\"מ שם. ת\"ז תנ\"ו (צ, א) ע\"פ יאיר נתיב למאו\"א מערכת יום ס\"ח. פרדס (שעה\"כ) שכ\"ג מערכת יום ומערכת ימים. לקו\"ת — להאריז\"ל — בראשית בתחילתו (ג, ב). 492) יסוד. . כנישו דכל נהורין: ראה גם לקמן פ' יתרו עדר, א. תצוה שנה, ד. הנסמן בהערה הבאה."],["10620","493","<b>בזהר ע\"פ יקוו המים</b>: בראשית א, ט. ראה זהר בראשית יח, א. לג, א. מאמרי אדה\"א בראשית ע' רפה. וש\"נ. קונטרסים ע' רכד. שעה\"י קלד, א."],["10621","494","<b>יסוד. . בשם כל</b>: נסמן לעיל פ' וארא נג, ד."],["10622","495","<b>כי כל בשמים</b>: דהי\"א כט, יא. ראה זהר בראשית לא, א."],["10623","496","<b>כזאת</b>: ה: כל זה. וראה בסמוך הערה 498."],["10624","497","<b>במ\"ד</b>: בה: במדה."],["10625","498","<b>כלולים</b>: ב: כללות. ה: כזאת. ראה לעיל הערה 496."],["10626","499","<b>וד\"ל)</b>: בה: וד\"ל."],["10627","500","<b>כללות</b>: ה: כלות."]]],[2300540826,"למטה ממש<sup data-n=\"10628\">501</sup> יש שם כח האו\"ח לתחלתו דוקא כמשי\"ת (והנה ג' הענינים הללו שיש בבחי' יסוד שאין זה בשאר המדות גם לא בדעת ות\"ת (אע\"פ שגם הם בקו האמצעי כו'), כי ת\"ת אינו כללי' הכולל הכל כ\"א רק שכולל בעצמו לחו\"ג<sup data-n=\"10629\">502</sup> בדרך פרט בבחי' הכרעה, וכן הדעת נוטה<sup data-n=\"10630\">503</sup> שכולל לחו\"ג<sup data-n=\"10631\">504</sup> ), וגם אין זה גמר השפע גם בנו\"ה שנק' כליות יועצות<sup data-n=\"10632\">505</sup> איך להשפיע עד שיגיע לגילוי אור השפע והמשכה למקבל שהוא אות הוי\"ו שראשו יו\"ד<sup data-n=\"10633\">506</sup> והולך ומתקצר למטה כידוע) בכל א' יש ב' מעלות יתירות שאין זה בכל המדות, א' מה שבאמצעות בחי' גילוי אור השפע והמשכה דבחי' יסוד מן המשפיע למקבל שזהו עיקר המכוון שהי' בראשית גילוי השפע לעצמו הוא שעולה לבחי' העצמו' דמשפיע ממש שלמעלה מגוף העונג שבשפע זו בתחלת[ו] משום דנתחב\"ס דוקא כו'. והב' מה שיש בגילוי אור שפע זו דבחי' יסוד מבחי' השלימות האמיתי מב' טעמים, הא' מצד שלימות השפע דמשפיע שיש <span data-k=\"pg\">638</span> ּ בשפע זו מפני בחי' ההתכללות דכל המדות יחד בו כמ\"ש יקוו המים כו' ונק' כל שכולל הכל כא' כנ\"ל. והג'<sup data-n=\"10634\">507</sup> מצד גילוי השפע למקבל שעי\"ז דוקא נשלם השפע כידוע ומבואר במ\"א בענין אדם דכר ונוק'<sup data-n=\"10635\">508</sup> כו', וע\"י בחי' שלימות האמיתי הזאת הוא שעולה לבחי' העצמו' ממש שלמעלה מבחי' משפיע ומקבל (כמשי\"ת). והג' מצד כללות של גמר גילוי דשפע היסוד במקבל שעי\"ז עולה בבחי' או\"ח אל העצמות שלמעלה מתחלתו כו', וזהו מעלה הא' שבכאו\"א מג' ענינים הנ\"ל שביסוד. והמעלה הב' הוא מה שימצא ביסוד בחי' המובחר מכל השפע[ות] שנמשך מכל המוחין ומדות כו' עד שלא ימצא בו שום נטי' לחוץ ולא ענין פסולת וחיצוני' כלל וכלל, וזהו דוקא בפנימי' יסוד כמו בברור שבטפה ובגמר השפע במקבל דוקא שנק' קליטה שבזה יש כח המוליד בדומה לו כו' וד\"ל).\n<b>ובכ\"ז</b> יובן ענין טעם דיום הששי הי' הכנה לשפע עד<sup data-n=\"10636\">509</sup> עומר דשבת שממנו נמצא מקור הברכה ל[כל ה]וי\"ו ימים שאחריו. דהנה טעם הא' הוא מצד שביום וי\"ו נגמר כל מלאכה מע\"ב דכל ימוהמ\"ש<sup data-n=\"10637\">510</sup> וכמ\"ש וירא אלקי' את כל אשר עשה<sup data-n=\"10638\">511</sup> כו', וזהו כמו בחי' יסוד שבו מתקבצים ונגמרים כל השפע דמדות דחג\"ת לבא בגילוי גמור, וידוע הכלל בכמה דוכתי שבבחי' גמר השפע<sup data-n=\"10639\">512</sup> דמשפיע למקבל שם ימצא עונג הנפלא ורב הרבה יותר מעונג הראשון שהי' למשפיע בהתעוררו' שפעו",[["10628","501","<b>למטה ממש</b>: ה: ליתא. בג: כבפנים."],["10629","502","<b>ת\"ת. . שכולל. . לחו\"ג</b>: נסמן לעיל פ' בא פט, א."],["10630","503","<b>הדעת נוטה</b>: נסמן לעיל פ' שמות מב, א."],["10631","504","<b>הדעת. . שכולל לחו\"ג</b>: נסמן לעיל פ' וארא נז, ד."],["10632","505","<b>בנו\"ה שנק' כליות יועצות</b>: ראה גם לעיל פ' שמות יד, ג. וש\"נ."],["10633","506","<b>הוי\"ו שראשו יו\"ד</b>: ראה לעיל קנ, ג. וש\"נ."],["10634","507","<b>והג'</b>: בה: והב'."],["10635","508","<b>אדם דכר ונוק'</b>: ראה זהר בהקדמה יג, ב. מאמרי אדה\"ז תקס\"ה ח\"א ע' שח. תקס\"ח ח\"א ע' תיח. ח\"ב ע' תרעא ואילך. מאמרי אדה\"א נ\"ך ס\"ע קכד ואילך. וש\"נ."],["10636","509","<b>עד</b>: ה: ליתא."],["10637","510","<b>ימוהמ\"ש</b>: בה: ימי השבוע."],["10638","511","<b>וירא. . אשר עשה</b>: בראשית א, לא."],["10639","512","<b>הכלל בכמה דוכתי. . גמר השפע</b>: ראה גם לקמן פ' יתרו רסו, א. עדר, ב. סידור ערבית לשבת קסט, א ואילך. ש\"א נג, א ובהערה 7. מאמרי אדה\"א נ\"ך ע' מט ואילך וע' רעט ואילך."]]],[2300540835,"ברצונו וחכמתו ומדותיו כו', כמו בגמר בנין המפואר שיתענג ביותר בגמר פעולתו בכל פרטי[ו] שלא נחסר בו דבר ומכללותם יחד דוקא יש בו להתפאר ברוב עונג ושעשועי' כו'. וכך הוא בהשפעת משפיע חסד וטוב או דבר חכמה שעיקר הפלא' העונג הוא בסופו דוקא דהיינו בגילוי גמר השפע בכל פרטי[ו] כא' למקבלים שזהו למעלה הרבה מתחלת העונג והרצון להשפיע. וזהו כמו יתרון רב בעונג שבטיפת יסוד בגמר גילוי השפע לנוק' יותר מעונג הרוחני' שבטפה הרוחני' במוח שהיא קודם השפע כו'. וכך הוא<sup data-n=\"10640\">513</sup> יובן עד\"מ העונג האלקי בגמר גילוי השפע דמע\"ב ביום הוי\"ו הוא שיעלה למעלה מעונג העליון הראשון שהי' ברצה\"פ לברוא וגם להאציל כו', משום דנתחב\"ס דוקא וסוף מעשה הוא שעלה במח' תחלה<sup data-n=\"10641\">514</sup> כי זה הי' עיקר המכוון בעונג ורצון הקדום כו'. וע\"כ יובן מזה גם בענין טעם ההכנה שהי' ביום וי\"ו דוקא בירידת שפע המן ליום השבת אע\"פ שיום השבת הוא מקור הברכה דוי\"ו ימים ש[ל]אחריו כנ\"ל, כי ביום וא\"ו דוקא שהוא גמר גילוי כל השפע דמדות עליונות דאצי' שם ימצא דוקא בחי' עונג העצמות שלמעלה מעונג המצומצם ברצון וחכ' דמע\"ב, עד שמזה יהי' הכנה לירידת השפע דעומר דשבת שהוא הברכה לוי\"ו ימים שנק' ברכה בסוף בלבד כנ\"ל. ואמנם ברכה [זו] בראש צדיק היינו [מ]בחי' ענג ושעשועי' העצמיי' שעולה מבחי' עונג שבגמר השפע דוקא שהוא יום וי\"ו דוקא כנ\"ל ולא יום אחד<sup data-n=\"10642\">515</sup> זולתו כנ\"ל, וגם מה שהמן דוקא הוא שירד ביום וי\"ו בשביל שבת ולא שאר ברכות אף לא ברכה דוי\"ו ימים שאחר השבת שא\"צ הכנה מע\"ש רק שע\"י <span data-k=\"pg\">שיט</span> ּ סבת הכליון וגמר דמע\"ב כמ\"ש ויכל אלקים [אז] נא' ויברך כו', לפי שהמן הי' בחי' פנימי' השפע דעונג העליון שנק' פנימי' [ע\"י שבפנימיות] אבא כנ\"ל. ובזה הובדל מעלת בחי' פנימי' יסוד שנמשך בו רק המובחר והתמצית כנ\"ל (ואמנם גם בחי' פנימי' השפע דברכת השבת למעלה על וי\"ו ימים שאחריו גם זה הרי בא ע\"י היום דע\"ש מטעם דברכות לראש צדיק כו' רק שלא הוכן ביום וי\"ו ממש כירידת המן ב' עומר כו', אבל באפיה ובישול לשבת הכל מוכן מיום וי\"ו דוקא שעל ידו דוקא יוכל לומר דא היא סעודתא דע\"י כו', וכן לענין המשכת נשמות חדשו' מפנימי' ע\"י ביחוד פנימי' דאו\"א וזו\"נ בכל ליל שבת כנ\"ל וד\"ל).\n<b>ומעתה</b> יש להבין בענין טעם הב' הנ\"ל שהוא מצד בחי' ההתכללו' דוי\"ו ימים שכלולים כא' ביום וי\"ו דוקא, דאע\"פ שא' בזהר דכל יומא בעבידתי' דוקא, עכ\"ז יש התכללות בכל יום מחבירו (וכמו בוא\"ש שהי' התכללו' דגבו'",[["10640","513","<b>הוא</b>: בה: ליתא."],["10641","514","<b>וסוף מעשה. . במח' תחלה</b>: ע\"פ פיוט לכה דודי."],["10642","515","<b>אחד</b>: בה: אחר."]]],[2300540844,"בחסד וחסד בגבורה כו'), וכמו במאמר יהי אור שנאמר בו כי טוב<sup data-n=\"10643\">516</sup> יש בו מבחי' הגבורה והצמצום דאור מן החושך והוא מ\"ש ויבדל אלקי' בין האור והחשך<sup data-n=\"10644\">517</sup> (כמ\"ש במ\"א), וגם מה שארז\"ל דגנזו לצדיקים לע\"ל<sup data-n=\"10645\">518</sup> (שנק' אור ז' הימים<sup data-n=\"10646\">519</sup> כו'), ובחי' אור החסד דיום הא' אזיל<sup data-n=\"10647\">520</sup> עם כולהו יומי' וכלול מכולם יחד כו'. וכן במא' יהי רקיע שבבחי' הגבורה הי' כלול מבחי' החסד שנק' גבורה שבחסד בבחי' הבדלה זו עצמה שהבדיל בין מ\"ע למ\"ת כו', כדי שיוכל להיות התהוות דצח\"מ ממ\"ת בארץ כו' וכה\"ג גם בשאר הימים. ואמנם כ\"ז נק' התכללות בפרט המיוחד לכל יום ויום לבד אבל [בחי'] התכללות דיום וי\"ו נק' התכללו' בכללות כולם יחד דוקא כמ\"ש וירא אלקים את כל אשר עשה דוקא והנה טוב מאד, דמאד זה בלי גבול<sup data-n=\"10648\">521</sup> מורה על היותו בחי' עונג העצמי' ממש שלמעלה מכל עונג הבא ברצון וחכמה ומדות דמע\"ב הגם שנאמר בהן כי טוב כו', והוא מחמת גמר כל המלאכה דוקא שראה את כל אשר עשה כו' והוא בחי' יסוד שנק' כל בכלות כל השפע שבו כלולי' הכל כא' כנ\"ל, שבחי' העונג שבו נק' עונג כללי מכללות כל השפע שעושה<sup data-n=\"10649\">522</sup> בעונג העצמות ממש שלמעלה גם מבחי' עונג הכללי הזה שבמע\"ב (ואע\"פ שגם הוא בא בגבול לפ\"ע הפר[ט ד]עונג ורצון בחכמה ומדות דמע\"ב, מ\"מ יש לו דמיון לעורר עונג העצמי'<sup data-n=\"10650\">523</sup> שנק' שעשועי המלך בעצמו<sup data-n=\"10651\">524</sup> שמצד העצמו' ממש שנק' שלימותא דכולא<sup data-n=\"10652\">525</sup> וע\"כ נק' טוב מאד, וכמבואר במ\"א שזהו כמשל הגומר מלאכת הבנין<sup data-n=\"10653\">526</sup> שמשתעשע בעצמותו ממש מכללו' יופי טוב המלאכה מכל אשר עשה דוקא כו' וד\"ל. וזהו ג\"כ הטעם לענין הכנה דיום הוי\"ו ליום השבת בין בשפע פנימי' דמן כנ\"ל ובין בשפע חיצוניות דוי\"ו ימים הבאים שנמשך בשבת כנ\"ל וד\"ל (ואע\"פ שגם בתחלת הרצה\"פ להאציל ולברוא כו' הי' בבחי' עונג ורצון כללי שכולל כל מה שעתיד להיות התחלקות עונג ורצון בפרטי' דוימ\"ב, אבל אין שלימות דעונג זה ורצה\"פ וכללי רק בגמר כל השפע בפו\"מ בכלות יום הוי\"ו שמקבל מכל<sup data-n=\"10654\">52</sup> עונג כללי מכל אשר עשה שעולה בבחי' העלאה דאו\"ח משום <span data-k=\"pg\">640</span> ּ דנתחב\"ס דוקא, וז\"ש ויהי ערב כו' יום הששי<sup data-n=\"10655\">528</sup> בה\"א שלא נכתב ה\"א בכל הימים<sup data-n=\"10656\">529</sup> להיותו כולל כולם שמפני זה עולה בעצמות השעשועי', והוא מ\"ש ויכולו כו' שהוא לשון תענוג<sup data-n=\"10657\">530</sup> כמו לכל תכלה ראיתי קץ<sup data-n=\"10658\">531</sup> כו'. ואמנם להיות בחי' העלא' דתענוג הכללי עולה בעצמות התענוג שלמעלה מבחי' המשפיע בכלל ובפרט (משא\"כ בכ\"י שהי' העלאה בדרך פרט מאותו יום לבד כמשי\"ת). וע\"כ מעלה יתירה זו אינו אלא בבחי' יסוד דוקא ולא בת\"ת ודעת כנ\"ל להיותו בא בפו\"מ למקבלים וכלולים הכל בו שיש בו ב' מיני",[["10643","516","<b>כי טוב</b>: בראשית א, ד."],["10644","517","<b>ויבדל אלקי' בין האור והחשך</b>: [וכ\"ה במאמרי אדה\"א ויקרא ח\"א ע' קפג. ש\"א מג, ב. ובבראשית א, ד: ובין החשך — וכ\"ה בבה]. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קסב ואילך."],["10645","518","<b>דגנזו לצדיקים לע\"ל</b>: חגיגה יב, א."],["10646","519","<b>אור ז' הימים</b>: ישעי' ל, כו."],["10647","520","<b>אור החסד דיום הא' אזיל</b>: ראה גם לעיל פ' בא קכא, ב ובהערה 317."],["10648","521","<b>דמאד זה בלי גבול</b>: נסמן לעיל פ' וארא סא, ב."],["10649","522","<b>שעושה</b>: בה: שעולה."],["10650","523","<b>העצמי'</b>: ב: העליון. ה: העצמי."],["10651","524","<b>שעשועי המלך בעצמו</b>: נסמן לעיל פ' בא צב, ד."],["10652","525","<b>שלימותא דכולא</b>: נסמן לעיל פ' שמות מח, ב."],["10653","526","<b>הגומר מלאכת הבנין</b>: ראה גם מאמרי אדה\"ז על מארז\"ל ע' קעב. ענינים ע' תלו. שע\"ת יג, ב."],["10654","52","<b>מכל</b>: בה: ליתא."],["10655","528","<b>ויהי ערב כו' יום הששי</b>: בראשית א, לא."],["10656","529","<b>שלא נכתב ה\"א בכל הימים</b>: ראה גם מפרשי החומש שם. (וראה ג\"כ בראשית ב, ב. ג)."],["10657","530","<b>ויכולו. . תענוג</b>: ראה גם רקאנטי בראשית ב, ב. מאמרי אדה\"ז תקס\"ט ע' לה. מאמרי אדה\"א נ\"ך ע' קמח. תו\"ח ויגש רלא, ד. לקמן פ' יתרו רסו, א."],["10658","531","<b>לכל תכלה ראיתי קץ</b>: תהלים קיט, צו."]]],[2300540853,"שלימות, א' מצד ההתכללות בגמר השפע דמשפיע, והב' מצד בחי' העלא' דאו\"ח בכללות מסוף מעשה דוקא וד\"ל.\n<b>וזהו</b> ג\"כ טעם הג' הנ\"ל משום דבכלות השפע שבפו\"מ עולה הכל בבחי' או\"ח אל העצמות לפי שלא ירד עוד למטה יותר, [ו]כל דבר הנמשך ובא בסיום אז יגדל כח העולה משם בבחי' או\"ח למעלה מכח של [ה]התחלה<sup data-n=\"10659\">532</sup>, וכנראה בחוש במים היורדי' ממקום גבוה בהר לעמק בסיום כח ירידתן למטה שלא ירדו [עוד] מפני הדבר המעכב הילוכן עוד, אז יעלו המים בחזרה בכח העלי' והגבהה למעלה עד מקור חוצבו [ו]למעלה משם<sup data-n=\"10660\">533</sup>, וכח החוזר הזה חזק יותר מכח היורד כו'. וזהו יתרון מעלה דאו\"ח על או\"י דבאו\"י שיורד מגבוה לנמוך נתמעט כחו בירידתו למטה אך כשהגיע בסופו דוקא שם מתחזק כח [ה]התחלה בתוס' כח יותר משהי' בעצם, והוא כח החוזר למעלה ממקור[ו] הראשון<sup data-n=\"10661\">534</sup>. וכנראה בחוש בהתפשטו' חום השמש באויר הארץ שבהתפשטות למטה מתחלש כח החום אך בהגיע בסופו שהוא בכדור הארץ שם יתרבה כח החום דשמש, דאויר הארץ מתחמם שם ביותר הרבה מאויר האמצעי שאין אור השמש [שם] חם כ\"כ, וגם יותר מחום השמש שבקרוב לשמש<sup data-n=\"10662\">535</sup>, לפי שלמטה בארץ שלא יתפשט שם עוד למטה יותר ע\"כ שם דוקא עיקר הכאת אור השמש בכח חזק מאד להיותו מטה יותר ומעוכב שם התפשטותו שלא יתפשט עוד כו', ע\"כ ימצא שם כח העולה בבחי' או\"ח בתוקף חום השמש ביותר מתחלתו (ולא כפי'<sup data-n=\"10663\">536</sup> הפרד\"ס<sup data-n=\"10664\">537</sup> בנתחב\"ס שאין בסוף יותר מתחלתו, אלא שכל כח [ה]התחלה מקבל מן הסוף מטעם דאו\"ח גדול מאו\"י). וכמו\"כ יובן [ענין] טעם מעלה יתירה דיום הוי\"ו שנק' סוף מעשה מכל אשר עשה בכל הימים כמ\"ש ויכולו השמים והארץ כו', כי בגמר דיום הוי\"ו הי' כלות כל ההמשכו' ו[כל] ההשפעות די\"מ בכלל ובפרט, ובבחי' כלו[ת] השפע למטה ממש שם נמצא כח העולה למעלה בבחי' או\"ח לקדמותו ממש לעצמות המאציל שלמעלה ממקור כל ההמשכו' ד[ו]ימ\"ב, מפני שנתחב\"ס באופן שיתחזק כח ומקור [ה]התחלה מסוף מעשה דוקא לפי שבחי' או\"ח דסוף מעשה חוזר אל העצמות ממש כמ\"ש כי בו שבת וינפש כו'. וזהו ויכל אלקים ביום הז' מיד אחר כלות יום הוי\"ו שהוא בחי' עלי' דאו\"ח לקדמות המאציל <span data-k=\"pg\">שכ</span> ּ וד\"ל (וזהו למעלה יותר מעלי' התענוג מכל אשר עשה, שזהו ביום הוי\"ו עדיין בגמר מלאכתו בכללות דוקא שז\"ש וירא אלקי' את כל כו'. ואמנם אחר שא' ויהי ערב כו' יום הששי ויכולו השמים שזהו בחי' ההעלאה דאו\"ח מן הגמר דגוף השפע דמשפיע ומקבל, וזהו ויכולו לשון רבים ואח\"כ א' ויכל",[["10659","532","<b>או\"ח למעלה מכח של [ה]התחלה</b>: ראה בסמוך בפנים ובהערות הסמוכות."],["10660","533","<b>במים היורדי'. . עד מקור חוצבו [ו]למעלה משם</b>: ראה יומא לא, א. מאמרי אדה\"א דברים ח\"א ע' שכז. קונטרסים ע' שצט. וש\"נ."],["10661","534","<b>דאו\"ח. . למעלה ממקור[ו] הראשון</b>: נסמן לעיל פ' שמות מ, סע\"ד."],["10662","535","<b>החום דשמש. . יותר. . שבקרוב לשמש</b>: ראה גם בענין החום דשמש לקמן פ' תשא שפו, א (בשם ספרי התכונה). ביאוה\"ז א, ב (בשם ספרי התכונה). דר\"מ מצות ציצית (טו, ב). שרש מצות התפלה (קכט, ב). מאמרי אדה\"ז על פרשיות התורה ח\"א ע' נט. כאן ע' רצו וע' רצט. תקס\"ה ח\"ב ע' תשמא (בשם ספרי הטבע). ענינים ע' שלד. מאמרי אדה\"א בראשית ע' תקיח. דברים ח\"א ע' שכז (בשם ספרי הטבע)."],["10663","536","<b>כפי' הפרד\"ס בנתחב\"ס</b>: ראה שם (שער ממטה למעלה) שט\"ו, פ\"א. ע\"ח (שער מ\"ן ומ\"ד) של\"ט, דרוש ט\"ו."],["10664","537","<b>הפרד\"ס</b>: בה: פרדס. נסמן לעיל פ' בא צ, א."]]],[2300540862,"אלקים לשון יחיד, לפי שבהעלא' זו דכללות כל השפע הוא שעלה הכל ע\"י שם אלקי' בעצמו שז\"ש ויכל אלקים כמו עלה אלקים<sup data-n=\"10665\">538</sup> כו') והוא בחי' עליי' המל' בתחלת ליל שבת בקבלת שבת דוקא וז\"ש ויכל אלקים ביום הז' וישבות כו' אחר כלות גמר השפע בכללות [בכלות] יום הוי\"ו דוקא מטעם הנ\"ל וכידוע דשרש יום השבת הוא בבחי' המל'<sup data-n=\"10666\">539</sup> כמשי\"ת וד\"ל.\n<b>ובכ\"ז</b> יובן עכ\"פ כללות ענין הטעם דדוקא ביום הוי\"ו יוכל להיות הכנה על יום השבת ולא יום אחר זולתו, לפי שיש יתרון מעלה ביום הוי\"ו על שאר הימים להיותו בחי' סוף מעשה דכל מע\"ב שעולה בבחי' או\"ח אל העצמות ממש שלמעלה מבחי' העונג ורצון וחכמה בתחלה מטעם הנ\"ל, ע\"כ יכול להכין ליום השבת ש[י]הי' ממנו מקור הברכות לוי\"ו ימים שאחריו בין בשפע המן בין בשפע דחידוש דמע\"ב כו'. אך הנה עדיין אין זה מובן דאיך יוכל להיות הכנה ביום הוי\"ו לשבת אחר שהוא בבחי' או\"ח אל העצמו' לפי שהוא גמר כל השפע כנ\"ל ובחי' או\"ח הוא היפוך יריד' וההמשכה למטה, [כי] הרי מטעם זה לא ירד המן בשבת להיותו בבחי' או\"ח אל העצמו' שהוא ענין השביתה והמנוחה כמ\"ש כי בו שבת כנ\"ל, וא\"כ זהו הטעם עצמו [ב]מניעת השפע ביום הוי\"ו אם הוא בבחי' או\"ח דוקא כנ\"ל. ועוד דהלא ידוע בשרש ענין וימ\"ב שהן בחי' ז'<sup data-n=\"10667\">540</sup> מדות דחג\"ת [ונה\"י], וא\"כ יום הוי\"ו הוא בחי' יסוד זהו עיקר בחי' ירידת השפע למקבל שהוא היפך העלי' והסתלקות דאו\"ח (דלא כדלעיל) וד\"ל. ועוד דלפי כלל זה דוימ\"ב הן בבחי' המדות דחג\"ת כו' וא\"כ<sup data-n=\"10668\">541</sup> הרי השבת הוא בבחי' המל' שהוא יום הז' שמקבל מן הוי\"ו ימים דחול ואיך יהי' בשבת דוקא מקור הברכה לוי\"ו ימי החול שאחריו כנ\"ל. אך הענין הוא דבאמת שרש הוי\"ו ימים הן בחי' המדות דאצי' שהן בחי' משפיעים ביום הא' בחי' אור החסד כו' עד יום הוי\"ו שהוא בחי' יסוד שהוא עיקר המשפיע שנק' כנישו דכל נהורין עילאין כו' כנ\"ל, וידוע דבחי' יסוד הוא המשפיע למל' שהוא יום הז' דשבת וע\"כ הי' ההכנה לשבת במן ביום הוי\"ו דוקא כמ\"ש והי' ביום הששי והכינו כו' לפי שיום הוי\"ו הוא בחי' יסוד שהוא המכין השפע למל' שהוא יום השבת שנק' שבת מלכתא<sup data-n=\"10669\">542</sup> כו'. אך בזה יתרון מעלת יום השבת על הימים דחול עד שנק' קדש כו', דגם שיום הז' דשבת הוא האחרון במדרגה מכל הימים עד שמקבל מיום הוי\"ו בחי' יסוד כנ\"ל זהו בבחי' ירידת השפע מלמעלה למטה מן המשפיע אל המקבל, אבל בשבת הוא בחי' עליי' המל' שבחי' המל' עולה בשבת בעילוי אחר עילוי עד רום המעלות בפנימי' הכתר עד",[["10665","538","<b>עלה אלקים</b>: תהלים מז, ו."],["10666","539","<b>יום השבת. . המל'</b>: ראה פרדס (שער עה\"כ) שכ\"ג מערכת שבת."],["10667","540","<b>ז'</b>: בה: ו'."],["10668","541","<b>וא\"כ</b>: שם: ליתא."],["10669","542","<b>שבת מלכתא</b>: ראה זהר (רע\"מ) צו כט, א. פינחס רמג, ב. תצא רעט, ב. ועוד. וראה ב\"ק לב, ב."]]],[2300540871,"עצמות דא\"ס<sup data-n=\"10670\">543</sup> ממש כמ\"ש כי בו שבת כו', והוא מ\"ש <span data-k=\"pg\">642</span> ּ ויכל אלקים ביום הז' כו' שזהו העלי' אחר כלות השפע דיום וי\"ו ביום הז' בליל ש\"ק<sup data-n=\"10671\">544</sup> דוקא שאז עליי' המל' למעלה ממש עד שוי\"ו ימים דמדות דאצי' מקבלים ממנה כמ\"ש ויברך אלקים את יום הז' ברכה זו לכל הוי\"ו ימים שאחר השבת כנ\"ל וד\"ל.\n<b>(ונמצא</b><sup data-n=\"10672\">545</sup> דעיקר בחי' העלי' דאו\"ח אל העצמו' ממש הוא בשבת דוקא שהוא עליי' המל' דוקא כנ\"ל, אבל ביום הוי\"ו אע\"פ שבו נגמר כל המשכות דמדות העליונות אבל גם הגמר הזה היינו דוקא בבחי' ירידת והמשכת השפע מלמעלה למטה דוקא מאחר שהוא בחי' יסוד שנק' כנישו כו', ו[כ]אות הוי\"ו שהולך ומתקצר למטה להתקבץ<sup data-n=\"10673\">546</sup> במקבלים כו'. וזהו ויהי ערב כו' יום הששי בה\"א הידיע' שבו נגמר הכל בירידת השפע וזהו ויכולו השמים והארץ שנגמר[ה] וכלה מלאכתו כתי'<sup data-n=\"10674\">547</sup> מצד בחי' המשפיע, ואז מיד בכלות השפע מן המשפיע למקבל שהוא בחי' המל' ויכל אלקים כו' שעולה המל' בבחי' או\"ח אל העצמות ממש (וגם מ\"ש וירא אלקים את כל אשר עשה כו' שזהו ביום הוי\"ו בגמר המלאכה כולה שעולה בבחי' או\"ח כנ\"ל זהו בחי' עליי' דתענוג דמשפיע שהוא בגמר טוב מלאכתו דוקא ונק' או\"ח דמשפיע, וז\"ש ויכולו לשון רבים מכל המדות שכלולים ביום וי\"ו, אבל בשבת הוא בחי' או\"ח דמל' כמ\"ש ויכל אלקים כו' ובזה יתורץ הכל וד\"ל). ולפי שהמל' דשם אלקים עלה בבחי' או\"ח בעצמ[ו]' ממש בבחי' שביתה ומנוחה לחיי כל העולמות דאבי\"ע אז נמשך מקור הברכה בשבת לכל הימים כמ\"ש וישבות ויברך כו' ויקדש אותו בבחי' קדש העליון דפנימי' הכתר שבחכמה כו'. וזהו שארז\"ל ברכו במן וקדשו במן<sup data-n=\"10675\">548</sup> שהברכה במן על כל הוי\"ו ימים הי' בשבת, וגם שעולה הכל בבחי' או\"ח<sup data-n=\"10676\">549</sup> במה שלא ירד המן בשבת זהו מפני קדוש[ה] דשבת (וכמ\"ש<sup data-n=\"10677\">550</sup> נכון כסאך מאז<sup data-n=\"10678\">551</sup> כנ\"ל וד\"ל (וגם בתחלת ההשתל' דוימ\"ב הראשונים שלא הי' תחלה העלאה דאו\"ח דשבת בבחי' שביתה ומנוחה כו', עכ\"ז נמשך מקור הברכה בוימ\"ב, כי גם אז הי' בחי' העלאה דאו\"ח ממה שעתיד להיות כמאמר במי נמלך בנשמתן של<sup data-n=\"10679\">552</sup> צדיקים<sup data-n=\"10680\">553</sup>,",[["10670","543","<b>דא\"ס</b>: ה: אא\"ס."],["10671","544","<b>ביום. . ש\"ק</b>: ה: בלילה הז' ביום ש\"ק."],["10672","545","<b>(ונמצא</b>: בה: ונמצא."],["10673","546","<b>להתקבץ</b>: ה: להתקבל."],["10674","547","<b>כתי'</b>: בה: ליתא."],["10675","548","<b>ברכו במן וקדשו במן</b>: ראה מכילתא יתרו כ, יא. רש\"י שם. ב\"ר פי\"א, ב. רש\"י בראשית ב, ג. לקו\"ש בשלח (כרך טז) ע' 173 הערה 7."],["10676","549","<b>שעולה הכל בבחי' או\"ח</b>: ה: ליתא."],["10677","550","<b>(וכמ\"ש. . וד\"ל</b>: ה: (שעולה המל' בבחי' או\"ח כנ\"ל וד\"ל). וראה בסמוך הערה 553."],["10678","551","<b>נכון כסאך מאז</b>: תהלים צג, ב."],["10679","552","<b>במי נמלך בנשמתן של צדיקים</b>: ראה ב\"ר פ\"ח, ז. רו\"ר פ\"ב, ג."],["10680","553","<b>צדיקים</b>: ה: ניתוסף: (וכמ\"ש נכון כסאך מאז). וראה לעיל הערה 550."]]],[2300540880,"דהיינו שבחי' סוף מעשה דנשמות הצדיקים בעוה\"ז בכל וא\"ש עד יום הוי\"ו עלה במ\"ת<sup data-n=\"10681\">554</sup> טרם שעלה ברצונו להאציל ולברוא כו', והצדיק הוא בחי' יסוד [שנק' יסוד] עולם, וע\"כ עלה בחי' סוף מעשה דצדיקים בבחי' או\"ח דמל' לעורר מח' ורצון הקדום דמל' דא\"ס כמ\"ש בריש הורמנא דמלכא<sup data-n=\"10682\">555</sup> כו', וזהו שא' במי נמלך אם יהי' לו רצון למל' כו' [ב]נשמתן של צדיקים שהן בחי' משפיעי' למל' כמו מיום הוי\"ו לשבת וכמו\"כ מאלף הוי\"ו לאלף הז' דעוה\"ב כמשי\"ת וד\"ל.\n<b>והנה</b> ע\"ד כל הנ\"ל בטעם ענין ההכנה דיום הוי\"ו לשבת יובן ג\"כ בכללות הוא\"ש דהוי עלמא דאלף הוי\"ו והוא בחי' יום הוי\"ו<sup data-n=\"10683\">556</sup> בכלל מכין לשבת שהוא אלף הז' שנק' יום שכולו שבת בחי' מנוחה לחה\"ע<sup data-n=\"10684\">557</sup> בעצמות א\"ס ממש. וביאור הענין הנה ידוע דיום הא' שהוא מאמר יהי אור כו' זהו אלף שנה דבחי' החסד דאצי' שהי' אריכות ימים לבנ\"א וגם דור אנוש שהי' עוע\"ז<sup data-n=\"10685\">558</sup> היו ניזוני' בחסדו<sup data-n=\"10686\">559</sup> כו', ואלף הב' מבחי' אור הגבו' דאצי' והי' המבול<sup data-n=\"10687\">560</sup> וההפלגה<sup data-n=\"10688\">561</sup> כו', ואלף הג' בבחי' הת\"ת הי' יצ\"מ לישראל שהן בחי' הת\"ת<sup data-n=\"10689\">562</sup> כמ\"ש ישראל אשר <span data-k=\"pg\">שכא</span> ּ בך אתפאר<sup data-n=\"10690\">563</sup> ו[הי'] מ\"ת שהוא בחי' הת\"ת<sup data-n=\"10691\">564</sup> כמ\"ש אש<sup data-n=\"10692\">565</sup> מימינו אש<sup data-n=\"10693\">566</sup> כו' כידוע, ואלף הד' בחי' נצח שהוא ענף החסד<sup data-n=\"10694\">567</sup> ממש כמ\"ש נעימות בימינך נצח<sup data-n=\"10695\">568</sup>, ע\"כ הי' רובו חסד כמו בנין בית ראשון<sup data-n=\"10696\">569</sup> וב\"ש ורוב טובה וברכה לישראל אך בסופו הי' חורבן ב\"ש וקצת צרות<sup data-n=\"10697\">570</sup>, ואלף הה' בחי' הוד ענף הגבורה<sup data-n=\"10698\">571</sup> רובו דיני' וגבורות, ע\"כ הי' בו רוב צרות ועיקר שעבוד הגלות וכמו גזירות תתנ\"ו<sup data-n=\"10699\">572</sup> וכה\"ג, עד זמן של[\"ג ל]אלף הוי\"ו שבטלו הגירושי' והשמדות<sup data-n=\"10700\">573</sup> כו', ואלף הו' בחי' יסוד שכלול מחו\"ג<sup data-n=\"10701\">574</sup> וכל המדות כנ\"ל ביום הו' בכל שבוע, וזמן ההכנה ליום השבת ביום וי\"ו דוקא כנ\"ל וכמ\"ש והי' ביום הו' והכינו כו' שהוא לחם משנה דמן, וכך הוא באלף הוי\"ו (מחצי היום ולמטה שהוא בשנת ת\"ר<sup data-n=\"10702\">575</sup> שזהו [כ]שעה א' אחר חצי היום וי\"ו<sup data-n=\"10703\">576</sup> בפרט כו') שכל התומ\"צ שעושים כנס\"י וצדיקי' שיהיו בימוהמ\"ש עד כלות האלף הוי\"ו הכל בבחי' הכנה ליום הז' שהוא אלף הז' דעוה\"ב שאז בחי'",[["10681","554","<b>במ\"ת</b>: בה: במחשבה תחלה."],["10682","555","<b>בריש הורמנא דמלכא</b>: ראה זהר בראשית טו, א."],["10683","556","<b>דאלף הוי\"ו. . יום הוי\"ו</b>: ראה (וכן להבא להלן) לעיל פ' שמות טו, ג הערה 668."],["10684","557","<b>לשבת שהוא אלף הז'. . מנוחה לחה\"ע</b>: ראה גם לקמן פ' משפטים רעט, א. רפו, ב. מאמרי אדה\"א דברים ח\"א ע' קג. וש\"נ. שע\"ת יג, א ואילך."],["10685","558","<b>דור אנוש שהי' עוע\"ז</b>: נסמן לעיל מד, א."],["10686","559","<b>דור אנוש. . היו ניזוני' בחסדו</b>: נסמן לעיל כד, ד."],["10687","560","<b>המבול</b>: בשנת אלף תרנ\"ו (סדר הדורות)."],["10688","561","<b>וההפלגה</b>: בשנת אלף תתקצ\"ו (סדר הדורות)."],["10689","562","<b>לישראל שהן בחי' הת\"ת</b>: ראה גם מאמרי אדה\"א קונטרסים ע' ג. וש\"נ."],["10690","563","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג."],["10691","564","<b>מ\"ת שהוא בחי' הת\"ת</b>: ברכות נח, סע\"א. ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' תיב. (וראה לעיל קעג, א)."],["10692","565","<b>אש</b>: בה: ליתא."],["10693","566","<b>מימינו אש </b>[ה: ניתוסף: דת]: ברכה לג, ב."],["10694","567","<b>נצח שהוא ענף החסד</b>: ראה זהר (רע\"מ) פינחס רמג, סע\"א. מאמרי אדה\"ז תקס\"ח ח\"א ע' תלא. הנסמן במאמרי אדה\"א קונטרסים ע' רכח."],["10695","568","<b>נעימות בימינך נצח</b>: תהלים טז, יא."],["10696","569","<b>ואלף הד'. . בנין בית ראשון</b>: בנין בית ראשון ב\"א תתקכח-תתקלה (סדר הדורות). וראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' תיב. פרשיות התורה ח\"א ע' תכ [ושם: ולכך הי' השני בתי מקדשי' ב\"ר וב\"ש באלף הזה]. ובתו\"ח בראשית ח, ד: לאלף השלישי. . ובסופו הי' בנין בהמ\"ק דשלמה."],["10697","570","<b>בסופו הי' חורבן ב\"ש וקצת צרות</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' תכ."],["10698","571","<b>הוד ענף הגבורה</b>: ראה זהר (רע\"מ) פינחס רמג, ריש ע\"ב. הנסמן במאמרי אדה\"א קונטרסים ע' רכח."],["10699","572","<b>גזירות תתנ\"ו</b>: נזכר גם בשע\"ת ה, ב ובהערה 12."],["10700","573","<b>של[\"ג ל]אלף הוי\"ו שבטלו הגירושי' והשמדות</b>: ראה גם שע\"ת שם ובהנסמן בהערות שם."],["10701","574","<b>יסוד שכלול מחו\"ג</b>: ראה פרדס (שער המכריעין) ש\"ט, פ\"ד. מאמרי אדה\"א קונטרסים ע' רכח. ש\"א פו, א."],["10702","575","<b>באלף הוי\"ו. . בשנת ת\"ר</b>: ראה גם אודות שנת ת\"ר שע\"ת יד, א."],["10703","576","<b>[כ]שעה א' אחר חצי היום וי\"ו</b>: ראה גם סה\"ש תש\"נ ע' 254. וש\"נ."]]],[2300540889,"מנוחה לחיי העולמי' כמו ההכנה מע\"ש לשבת הנ\"ל, שזהו מצד בחי' כלות השפע דוי\"ו ימי' שהן וי\"ו מדות דחג\"ת כו' שעי\"ז עולה המל' בשבת בבחי' או\"ח עד רום המעלות ממש כמ\"ש ויכולו כו' ויכל אלקים כנ\"ל. כך הוא בכללות ענין [כל] ו\"א שנים שנגמרים באלף הוי\"ו בימוהמ\"ש שנק' צדיקים יסודי<sup data-n=\"10704\">577</sup> עולם בכללות וכל הצדיקי' שעמו בכללות נש\"י בכל מעשיהם הן בחי' משפיעי' במל' שנק' שכינה<sup data-n=\"10705\">578</sup>, כמ\"ש ועמך כולם צדיקים<sup data-n=\"10706\">579</sup> משפיעי' בתו\"מ למל' ע\"כ לעולם ירשו ארץ שהוא ארץ החיים דעוה\"ב באלף הז' שאז הוא בחי' עליי' המל' בכלל שהוא עוה\"ב, שאז בחי' עליות העולמות בעילוי אחר עילוי עד שעשועי המלך בעצמו שאין עוד למעלה הימנו שנק' מנוחה לחיי העולמים בבחי' מנוחה העצמי', דהיינו לכל חיי העולמי' דאבי\"ע בכללות דוימ\"ב דאצי' בכל וא\"ש דהוי עלמא בהשתלשלו' דקו\"ח כו' יהי' עליי' לכולם ביום שכולו שבת באלף הז' דעוה\"ב בבחי' עצמיות השעשועי' שנק' עדן העצמי' שאין עלי' אחרי' עוד ע\"כ נק' מנוחה לח\"ע כו', כמו שבכל שבת הוא בחי' עליי' המל' שמעלה לכל הימים דחול בבחי' או\"ח אל העצמות ממש כנ\"ל, כך יהי' בחי' עליי' הכללי' דמל' ביום שכולו שבת להעלות לכל וא\"ש כו', ובכל שבת יש מיום שכולו שבת דעוה\"ב כידוע וד\"ל (וכל ג' טעמי' הנ\"ל ביתרון מעלה דיום הוי\"ו על שאר הימים יובן ג\"כ בדרך כללו' באלף הוי\"ו שהוא יום הוי\"ו בכלל שהוא גמר השפע הכללי' דכל וא\"ש, כמו בכלות יום וי\"ו בכל שבוע שעולה בתענוג העצמו' ממש שלמעלה מבחי' תחלת העונג ורצה\"פ כו' וע\"כ יש בו כח ההכנה לשבת הכללי, ולבד טעם הד' שהוא בחי' עיקר המשפיע למל' שהוא בחי' יסוד כנ\"ל בדרך ירידה דוקא למקבל כנ\"ל. וזהו ענין המצות שיהי' בתכלית השלימות בימוהמ\"ש בכללות נש\"י שנק' צדיקי' בחי' משפיע[ים] למל' שעי\"ז ירשו ארץ החיים דעוה\"ב שנק' ארץ חפץ כמ\"ש והארץ אזכור<sup data-n=\"10707\">580</sup> כו'. ואמנם בזאת יתרון המעלה באלף הז' דעוה\"ב שיהי' בחי' עליית המל' למעלה [ממקור] הוימ\"ב דוא\"ש עד שהם יקבלו מקור הברכה מבחי' המל' דאו\"כ<sup data-n=\"10708\">581</sup> עצמו שנק' ברכת ה' היא תעשיר כו', והוא מ\"ש ויברך אלקי' ויקדש אותו בבחי' קדושה <span data-k=\"pg\">644</span> ּ העצמי' ממש שזהו ביום שכולו שבת דעוה\"ב שאז תכלית העילוי שאין עוד עלי' למעלה מזה כנ\"ל (ומ\"ש<sup data-n=\"10709\">582</sup> ז\"ל דת\"ח אין",[["10704","577","<b>צדיקים יסודי</b>: ה: צדיק יסוד."],["10705","578","<b>במל' שנק' שכינה</b>: נסמן לעיל פ' שמות א, ד."],["10706","579","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["10707","580","<b>והארץ אזכור</b>: בחוקותי כו, מב."],["10708","581","<b>דאו\"כ</b>: בה: דא\"ס."],["10709","582","<b>(ומ\"ש</b>: ה: וז\"ש."]]],[2300540898,"להם מנוחה אפי' בעוה\"ב כו' זהו לאחר העוה\"ב כמו ענין מיכאל מקריב נשמות<sup data-n=\"10710\">583</sup> ע\"ג המזבח דאצי' לאשתאבא בגופא דמלכא<sup data-n=\"10711\">584</sup> ממש שזהו נשמות שעלו [מ]געה\"ע דבריאה. כך נשמות דעוה\"ב שאינו רק כמו געה\"ע דעכשיו, כידוע ומבואר במ\"א דתחה\"מ שלפני עוה\"ב הוא בחי' ממוצע<sup data-n=\"10712\">585</sup> בין ימוהמ\"ש (שהוא כמו געה\"ת דעכשיו) לעוה\"ב כמו נה\"ד שטובלים בו [ה]נשמות<sup data-n=\"10713\">586</sup> בעלותם מגעה\"ת לגעה\"ע, וכך תחה\"מ הוא בחי' טהרה מטלא דנטיף<sup data-n=\"10714\">587</sup> כו' שיבאו בבחי' ביטול ממהות הראשון כו' והוא בחי' ביטול לגופי' כמו ביטול לנשמות ב[נ]ה\"ד כו' וד\"ל. וכמו\"כ יהי' עלי' הב' מעוה\"ב למעלה יותר בעצמו' השעשועי' שז\"ש ת\"ח אין להם מנוחה כו' כמו עליי' הנשמות במזבח כו', וזהו שא' שיתא אלפי שני דהוי עלמא וחד חרוב בבחי' ביטול המציאות דקאי בעוה\"ב מטעם זה כמ\"ש במ\"א (ע\"פ ובבואה לפני המלך<sup data-n=\"10715\">588</sup> וד\"ל).",[["10710","583","<b>מיכאל מקריב נשמות</b>: ראה גם לעיל פ' שמות ה, א. וש\"נ."],["10711","584","<b>לאשתאבא בגופא דמלכא</b>: נסמן לעיל ה, ב."],["10712","585","<b>דתחה\"מ. . ממוצע</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ס\"ע תיב ואילך. לקמן פ' ויקהל תכט, ב."],["10713","586","<b>נה\"ד שטובלים בו [ה]נשמות</b>: ראה גם לעיל ה, ד. וש\"נ."],["10714","587","<b>מטלא דנטיף</b>: ראה גם לעיל ז, ב ובהערה 312."],["10715","588","<b>ובבואה לפני המלך</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' תיב ואילך."]]],[2300540078,"<b>ב\"ה שמחת תורה שנת תקפ\"ו לובאוויטש יע\"א</b>\n<span data-k=\"pg\">שכב</span> ּ<b>צדקת</b> פרזונו<sup data-n=\"10716\">1</sup> בישראל<sup data-n=\"10717\">2</sup> וארז\"ל א\"ת פרזונו אלא פזרונו<sup data-n=\"10718\">3</sup> צדקה עשה הקב\"ה<sup data-n=\"10719\">4</sup> בישראל<sup data-n=\"10720\">*5</sup> שפיזרן בין אוה\"ע כו'. הנה ארז\"ל והנצח זו בנין ירושלים<sup data-n=\"10721\">5</sup> שבנין ירושלים [ד]לע\"ל יבנה מבחי' מדת הנצח העליון שלא הי' כזה בבנין ירושלים שבבית ראשון כו'. ולכאו' מאמר זה פלא[י] דמה שייכות יש [ל]בנין ירושלים למדת הנצח דוקא כו' (והלא הנצח אינו רק ענף החסד<sup data-n=\"10722\">6</sup> בלבד וכמ\"ש<sup data-n=\"10723\">7</sup> נעימות בימינך נצח<sup data-n=\"10724\">8</sup> כו', ובנין העולם כולו במדת החסד עצמו כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"10725\">9</sup> כידוע, ומוכרח לומר מזה ששרש מדת הנצח למעלה מרצון וח\"ס<sup data-n=\"10726\">10</sup>, ולמעלה גם מתענוגים הפנימים שבנפש וע\"כ יהי' [בנין] ירושלים דלע\"ל נצחיות וד\"ל). אך הענין הוא במה שירושלים דלע\"ל הוא נצחי מפני שיבנה במדת הנצח שמגיע שרשו בפנימיות ועצמי' שלמעלה מכל התענוגים.\n<b>דהנה</b> אנו רואים במלכותא דארעא שמאציר המלך אוצרות רבים מזהב וכסף על<sup data-n=\"10727\">11</sup> הנוסף על הצטרכות לעצמו",[["10716","1","<b>צדקת פזרונו</b>: מיוסד על ד\"ה זה ש(נאמר בשמח\"ת תקס\"ו) נדפס במאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקפט הנחת כ\"ק אדה\"א. ראה שע\"ת פ, ד (פרקים ז-יג). אוה\"ת יתרו ע' תתקסו. והנחת הר\"מ בן כ\"ק אדה\"ז נדפסה במאמרי אדה\"ז שם. וראה אוה\"ת בשלח ע' עתר ואילך. ראה עוד ע\"ד המאמר לקמן ברשימות הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["10717","2","<b>צדקת פרזונו בישראל</b>: ס' שופטים ה, יא."],["10718","3","<b>א\"ת פרזונו אלא פזרונו</b>: ראה שע\"ת כאן (פ, ד) הערה 39. לקמן רלא, ג. ד. רלה, ג."],["10719","4","<b>צדקה עשה הקב\"ה בישראל</b>: פסחים פז, ב."],["10720","*5","<b>בישראל</b>: חט: עם ישראל, וכ\"ה בהדרושים שנסמנו בריש המאמר — גי' הע\"י."],["10721","5","<b>והנצח זו בנין ירושלים</b>: דהי\"א כט, יא. ראה ברכות נח, א. לקמן רכז, ד. רלא, ג, רלב, ב. רלד, א. רלה, ג פ' תצוה שנב, ג. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' תכ. מאמרי אדה\"א בראשית ע' רפו. וש\"נ. במדבר ח\"א ע' קלד. וש\"נ. תו\"ח ויצא קעב, א. שע\"ת פב, ב. דרמ\"צ יא, ב. קטז, ב. אוה\"ת ש\"ש ע' א'תקכד. סה\"ש תנש\"א ח\"א ע' 277 הערה 77 ובשולי הגליון שם."],["10722","6","<b>הנצח. . ענף החסד</b>: נסמן לעיל רכא, ב."],["10723","7","<b>וכמ\"ש</b>: ט: כידוע במ\"ש."],["10724","8","<b>נעימות בימינך נצח</b>: תהלים טז, יא."],["10725","9","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["10726","10","<b>וח\"ס</b>: חט: שבחכ' וחסד."],["10727","11","<b>על</b>: שם: ליתא."]]],[2300540116,"ולאנשי המדינה מן המסים על כל השרים שכבשם מדי שנה בשנה שנוסף<sup data-n=\"10728\">12</sup> הון רב, וגם מאשר כובש מדינות רבות ושללם לבוז כידוע. וגם מלכים הראשונים אבותיו אצרו אוצרות רבים בכל משך חייהם דור אחר דור וכל אוצרות המלך ואוצרות אבותיו כל הון יקר<sup data-n=\"10729\">13</sup> וגדול הזה נאצר באוצר המלך סגור יהי' ומוצנע חתום בחותם המלך תחת יד הממונה על האוצרות ולא יקחו ויוציאו משם להצטרכות גם להנצרך ביותר לפי שעה, וגם מה שיביאו לו כסף וזהב מסים ומנחות ממלכי ארץ ורוזנים הכל<sup data-n=\"10730\">14</sup>, וגם מה שי[ר]ש מאבותיו כל כלי יקר וחמדה מאבנים טובות ומרגליות וסגולת מלכים בהפלגת ויקר הערך מאד שלא יערכם זהב וכסף כלל הכל מאציר באוצר המלך, וע\"כ נק' אוצרות [ש]מתקבצים ונאצרים בהן הון רב בלי שיעור מפני שלא יגע בהן יד לעולם ולא יפתחו משך זמן רב כמה מאות שנים, וכ\"ש שלא יגיעו להשתמש בכלים וחפצים יקר היקרים ונחמדים מזהב ומפז [רב] אפי' כלי א' רק הם טמונים ומוצנעים אוצרות המלך, ואף כשצריך המלך להוצאות הכרחים מאד לא יסתפק מן האוצרות לעולם שאם הי' מוציא ומסתפק מהן לעת ההכרח לא היו נאצרים הון רב כ\"כ ולא יקרא אוצר כלל, אלא כאשר הנאצר טמון ומוצנע לעולם הוא שנק' מטמונים כמש\"א ג' מטמונים הטמין יוסף כשליקט כל הכסף<sup data-n=\"10731\">15</sup> כו', וכתיב אם כמטמונים תחפשינה<sup data-n=\"10732\">16</sup> דמשמע שהמטמון והאוצר טעון חיפוש גדול (שע\"פ רוב השמירה לאוצר של ממון בעומק הקרקע וכלי יקר מאבנים טובות ומרגליות בחדרים מוצנעים מעין כל רואה כו'), לפי שהמטמונים והאוצרות סגורים וצנועים בתכלית ההסתר מעין כל כידוע. ואף שלפעמים חפץ המלך להשתעשע ולהתענג בכלי חצו יקר<sup data-n=\"10733\">17</sup> וסגולת מלכים שנטמנו באוצרות[יו] ואוצרות אבותיו או להראותם לפני שר גדול [או] אוהבו וריעו כנפשו, לא ירצה ליקח מן האוצרות הטמונים מכבר, כי אינו חפץ ואינו לפי כבודו שיגלה לעין רואה מאוצרות[יו] ומטמוני[ו] [ה]מוסתרים שנטמנו זה כמה מא[ות] שנים וגם <span data-k=\"pg\">646</span> ּ מאשר נאצר על [ידו] להיות מונח לעת הצורך הגדול, וברצותו להשתעשע בכלי חמדה יקר<sup data-n=\"10734\">18</sup> מן המוכן בביתו לשולחנו כיד המלך להתכבד לפני השרים והמלכים כו'. אך זה<sup data-n=\"10735\">19</sup> לפרקים רחוקים מאד כמו בעת שהוא עושה משתה ושמחה גדולה על ענין גדול כמו בכיבוש מלחמה גדולה (כמו שצוה<sup data-n=\"10736\">20</sup> בלטשאצר<sup data-n=\"10737\">21</sup> להביא כלי המקדש), או בעת שהוא עושה משתה ושמחה ביום חתונתו, או כשבת המלך על כסא מלכותו<sup data-n=\"10738\">22</sup> וכה\"ג, אז יצוה גם להוציא כלים היקרים כל כלי חמדה וסגול[ו]ת מלכים הטמונים באוצרותיהם להראות את יקר תפארת גדולתו ועושר כבוד מלכותו לפני היושבים במשתה משרי המלך הפרתמים כמבואר במשתה דאחשורוש וכדומה",[["10728","12","<b>בשנה שנוסף</b>: ח: בשנה עד שנאסף. ט: עד שנאסף."],["10729","13","<b>כל הון יקר</b>: משלי א, יג. כד, ד."],["10730","14","<b>הכל</b>: חט: כו'"],["10731","15","<b>ג' מטמונים הטמין יוסף כשליקט כל הכסף</b>: ויגש מז, יד. ראה פסחים קיט, א."],["10732","16","<b>אם כמטמונים תחפשינה</b>: משלי ב, ד [ושם: אם תבקשנה ככסף וכמטמונים תחפשנה — ראה לקמן רכה, ג. מאמרי אדה\"א ויקרא ח\"ב ע' תקעד. וש\"נ. תו\"ח ויחי רמז, ד]. ראה גם תו\"ח שם."],["10733","17","<b>חצו יקר</b>: ח: יקר חפצו. ט: חפצו היקרים."],["10734","18","<b>יקר</b>: ט: יקח."],["10735","19","<b>זה</b>: ט: ורק."],["10736","20","<b>שצוה בלטשאצר להביא כלי המקדש</b>: דניאל ה, ב ובמפרשים שם."],["10737","21","<b>בלטשאצר</b>: וכ\"ה בח (!). ט: בלשאצר."],["10738","22","<b>המלך. . מלכותו</b>: ח: ליתא. . ממלכתו. — ע\"פ פ' שופטים יז, יח."]]],[2300540154,"לזה, וכ\"ש וק\"ו שלא ימכרם בכל הון שבעולם אף בעת הצורך גדול מאד. והנה מכ\"ז אנו רואים גודל עוצם הפלאת יקר הערך של [ה]כלים הגנוזי' באוצרותיהם שהן כלי חמדתו היקרים בעיניו כ\"כ, עד שגם בגודל התענוג והשמחה שחפץ להתענג ולהשתעשע בכלי חמדה אין התענוג שלו שוה כלום כשישתמש בהן לגבי עוצם מעלת ערך י[ו]קרם וחשיבותם בעצם, ע\"כ מבטל רצונו ותענוגו ואינו חפץ להשתמש בהן ואף לא להראותם ולגלותם לשום שר וחשוב [ו]רעים אהובים, רק בעת חתונתו או חתונת בנו<sup data-n=\"10739\">*23</sup> או בעת ישועה ונחמה גדולה לפרקים יחפוץ להראות יקר תפארת גדולתו בהם דוקא כנ\"ל וד\"ל.\n<b>וא\"כ</b> לכאורה יפלא מאד מאד על היפך על<sup data-n=\"10740\">23</sup> הנ\"ל, במה שאנו רואים שיוכל המלך לבזבז כל אוצרותיו ואוצרות אבותיו מימי קדם בשביל כיבוש ונצחון מלחמה עם שונאו, דהנה אנו רואים שכאשר צריך המלך לכבוש ולנצח לאויביו שרוצה להרחיב מלכותו, או גם כדי לכבוש מדינות מלכים זולתו בניצוח מלחמה להראות גבורתו, או בניצוח מלחמה שיש לו עם מלך א[חר] מימים קדמונים, שאז יזיל כל זהבו וכספו הנמצא תחת ממשלתו, ואם לא יספיק ולא יהיו [לו] עוד להוצאות המלחמה יקח גם אז מן האוצר[ות] שלו או גם מאוצרות אבותיו שנאצרו משנים קדמונים בימי [אבות] אבותיו הקדמונים<sup data-n=\"10741\">24</sup>, ואם לא יספיק עוד יקח גם מכל הון יקר של כלי חמדה ואבנים טובות כו' להוציאם במחיר רב על הוצאו' המלחמה עד שישלים הניצוח ויכבוש מלחמתו [כ]רצונו כו', וכידוע שזהו בנימוסי המלכות<sup data-n=\"10742\">25</sup>, וא\"כ יהי'<sup data-n=\"10743\">26</sup> היפך גמור מענין הנ\"ל בעוצם י[ו]קר הערך של כל[י] האוצרות עד שלא יקח אותם לשום דבר הכרחי כו'.\n<b>אך</b> הענין הוא לפי שידוע בענין המלחמה ב' דברים, הא' גופו של ענין הכיבוש לכבוש מדינות ועיירות רבות להרבות שלל ורכוש ולהרחיב גבול ארצו, והב' הוא ענין ההתנשאו'<sup data-n=\"10744\">27</sup> והרוממות שיהי' רם ונשא וגבוה מזולתו ויהי' כל תוקף וגדולה שלו מכל הנ\"ל<sup data-n=\"10745\">28</sup> שלא ירום איש ראשו, וע\"כ גם מדינה קטנה בערך שאינה שוה אפי' א' מאלף שיוציא ויבזבז עליו מאוצרו מ\"מ יכול להוציא ולבזבז הכל כנ\"ל. וכש\"כ וק\"ו אשר<sup data-n=\"10746\">29</sup> שר הארץ ההוא מורד ומתנשא ועומד לנגדו שיגדל יותר הכעס והנצחון להאבידו ולהשפילו כו'. ואמנם לגבי מדת ההתנשאו' או כדי להשיג הון ורכוש גדול [יש] לזה סברא מנגדת, והוא מפני שבאמת לגבי <span data-k=\"pg\">שכג</span> ּ רוממות ערך גדולתו כלא ממש חשיב התנשאות שר ומלך קטן זולתו והגם שיר[י]ם ראש גם הוא כו', וכ\"ש העושר והרכוש שישיג ממנו שאינו שוה בנזק המלך בכלי יקרו",[["10739","*23","<b>חתונת בנו</b>: ראה גם שיחת ש\"פ וישב תשי\"ד סי\"א ואילך."],["10740","23","<b>על</b>: חט: ענין."],["10741","24","<b>הקדמונים</b>: ט: ליתא."],["10742","25","<b>המלכות</b>: ח: המלך. ט: המלכי'. — וכ\"ה במאמרי אדה\"ז כאן (ע' תתקצא)."],["10743","26","<b>יהי'</b>: שם: זהו."],["10744","27","<b>ההתנשאו'</b>: ט: התפארו'."],["10745","28","<b>מכל הנ\"ל</b>: חט: על הכל."],["10746","29","<b>אשר</b>: שם: אם."]]],[2300540191,"וחמדתו הגנוז באוצרותיו מימי קדם אפי' חלק א' מאלף אלפים כו' ולזאת לא יבזבז כלום ע\"ז כידוע. אך א\"א לומר בטעם סיבת הרצון לבזבז כל אוצרות שלו בשביל כיבוש המלחמה עם שונא[ו] כנ\"ל, רק מצד מדת הנצח שהוא הנצחון שלמעלה מן הטעם לגמרי דהיינו רק שיהי' [כ]רצונו דוקא ולא [כ]רצון [אחרים] זולתו ולהכניע לזולתו שעומד כנגדו שיבוטל אל רצונו בתכלית, ועיקר הנצחון אינו [בא] רק מצד המנגד שעומד לנגד רצונו בדבר זה, הגם שדבר זה קטן הערך מאד בעיניו ואין רצונו עליו כ\"כ וגם יכול להיות שיהי' הדבר נגד רצונו לעצמו, מ\"מ כאשר המנגד יקום לנגדו ומונע אותו מדבר זה יעמו[ד] לנגדו [מאד] בכל תוקף ועוז והוא עיקר תוקף הנצחון בעצם והוא רק תוקף הרצון שישאר [כ]רצונו וישאר בדעתו<sup data-n=\"10747\">30</sup>, ואעפ\"י שיש לו טעם בדבר ואותו הטעם בטל מ\"מ יעמוד בנצחו[נו] בלי יזוז מכל גם להשליך כל אשר לו מנגד כאלו הדבר מגיע בפנימיות חיות נפשו [ממש] כידוע. וא\"כ הרי אנו רואים בחוש במדת הנצחון הגם שהוא בקרירות בלא<sup data-n=\"10748\">31</sup> רשפי אש התשוקה ורצון כלל מ\"מ יגיע לנקודת פנימית הנפש שלמעלה מכל הרצונות ותענוגים שבפנימיות נפשו, מאחר שיוכל להשליך הכל מנגד רק בשביל ניצוח זה שיקום כרצונו דוקא בדבר מה [יהי' מה] שיהי', כמו שאם הי' נוגע הדבר בפנימית בנפשו ממש, [ו]יותר מזה שהרי יוכל להפקיר גם חיי נפשו למות בשביל ניצוח שלו כיוצא למלחמה לכבוש אויביו העומד לנגדו בדבר מחלוקת קטנה שאינה בערך שיוציא הוצאות קטנות ע\"ז וכש\"כ להשליך נפשו מנגד כו', כמו שאם הי' אויבו יוצא עליו להחריב כל אשר לו ולירד נפשו<sup data-n=\"10749\">32</sup> ממש. וזהו שהנצחון הוא למעלה גם ממקור הרצון והתענוג הגדול שהרי בשביל כל התענוגים ורצונו[ת] היותר יקרים בנפשו לא יעמוד במלחמה להשליך נפשו עליהם רק על חייו ממש או דבר יקר כחייו ממש כבנו וגם עיר ממלכתו וכסא היכלו שלא ילכד הכל ביד שונא[יו] וכה\"ג וכידוע וד\"ל.\n<b>וכך</b> יובן בטעם ענין הנ\"ל שיכול המלך לבזבז כל אוצרות[יו] כדי לנצח את שונאו מפני שתגדל בעיניו ניצוח המלחמה יותר מכל הון יקר ונחמד שאינו שוה כלום לגבי התענוג [הגדול] הזה שבניצוח זה גם כל תענוגי [אוצרותיו וכלי חמדה שיקרי' בעיניו יותר מכל התענוגי' שלו כנ\"ל, א\"כ הרי אנו רואים בחוש שבחי'] מדת הניצוח הזה הגם שהוא בדבר קטן הערך מאד כמו שר ומלך קטן והמחלוקת בדבר קטן [מאד], מ\"מ יש לבחי' ניצוח זה שיהי' כרצונו דוקא מקום גדול בפנימיות [ו]עצמות נפש המלך עד שיאבד כל אשר לו מחמת הנ\"ל וגם [י]שליך נפשו מנגד ע\"ז כנ\"ל, וע\"כ יבזבז כל אוצרות[יו] הנחמדים<sup data-n=\"10750\">33</sup> מפני זה",[["10747","30","<b>וישאר בדעתו</b>: שם: ודעתו דוקא."],["10748","31","<b>בלא</b>: ח: בלי חום. ט: בלי שום."],["10749","32","<b>נפשו</b>: שם: לחייו."],["10750","33","<b>הנחמדים</b>: ט: ניתוסף: מזהב ומפז רק."]]],[2300540225,"הניצוח שגדול יותר מכל התענוגי' המופלגים שבכל עושר והון יקר כו' עד שיבוז בעיניו הכל מפני מדת<sup data-n=\"10751\">34</sup> הניצוח וד\"ל.\n<b>והנה</b> הנמשל מכ\"ז יובן ג\"כ במל' דרקיע לעילא [לעילא] להיות כי קוב\"ה<sup data-n=\"10752\">35</sup> סתים וגליא<sup data-n=\"10753\">36</sup> והוא ב' מדות דאוא\"ס ב\"ה עצמו כמו שהן בעצמותו ממש שהוא מקור כל בחי' ההעלם והגילוי בכלל וכידוע שכח המתפשט מעצמות דא\"ס נק' גם הוא <span data-k=\"pg\">648</span> ּ א\"ס שא\"ס להתפשטותו כלל וכמ\"ש [ו]לגדולתו אין חקר<sup data-n=\"10754\">37</sup> כו', דהיינו מה שנתפשט מהארת או[ר ד]א\"ס בשביל השתלשלו' כל העולמות והוא כל [ה]השתל' דקו\"ח דאבי\"ע זהו בבחי' א\"ס ממש שהוא בחי' התפשטות בלי גבול ושיעור כלל וזהו שאא\"ס למטה עד אין קץ<sup data-n=\"10755\">38</sup> כו'. וענין למטה זה היינו גם במקור דע\"ס דאצי' שנאצלו ע\"י צמצומי' דקו\"ח שאינו רק הארה [א'] מעצמות המאציל כניצוץ לגבי השלהבת כמ\"ש בס\"י כשלהבת הקשורה בגחלת<sup data-n=\"10756\">39</sup> בהעלם כו' ([ו]כמו יו\"ד כחות הכלולים בהעלם בעצמות הנפש כידוע) גם באור [מ]צומצם הזה הי' מתפשט עד אין שיעור כלל, והוא למעלה גם מבחי' הגבלת האורות דע\"ס והכלים שבאים במספר עשר דוקא [כ]רצון וחו\"ב ומדות ומחדו\"מ שכל אלה באים ע\"י [ה]צמצום דקו המדה כידוע, אבל מצד התפשטות דאוא\"ס עצמו הי' מתחלק לריבו[א] רבבות ספירות ומדות עד אין שיעור כלל<sup data-n=\"10757\">40</sup> מאחר שמצד עצמו נק' חד ולא בחושבן<sup data-n=\"10758\">41</sup> י\"ס כלל וכמ\"ש ולאו מכא\"מ כלל<sup data-n=\"10759\">42</sup>, א\"כ מה שנאצלו במספר דעשר בכלים מכלים שונים גם בחי' [המקיפים דכח\"ב דא\"ק וע\"י וכה\"ג עד גם המקיף הכללי שמקיף לד' עולמות דאבי\"ע שגם] הוא בא במדה ושיעור כידוע בערך הקפת החומה<sup data-n=\"10760\">43</sup> לפני<sup data-n=\"10761\">44</sup> העיר וכמו הכלל לגבי הפרט כמ\"ש במ\"א, הנה כ\"ז בא ע\"י צמצום הראשון דקו\"ח שנותן מדה ושיעור לכל ההשתל' דאבי\"ע עד סוף העשי'. וז\"ש לך הוי' הגדולה<sup data-n=\"10762\">45</sup> וכו' שהן ז\"מ דאצי' ולמעלה מעלה במקורם הראשון במדות דעצמו' המאציל ש[נ]משכו לאצי' ומאצי' לבי\"ע שנק' ז' ימי הבנין בכלל הרי הם כלולים ובטלים בעצמות א\"ס שהי' בתכלי'<sup data-n=\"10763\">46</sup> ביכולתו להאציל ולברוא כו' עד אין שיעור כלל למעלה מצמצום והתפשטו' דז\"מ הללו, ע\"כ אמר לך הוי' הגדולה כו' דכלא ממש חשיבי כל בחי' התפשטו' הגדולה שהוא החסד שבא בשביל השתל' דאבי\"ע לגבי אור העצמות [דא\"ס] שלגדולתו [שזה] התפשטות החסד עצמו<sup data-n=\"10764\">47</sup> כו' וד\"ל (וראי' לזה גם מבחי' האחרונה שבי\"ס שהוא בחי' המל' כידוע שהתפשטות מד' זו בי\"ס וצירופים רבים שמסתעף מכח שם אדנ\"י<sup data-n=\"10765\">48</sup> ואלקים<sup data-n=\"10766\">49</sup> נמשך עד אין שיעור כלל כמ\"ש בס\"י ה' אבנים<sup data-n=\"10767\">50</sup> בונות ק\"ך בתים [כו'] המליך אותו<sup data-n=\"10768\">51</sup> כו' עד מכאן ואילך צא וחשוב<sup data-n=\"10769\">52</sup> כו', ועכ\"ז נתן",[["10751","34","<b>מדת</b>: דח: ליתא."],["10752","35","<b>כי קוב\"ה</b>: דחט: ידוע דקוב\"ה."],["10753","36","<b>קוב\"ה סתים וגליא</b>: ראה זהר אחרי עא, ב. עג, א."],["10754","37","<b>[ו]לגדולתו אין חקר</b>: תהלים קמה, ג."],["10755","38","<b>שאא\"ס למטה עד אין קץ</b>: נסמן לעיל פ' שמות ד, ד הערה 214."],["10756","39","<b>כמ\"ש בס\"י כשלהבת הקשורה בגחלת</b>: פ\"א, מ\"ז."],["10757","40","<b>ספירות ומדות עד אין שיעור כלל</b>: ראה גם מאמרי אדה\"א קונטרסים ע' ו. וש\"נ. שערי אורה פב, ב ובהערה 12."],["10758","41","<b>חד ולא בחושבן</b>: ת\"ז בהקדמה (יז, א)."],["10759","42","<b>ולאו מכא\"מ כלל</b>: ת\"ז שם (יז, ב)."],["10760","43","<b>בערך הקפת החומה</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' רמה."],["10761","44","<b>לפני</b>: דחט: לפי ערך."],["10762","45","<b>לך הוי' הגדולה</b>: דהי\"א כט, יא."],["10763","46","<b>בעצמות. . בתכלי'</b>: דחט: בתכלית בעצמות א\"ס שהי'."],["10764","47","<b>עצמו</b>: גח: העצמי אין חקר. ט: חסר."],["10765","48","<b>המל'. . אדנ\"י</b>: ראה גם לעיל פ' וארא עה, ב. וש\"נ."],["10766","49","<b>המל'. . ואלקים</b>: ראה גם לעיל שם. וש\"נ."],["10767","50","<b>בס\"י ה' אבנים</b>: נסמן לעיל ס, ג."],["10768","51","<b>המליך אותו </b>[גח: אות. ט: חסר]: ס\"י פ\"ה, מ\"ב."],["10769","52","<b>מכאן ואילך צא וחשוב</b>: ס\"י פ\"ד, מי\"ב."]]],[2300540257,"בזה שיעור ומדה כמו שיעור קומה<sup data-n=\"10770\">53</sup> של יוצר בראשית שהוא [רל\"ו] רבבות אלפים [פרסאות כו'] בגימ' דורב כח<sup data-n=\"10771\">54</sup> כמ\"ש במ\"א (וכן בו\"ק דז\"א<sup data-n=\"10772\">55</sup> ואף<sup data-n=\"10773\">56</sup> רבבות ספי' כו'). ועוד ראי' מחידוש מע\"ב וכל העולמות הרוחנים מלפני האצי' כו' מתחדש לאין שיעור כלל וכמו בעליות וירידות בחי' שבת<sup data-n=\"10774\">57</sup> ושמיטה דוא\"ש כו').\n<b>ובזה</b> יובן מה שאנו אומרים בקדיש דיתגדל כו' לעילא מן כל ברכתא ושירתא כו' דאמירן בעלמא, פי' דאמירן בעלמא היינו מה שיוכל להיות בגילוי מן ההעלם בדבור שזהו דאמירן בעלמא שיוכל ואפשר להיות נאמר בעולמות, דהיינו רק במה שנתפשט מהארת אוא\"ס ב\"ה בע\"ס דאבי\"ע כח\"ב<sup data-n=\"10775\">58</sup> ומדות וכה\"ג שזהו שיוכל לבא בשבח ותהלה בדיבור כמו לך הוי' הגדולה כו' כמו שנק' חכים <span data-k=\"pg\">שכד</span> ּ ומבין<sup data-n=\"10776\">59</sup> כו' וגם זה שמתפשט לאין שיעור כלל כנ\"ל. וזהו דאמירן בעלמא דע\"ז בלבד הוא דאמירן בעלמא דעלמא דאתכסיא ועלמא דאתגלי'<sup data-n=\"10777\">60</sup>, והוא ענין ברכתא ושירתא כל בחי' המקיפים שנק' ברכה בשם הוי' ושירות ותשבחות להלל לשם הוי' כו' שכ\"ז הוא בע\"ס שנאצלו מן עצמות המאציל שנמשך לבי\"ע וכתיב לך הוי' הגדולה כו' שזהו דאמירן בעלמא עכ\"פ. אבל מה שהי' ביכולת כח הא\"ס להתפשט בעולמות למעלה מע\"ס דחו\"ב ומדות כנ\"ל שהי' יכול להאציל עד אין שיעור כלל שלא בבחי' רצון וחו\"ב [ומדות] דחג\"ת כלל, וגם מה שנתפשט בע\"ס נתצמצם וניתן במדה ושיעור בכל ההשתל' [ה]נ\"ל א\"כ זהו לעילא מן כל ברכתא כו' דאמירן כבר בעלמא לפי שזה האור לא נאמר בעלמא עדיין, ומה דאמירן בעלמא אינו רק אפס קצהו הארה בלבד וגם זה בטל בעצמות כו'<sup data-n=\"10778\">61</sup>, וכידוע דכל ההשתל' דקו\"ח אינו רק זיו והארה בעלמא משמו הגדול שהוא בחי' מל' דא\"ס<sup data-n=\"10779\">62</sup> שע\"ז אמר שהי' הוא ושמו בלבד<sup data-n=\"10780\">63</sup>, וזהו שאו' משובח ומפואר<sup data-n=\"10781\">64</sup> עדי עד שמו הגדול כו' וקאי אדסמיך לי' ובשירי דוד עבדך נהללך עד יחיד חי העולמים מלך כו' [ש]מתצמצם בתשבחות הללו דע\"ס דאבי\"ע כי מצד עצמו לאו מכא\"מ כלל והוא לעילא ולעילא מן כל ברכתא כו' (בעי\"ת שהוא בעליות העולמו' במל' דא\"ס עצמו ע\"כ או[מר] לעילא ולעילא<sup data-n=\"10782\">65</sup> ), וכמ\"ש לך דומי' תהלה<sup data-n=\"10783\">66</sup> ונק' נורא תהלות<sup data-n=\"10784\">67</sup> כו' וכתיב מי ימלל גבורות ה'<sup data-n=\"10785\">68</sup> כו' וכן א' נפלאותיך ומחשבותיך עצמו מספר<sup data-n=\"10786\">69</sup> וכה\"ג ואעפ\"כ או' יש\"ר<sup data-n=\"10787\">70</sup> מברך שמי\"ר<sup data-n=\"10788\">71</sup> הנ\"ל בחי' מל' דא\"ס עצמו מברך לעלם כו' ויתברך וישתבח כו' רק",[["10770","53","<b>שיעור קומה</b>: נסמן לעיל ריב, ד."],["10771","54","<b>[רל\"ו] רבבות. . דורב כח</b>: תהלים קמז, ה. ראה הנסמן בהערה שלפנ\"ז."],["10772","55","<b>בו\"ק דז\"א. . ספי'</b>: נסמן לעיל ריב, ד."],["10773","56","<b>ואף</b>: גח: ו' אלפי'."],["10774","57","<b>בחי' שבת</b>: דח: דחול ושבת."],["10775","58","<b>כח\"ב</b>: ד: כחו\"ב. ח: בחו\"ב."],["10776","59","<b>חכים ומבין</b>: ת\"ז בהקדמה (יז, ב)."],["10777","60","<b>דעלמא דאתכסיא ועלמא דאתגלי'</b>: נסמן לעיל פ' שמות לג, א."],["10778","61","<b>כו'</b>: דח: כנ\"ל."],["10779","62","<b>משמו הגדול. . מל' דא\"ס</b>: נסמן לעיל פ' שמות ה, ג."],["10780","63","<b>שהי' הוא ושמו בלבד</b>: נסמן לעיל פ' וארא נג, ב."],["10781","64","<b>משובח ומפואר</b>: נוסח ברוך שאמר."],["10782","65","<b>בעי\"ת. . לעילא ולעילא</b>: שו\"ע אדה\"ז הל' ר\"ה סתקפ\"ב, סט\"ז. וראה גם סה\"מ תרל\"ג ח\"ב ע' תקיד בשולי הגליון. שער הכולל פ\"ד, ס\"ט. אוצר מנהגי חב\"ד ר\"ה סצ\"ה-צ\"ח."],["10783","66","<b>לך דומי' תהלה</b>: תהלים סה, ב."],["10784","67","<b>נורא תהלות</b>: בשלח טו, יא."],["10785","68","<b>מי ימלל גבורות ה'</b>: תהלים קו, ב."],["10786","69","<b>נפלאותיך ומחשבותיך עצמו מספר</b>: תהלים מ, ו [בדילוג]."],["10787","70","<b>יש\"ר </b>[דח: יהא שמי' רבא]<b>. . מל' דא\"ס</b>: ראה גם לעיל קעח, ג. וש\"נ."],["10788","71","<b>מברך שמי\"ר</b>: שם: ליתא."]]],[2300540287,"שיתברך לעילא מן כל ברכתא כו' דאמירן בעלמא כו' כמשי\"ת וד\"ל.\n<b>והנה</b> ידוע דכמו שבחי' החסד דאוא\"ס [ב\"ה] מתפשט למטה מטה עד אין שיעור ותכלית<sup data-n=\"10789\">72</sup> כנ\"ל, כך בחי' הגבורה שבאוא\"ס הוא בחי' העלאה בעילוי אחר עילוי בעצמות[ו] בבחי' הרוממות וההתנשאו' העצמי' שאין לו שיעור למעלה מעלה כמו שאין לו שיעור להתפשטו' למטה כנ\"ל והוא בחי' העלם אחר העלם סדכ\"ס<sup data-n=\"10790\">73</sup> כמשי\"ת, כי מה שנמשך בבחי' צמצום בקו\"ח כנ\"ל זהו הצמצום שבגילוי אור השפע עצמו' שצמצם אור העצמות ולא נמשך רק הארה א' מצומצמת בלבד כו' (והוא ענין מה ששיער בעצמותו בכח<sup data-n=\"10791\">74</sup> מה שעתיד להיות בפועל בגילוי [כו'] שזהו גליף גליפו בטה\"ע<sup data-n=\"10792\">75</sup> שעי\"ז נמשך ע\"ס במספר כו' וד\"ל<sup data-n=\"10793\">76</sup>, ע\"כ מה שנשאר בהעלם אור העצמות דא\"ס כמו שהי' ביכולתו להאציל עד אין שיעור כו' וצמצם א\"ע שנשאר בהעלם העצמות ולא נשאר ממנו רק בחי' רושם בלבד ועצם האור נכלל בעצם המאור כו' (שזהו ענין המק\"פ וחלל ריקן<sup data-n=\"10794\">77</sup> כנ\"ל במשל<sup data-n=\"10795\">78</sup> הרצון המוחלט<sup data-n=\"10796\">79</sup> [מ]זמן רב הנכלל בעצם ובא בגילוי מן ההעלם אפס קצהו או כמו הנזכר על דבר שעולה בשכלו כבר<sup data-n=\"10797\">80</sup> כמ\"ש במ\"א, שכ\"ז אינו שייך לו<sup data-n=\"10798\">81</sup> רק לבחי' הגילוי שבא מן ההעלם וצמצום הזה ([ו]כמו שאמר לעולמו די<sup data-n=\"10799\">82</sup> כו' שלא יתפשט הכל בבחי' א\"ס כנ\"ל). אבל בחי' העלא' דגבורות בעילוי אחר עילוי בעצמות[ו] זהו למעלה מבחי' הצמצום הנ\"ל שאינו רק לגבי השפע הנמשך בקו\"ח <span data-k=\"pg\">650</span> ּ לבד, אבל העלא' זה היינו בחי' התנשאות ורוממות המעלה בעילוי אחר עילוי עד אין שיעור למעלה כנ\"ל, זהו הכל בעצם האור דא\"ס עצמו כמו שהוא באמיתי' עצמותו שאין לו שיעור למעלה מעלה כנ\"ל שהוא למעלה הרבה [ונ]בדל בערך לגמרי מבחי' הצמצום הנ\"ל<sup data-n=\"10800\">83</sup> והתפשטות שנמשך בהשתל', אעפ\"י שגם בחי' [ה]התפשטות הוא בחי' א\"ס אבל זהו התפשטו' לבד למטה וגם זה בא ע\"י צמצום דכלא חשיב ממש כו' כמ\"ש לך הוי' הגדולה. אך זה<sup data-n=\"10801\">84</sup> בחי' הרוממות בעצמות אעפ\"י שאין לו שיעור למעלה אין זה בחי' מהו\"ע ית' [ממש] וכידוע בענין עומ\"ר ועומ\"ת<sup data-n=\"10802\">85</sup> שהן ב' מדות דחו\"ג הנ\"ל באוא\"ס, דעו\"ת הוא היורד ונמשך למטה בהשתל' העולמות כנ\"ל ועמ\"ר היינו העומק של הרוממות והעילוי בעצמות עד אין שיעור למעלה כנ\"ל ונק' עומק של רום כידוע, ואמנם הרי נק' בשם רום ותחת עכ\"פ שהן בחי' תחלה וסוף מעלה ומטה וידוע דעצמות",[["10789","72","<b>שיעור ותכלית</b>: שם: תכלית."],["10790","73","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["10791","74","<b>ששיער בעצמותו </b>[דח: עצמו]<b> בכח</b>: נסמן לעיל פ' בא קב, א."],["10792","75","<b>גליף גליפו בטה\"ע</b>: זהר בראשית טו, א."],["10793","76","<b>וד\"ל</b>: דח: כנ\"ל."],["10794","77","<b>המק\"פ וחלל ריקן</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א, ענף ב."],["10795","78","<b>כנ\"ל במשל</b>: בזכ: כו' כמשל. אגדהחייא: כבפנים."],["10796","79","<b>כנ\"ל במשל הרצון המוחלט</b>: לע\"ע לא נתברר לאיזה מאמר כוונתו."],["10797","80","<b>הנזכר על דבר שעולה בשכלו כבר</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תתקכז."],["10798","81","<b>לו</b>: דח: ליתא."],["10799","82","<b>שאמר לעולמו די</b>: ראה חגיגה יב, א. וראה גם לעיל פ' וארא סב, ד."],["10800","83","<b>הנ\"ל</b>: דח: ליתא."],["10801","84","<b>זה</b>: שם: גם."],["10802","85","<b>עומ\"ר ועומ\"ת</b>: ס\"י פ\"א, מ\"ה."]]],[2300540315,"אוא\"ס ב\"ה למעלה מבחי' מעומ\"ט דעומ\"ר ועומ\"ת עד שמעלה ומטה דעו\"ר ועו\"ת שניהם שוין לפניו [ממש] כי אינם רק בחי' המדות דחו\"ג שמאיר ממנו ואין לזה ערך מהו\"ע ממש, וזהו לך הוי' הגדולה והגבו' כו' שהן [ב'] מדות דחו\"ג דעומ\"ר ועומ\"ת כמ\"ש בשמים ממעל ועל הארץ מתחת אין עוד<sup data-n=\"10803\">86</sup> בשוה וכך בחי' עומ\"ר ועומ\"ת הנ\"ל וד\"ל.\n<b>אך</b> הנה עכ\"ז יש הפרש גדול בין עומ\"ר לעומ\"ת שבחי' העלא' ברוממו' והתנשאות זהו הכל בבחי' אור הנעלם וגנוז בעצמו' דא\"ס אשר לא יוכל לבא לגילוי מן ההעלם לעולם, וע\"כ נק' עומ\"ר שכל דבר המופלא ונעלם ביותר נק' עומק כמ\"ש עמוק עמוק מי ימצאנו<sup data-n=\"10804\">87</sup> כו' ויש עומק אחר עומק עד אין שיעור וכללותם נק' עומקים<sup data-n=\"10805\">88</sup> לשון רבים, וזהו מגלה עמוקות מ[י]ני חשך<sup data-n=\"10806\">89</sup> שהוא בחי' ההעלם דסדכ\"ס דלית מחתב\"כ<sup data-n=\"10807\">90</sup> וד\"ל. והטעם שנק' עומקים ל' רבים לפי שיש עומק אחר עומק שכ\"א לגבי העליון ממנו אינו נק' עומק כלל, כעומק הנעלם של מעיין הנובע לא נק' עומק לגבי מעיינות תהום, וכן עומק הנהר לגבי עומק המעיין שעמוק הוא בתחתית הארץ ביותר. וכך הוא בשכל עמוק של המקבל אעפ\"י שעמוק [הוא] לגבי שלמטה הימנו אינו נק' עומק כלל אצל המשפיע שהוא עליון ממנו, וכן עומק של המשפיע לגבי העליון ממנו, וכך מעילוי לעילוי עד רום המעלות עד הגדול מכולם שעמוק מהכל ואין עמוק יותר ממנו [כו']. וכך יובן למעלה בבחי' עומ\"ר הנ\"ל שזהו עילוי המדריגות ברוממות האור בעצמות א\"ס למעלה מעלה שנק' סדכ\"ס, שכל עומק והעלם אור התחתון אינו נק' עומק כלל לגבי אור העליון ממנו כמו עומק רום דאור החכ' אינו נק' עומק כלל<sup data-n=\"10808\">91</sup> באור הכתר שהוא הרצון<sup data-n=\"10809\">92</sup> שהוא למעלה מן החכ' לגמרי כידוע. וגם הטעם הכמוס לרצון נכלל ובטל ברצון עצמו שאין טעם לרצון כלל<sup data-n=\"10810\">93</sup>, וזהו כמו כל עלול שנכלל בעילתו ואינו ניכר כלל במציאות שם כלל (כמשי\"ת). וכן אור הכתר שהוא הרצון והתענוג כו'<sup data-n=\"10811\">94</sup> בגילוי אור התענוג ורצה\"ע [הנעלם ש]נכלל במקור כל רצה\"ע ותענוג הנעלם<sup data-n=\"10812\">95</sup> ואינו נק' עומק כלל. וז\"ש ממעמקים קראתיך<sup data-n=\"10813\">96</sup> ממקור כל הע[ו]מקים העליונים הנק' עו\"ר כו' (וכידוע בענין יו\"ד עומקי' דעי\"ת<sup data-n=\"10814\">97</sup> בע\"ס עד עומק כשב\"כ שביוה\"כ), ומ\"ם דממעמקי' <span data-k=\"pg\">שכה</span> ּ הוא עומקא דכולא<sup data-n=\"10815\">98</sup> שהוא עצמות א\"ס ב\"ה שנק' סדכ\"ס דלית מחתב\"כ והוא ע\"י תשובה מעומקא דלבא דנקודת מקור כל רצון ותענוג הפנימי' [שבלב], והוא מ\"ם דממעמקים למטה שהוא בחי' מקיף דיחידה מ\"ם דצלם<sup data-n=\"10816\">99</sup> כו'",[["10803","86","<b>בשמים ממעל. . אין עוד</b>: ואתחנן ד, לט."],["10804","87","<b>עמוק עמוק מי ימצאנו</b>: קהלת ז, כד [ושם: ועמוק — ראה של\"ה ח, א]."],["10805","88","<b>עומקים</b>: דח: עמוקות."],["10806","89","<b>מגלה עמוקות מ[י]ני חשך</b>: איוב יב, כב."],["10807","90","<b>דלית מחתב\"כ</b>: ראה ת\"ז בהקדמה (יז, ב)."],["10808","91","<b>לגבי. . כלל</b>: בתו\"ח כאן נכפל עוה\"פ."],["10809","92","<b>הכתר שהוא הרצון</b>: נסמן לעיל עט, א."],["10810","93","<b>שאין טעם לרצון כלל</b>: נסמן לעיל פ' בא פט, ד."],["10811","94","<b>כו'</b>: דח: וכן."],["10812","95","<b>רצה\"ע ותענוג הנעלם</b>: שם: רצון ותענוג העליון."],["10813","96","<b>ממעמקים קראתיך</b>: תהלים קל, א."],["10814","97","<b>יו\"ד עומקי' דעי\"ת</b>: ראה גם פע\"ח (שער תפילות ר\"ה) שכ\"ה, פ\"ז. מאמרי אדה\"א דברים ח\"ב ע' תקמו וע' תכג. וש\"נ. ח\"ג ע' תתיא. וש\"נ."],["10815","98","<b>ומ\"ם דממעמקי' הוא עומקא דכולא</b>: ראה זהר בשלח סג, ב. מאמרי אדה\"א דברים ח\"ג ס\"ע תתקצד ואילך. וע' א'קכח. עט\"ר נה, ב."],["10816","99","<b>מקיף דיחידה מ\"ם דצלם</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תצט ואילך."]]],[2300540340,"כמ\"ש במ\"א וד\"ל, שעי\"ז דוקא נמשך ג\"כ מעומקא דכולא בחי'<sup data-n=\"10817\">100</sup> מקור כל העומקים דע\"ס הגנוז[ו']<sup data-n=\"10818\">101</sup> בעצמות המאציל וד\"ל.\n<b>וזהו</b> מגלה עמוקות מני חשך, דהנה לכאו' אינו מובן למה נק' עמוקות ל' רבים דמשמע שכ\"א מן האורות הנעלמים בהעלם אור העצמי' נק' עומ\"ר בפרט מאחר שלגבי עומק עליון<sup data-n=\"10819\">102</sup> הימנו אינו נק' עומק כלל כו', וצ\"ל מטעם שכל עילה לגבי העלול [ממנו] נק' עומק עכ\"פ לפי שעמוק מכלי המקבל ונשאר בהעלם עלי' כנ\"ל וע\"כ כל עילה נק' עומק לגבי עלול וכל עלול נק' עילה ומשפיע לגבי שלמטה הימנו. אך מפני שכל עילה כשהוא דבוק בעילתו וקרוב אליו לא ניכר שם במציאות כלל ע\"כ נק' חשך, כמ\"ש דאפי' אור צח [כו'] אוכם<sup data-n=\"10820\">103</sup> הוא לגבי עה\"ע עצמו שהוא כאשר מתקרב אליו בדיבוק כמו הלבנה בקירובה אל השמש חשך אורה לגמרי כי שרגא בטיהרא<sup data-n=\"10821\">104</sup> כו' אך בריחוקה דוקא תאיר אורה מן אור השמש [כו'], וכן תלמיד לפני רבו בטל במציאות לפני רבו כפני יהושע בק[י]ר[ו]בו אל משה רבו ונק' נער לא ימיש<sup data-n=\"10822\">105</sup> כו' [ואז] לא יוכל להיות בבחי' משפיע לעלול הימנו כלל. וע\"כ נק' אוכם וחשך מב' טעמים, א' שהוא מצד הביטול עצמותו בעילה שלו בקרבו בתכלית. והב' מה שהוא בבחי' ההעלם וחושך מן המקבלים הימנו כמו איידי דטריד למבלע<sup data-n=\"10823\">106</sup> ולקבל לא פליט להשפיע כלל כמ\"ש במ\"א, והכל ענין וטעם א' והא בהא תליא משום דנק' אוכ\"ם לגבי המשפיע שלו ע\"כ נק' חשך והעלם לגבי המקבל הימנו כנ\"ל וד\"ל. וזהו מגלה עמוקות מני חשך שזהו מ\"ש ישת חשך סתרו<sup data-n=\"10824\">107</sup> שהוא בחי' העלם אור העצמות ממש שנק' חושך וכמו ומשה נגש אל הערפל<sup data-n=\"10825\">108</sup> אשר שם דוקא אלקים כו', ולהיות שהוא ית' מקור כל העלם [ו]עומק לעומק אע\"פ שכ\"א נק' חשך כנ\"ל עכ\"ז מגלה מבחי' ההעלם כל העומקים העליונים, [כי] בהגלות נגלות אור עצמותו אז כל בחי' העלם נעשה גילוי גם העלם עליון יותר שנק' חשך סתרו ממש וממילא כל עילה שהוא בחי' ההעלם וחשך לגבי עלול נתגלה מן ההעלם ולא נק' העלם וחושך כלל, כי לפניו נגלו כל תעלומות<sup data-n=\"10826\">109</sup> העליונים (ודוגמא לזה הוא בימוהמ\"ש שיתגלה מן בחי' ההעלם דח\"ע כמ\"ש ישכיל עבדי<sup data-n=\"10827\">110</sup> כו' כידוע דכל רז לא אניס לי'<sup data-n=\"10828\">111</sup> שכל בחי' ההעלם העליון בהשגות רזין וסודות התורה שנפלאים וסתומים מאד שנק' נסתרות לה' ממש יבא הכל בגילוי ונק' חכם חרשים<sup data-n=\"10829\">112</sup> כו', וכך הוא בגילוי ההעלם דעולם התענוג שגם בהעלם העליון יותר",[["10817","100","<b>בחי'</b>: דח: כו'."],["10818","101","<b>דע\"ס הגנוז[ו']</b>: נסמן לעיל פ' שמות כח, ד."],["10819","102","<b>עומק עליון</b>: דח: האור העליון."],["10820","103","<b>דאפי' אור צח [כו'] אוכם</b>: נסמן לעיל יב, ב."],["10821","104","<b>שרגא בטיהרא</b>: חולין ס, ב."],["10822","105","<b>נער לא ימיש</b>: תשא לג, יא."],["10823","106","<b>איידי דטריד למבלע</b>: ראה גם לעיל קפח, ב. הנסמן לעיל פ' שמות מז, ג."],["10824","107","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["10825","108","<b>ומשה נגש אל הערפל</b>: יתרו כ, יח."],["10826","109","<b>כי לפניו נגלו כל תעלומות</b>: ע\"פ ברכת זכרונות."],["10827","110","<b>ישכיל עבדי</b>: נסמן לעיל מג, ד."],["10828","111","<b>דכל רז לא אניס לי'</b>: נסמן לעיל קנו, ד."],["10829","112","<b>חכם חרשים</b>: ראה גם לעיל פ' שמות כג, א הערה 952."]]],[2300540363,"כשעשוע[י] המלך בעצמו<sup data-n=\"10830\">113</sup> שנק' עדן גם הוא יבוא בגילוי [ב]עוה\"ב וד\"ל.\n<b>אך</b> לכאורה מטעם התגלות אור העצמיות ממש כמו בעוה\"ב וכה\"ג צ\"ל בהיפך, שגם אור העליון יותר יהי' בבחי' ביטול והעלם גדול עד שלא ניכר במציאות כלל כמו אור צח [כו'] דאוכם הוא לגבי עה\"ע עצמו כנ\"ל, וע\"כ נק' עה\"ע עצמו סדכ\"ס דוקא דהיינו שהוא סתום ונעלם ג\"כ מבחי' הסתומי' שנק' ראי'<sup data-n=\"10831\">114</sup> <span data-k=\"pg\">652</span> ּ בחי' גילוי לגבי' כנ\"ל במשל [ב]שכל הנעלם שבמקבל לגבי המשפיע כנ\"ל וד\"ל. והענין הוא דודאי יש הפרש בין בחי' [ה]עליות ובין בחי' הירידות, ד[ב]בחי' העליות בעילוי אחר עילוי כמו עליות הנשמות מגעה\"ת לגעה\"ע הרי בעלותם למעלה [מהם] מתבטלים [מ]מציאות[ם] שם, וכן מגעה\"ע למעלה באצי' עצמו, וכך הוא עד רום המעלות גם באורות הנעלמים וסתומים [כ]ע\"ס הגנוזות בעצמיות המאציל כמו שנק' שכל מופלא<sup data-n=\"10832\">115</sup> שכל מוצנע<sup data-n=\"10833\">116</sup> [ו]כמו שבלשון הגמ' נק' אור הגנוז מוימ\"ב ונגנז לצדיקים לע\"ל<sup data-n=\"10834\">117</sup>, וכן תענוג הנעלם שנק' עדן סתימא'<sup data-n=\"10835\">118</sup> עולה גם הוא למעלה מעלה שהוא בעצמות א\"ס שנק' מקור כל התענוגי' העליונים שזהו שנק' סדכ\"ס היות מופלא ונעלם גם מן הסתימין שנק' נסתרות [א]ו נפלאות וכה\"ג. אבל מגלה עמוקות מני חושך היינו שכל בחי' הנסתרות ונפלאות הנ\"ל יורדים מן ההעלם לגילוי, זהו כמו שהאור [מקיף] עליון נעשה בחי' או\"פ בגילוי אותיות [ה]מח' שבהעלם שבא בבחי' גילוי כמו בגילוי<sup data-n=\"10836\">119</sup> אותיות הדבור שזהו ירידת המדריגות מעליון לתחתון (כמ\"ש במ\"א בענין קי\"ס שהים שהוא בבחי' ההעלם המים נעשה הוא עצמו בבחי' גילוי כיבשה<sup data-n=\"10837\">120</sup> לבד (ולפי שנגלה מעצמות אוא\"ס שלמעלה מבחי' ההעלם וגילוי ע\"כ ההעלם נעשה גילוי וכנ\"ל). והוא לפי שאוא\"ס עצמו אינו עולה בבחי' העלם והכל א'<sup data-n=\"10838\">121</sup> בעצמו, ובעילוי אחר עילוי [עד] שנק' סדכ\"ס שזהו דוקא בבחי' העליות שכל שעולה יותר בעצמו יותר הוא מופלא ומכוסה בהבדלת הערך מכל ההשתל' הבא בהתפשטות למטה, וגם על עליות העולמות הסתומין שבעצמות יותר נעשה מובדל ומופלא וכל הקרוב קמי' ממש יותר כלא חשיב כו' (וכמו ביטול והתכללות העונג ורצון הפנימי' בעצם הנפש ממש הוא יותר מביטול והתכללות דחכ' ומדות ומחדו\"מ כו'). אבל בבחי' היריד[ות] נהפך הוא ממש שעצמות ממש יורד ומתגלה שאינו בהפלאה וסתר עליון, א\"כ כל בחי' העלם נעשה גילוי ואינו בביטול כלל אלא מאיר בבחי' גילוי אור למטה [ממנו] עד שגם",[["10830","113","<b>כשעשוע[י] המלך בעצמו</b>: נסמן לעיל פ' בא צב, ד."],["10831","114","<b>ראי'</b>: דח: ליתא."],["10832","115","<b>שכל מופלא</b>: נסמן לעיל פ' שמות לג, א."],["10833","116","<b>שכל מוצנע</b>: ראה גם לעיל קפח, ד. הקדמת הראב\"ד לס\"י ביאור נתיב הא' [ירושלים תשכ\"ב יא, א] שכל מופלא. . כאילו אמר שכל נעלם מכוסה ונסתר. וראה גם נתיב הז'."],["10834","117","<b>אור הגנוז. . לצדיקים לע\"ל</b>: ראה חגיגה יב, א."],["10835","118","<b>עדן סתימא'</b>: נסמן לעיל ה, ג."],["10836","119","<b>בגילוי</b>: ד: גילוי. ח: ליתא."],["10837","120","<b>שהים. . נעשה הוא עצמו. . כיבשה</b>: ראה גם לעיל קפו, א ואילך."],["10838","121","<b>והכל א'</b>: דח: והפלאה."]]],[2300540384,"בעשי' [י]איר בגילוי אור העצמו' כמו לפני האצי' רק שהוא בשוה ממש מטעם דמעלה ומטה שוין לפניו כנ\"ל.\n<b>וראי'</b> לזה ממה שכבר הי' לעולמים במ\"ת שנתגלה בחי' אנכי מי שאנכי<sup data-n=\"10839\">122</sup> שהוא סדכ\"ס כו' והי' בגילוי לכל כקטן כגדול בשוה ממש מטעם הנ\"ל, וכך יהי' בימוהמ\"ש שיתגלה כל בחי' העלם לגילוי ויהי' גילוי אור האלקי' בקטנים כמו בגדולים כמ\"ש ולא ילמדו [עוד]<sup data-n=\"10840\">123</sup> איש את רעהו כי<sup data-n=\"10841\">124</sup> כולם ידעו אותי מקטנם ועד גדולם<sup data-n=\"10842\">125</sup> כו' וכן א' ואשפוך את רוחי<sup data-n=\"10843\">126</sup> כו' כי הכל שוין מטעם הנ\"ל וד\"ל. וכך יהי' בעוה\"ב שהוא גילוי אור העצמי דא\"ס ב\"ה ממש למטה כמו למעלה בעצמותו לכל העולמות בשוה ממש, וז\"ש להנחיל אוהבי יש<sup data-n=\"10844\">127</sup>, יש ממש במורגש גילוי ההשגה ובמורגש יהי' גילוי [ה]עונג למטה כמו שהוא למעלה בסדכ\"ס עצמו כמ\"ש כימי כו' אראנו נפלאות<sup data-n=\"10845\">128</sup> למטה כמו למעלה ממש, לפי שביצי\"מ וקי\"ס הי' גילוי אור נפלאות העליונים למטה כמו למעלה, והכל מטעם הנ\"ל שהוא מצד גילוי [ו]ירידת האור [ב]עצמ[ו]' מן ההעלם היפוך ענין העלי' באו\"ח הנ\"ל. ושרש <span data-k=\"pg\">שכו</span> ּ הענין ידוע במ\"ש כי אל דיעות ה'<sup data-n=\"10846\">129</sup> ב' דיעות ד\"ע וד\"ת, שזהו ההפרש בין עליות וירידות הנ\"ל [ד]בחי' ד\"ת זהו כמו שהאור נמשך מאין ליש כמו החכ' מאין דכתר תמצא שלזה אור צח כו' אוכם הוא כו' וכה\"ג בכל עו\"ע עד רום המעלות שכל עילה כאשר עולה הוא בביטול היש לאין כנ\"ל. אבל בחי' ד\"ע זהו שנמשך מבחי' יש ליש דהיינו מיש האמיתי כמו שהוא נמשך למטה במקבל ג\"כ בבחי' יש ולא ע\"י צמצום שהוא מאין ליש כו', וזהו יהי' לע\"ל במשיח ודורו שנגלה כבוד הוי' למטה כו' וע\"כ ישפוך רוח אלקי' על כל הברואים<sup data-n=\"10847\">130</sup> ולא יהי' בבחי' ביטול היש כלל<sup data-n=\"10848\">131</sup> (ודוגמא לזה הי' במשה שידעו ה' פב\"פ<sup data-n=\"10849\">132</sup> ולא הי' בבחי' הביטול<sup data-n=\"10850\">133</sup> כלל כמו<sup data-n=\"10851\">134</sup> שכינה מדברת<sup data-n=\"10852\">135</sup> כו'), וכך יהי' במשיח ודורו דכתיב להנחיל אוהבי יש בחי' יש האמיתי כמ\"ש<sup data-n=\"10853\">136</sup> בעוה\"ב בתענוג הפשוט העצמי ממש וד\"ל.\n<b>וזהו</b> ואוצרותיהם אמלא דהנה כל בחי' עומקים הנ\"ל שהן העליות בהעלם אחר העלם עד בחי' העלם דעצמו' אוא\"ס<sup data-n=\"10854\">137</sup> שנק' סדכ\"ס כנ\"ל נק' בשם אוצרות העליונים עד\"מ האוצר[ות] של המלך הגנוזים וטמונים בהם כל הון יקר ונחמד וכל כלי חמדה סגולות מלכים מאבני יקר ופנינים כו' מזמן רב<sup data-n=\"10855\">138</sup> ולא יגלה לשום אדם אפי' לעצמו להתענג ולהשתעשע בהם כו' רק בעת חתונתו או חתונת בנו כנ\"ל. וכך יובן למעלה בבחי'",[["10839","122","<b>אנכי מי שאנכי</b>: נסמן לעיל פ' וארא סג, ד."],["10840","123","<b>ולא ילמדו [עוד]</b>: ירמי' לא, לג."],["10841","124","<b>כי</b>: דח: כו'."],["10842","125","<b>מקטנם ועד גדולם</b>: ד: מקטנם ועד. ח: מקטנם — נסמן לעיל פ' שמות לח, ג."],["10843","126","<b>ואשפוך את רוחי</b>: נסמן לעיל פ' שמות כב, ג."],["10844","127","<b>להנחיל אוהבי יש</b>: ראה גם לעיל קלח, ד. וש\"נ."],["10845","128","<b>כימי כו' אראנו נפלאות</b>: מיכה ז, טו."],["10846","129","<b>כי אל דיעות ה'</b>: נסמן לעיל פ' שמות כט, ב."],["10847","130","<b>הברואים</b>: דח: בשר."],["10848","131","<b>במשיח. . ולא יהי' בבחי' ביטול היש כלל</b>: ראה גם מאמרי אדה\"ז על מארז\"ל ע' תפב. לעיל פ' שמות כט, ב ובהערה 91."],["10849","132","<b>במשה שידעו ה' פב\"פ</b>: ברכה לד, י."],["10850","133","<b>במשה. . ולא הי' בבחי' הביטול</b>: ראה גם לעיל קצד, ד ואילך. לקמן רכה, א. רלה, א."],["10851","134","<b>כמו</b>: דח: כענין."],["10852","135","<b>שכינה מדברת</b>: נסמן לעיל קצד, ד."],["10853","136","<b>כמ\"ש</b>: דח: וכמ\"כ."],["10854","137","<b>אוא\"ס</b>: שם: א\"ס."],["10855","138","<b>רב</b>: שם: קדמון."]]],[2300540404,"אוצרות העליונים הגנוזים בהעלם אור העצמי' דאצי'<sup data-n=\"10856\">139</sup> שהוא בחי' [ה]עליות דאורות העליונים שנק' סתומים או נפלאות ונסתרות כו', וכמו מקור האור דח\"ע שבעצמות א\"ס שלתבונתו אין מספר<sup data-n=\"10857\">140</sup> ונק' חכים כו' יש בחי' אוצר החכ' ששם נגנז<sup data-n=\"10858\">141</sup> כל מקור ח\"ע בדוגמא<sup data-n=\"10859\">142</sup> שנתן ה' חכ' לשלמה שיחכם מכל האדם<sup data-n=\"10860\">143</sup> כו', דמתנה זו נמשך מבחי' אוצר הח\"ע שהוא בבחי' א\"ס ואין שיעור למעלה כנ\"ל רק שזהו בחי' חכ' שבדבור כמ\"ש וידבר<sup data-n=\"10861\">144</sup> שלמה<sup data-n=\"10862\">145</sup> כו' (וכן במ\"ת, בתו' הנגלית כו' בתוך גילוי הדבור<sup data-n=\"10863\">146</sup> כו'), וכמ\"כ גם בח\"ע הפנימי' במשיח דכתיב ישכיל עבדי כו' שיגל[ה] לו כל רזין וסודות התוה\"ק שנק' חכ' שלמעלה והוא שנק' הון יקר<sup data-n=\"10864\">147</sup>, וכמו אם יתן איש<sup data-n=\"10865\">148</sup> את כל הון ביתו שזהו מקור החו\"ב דתו\"מ כמ\"ש במשה בכל ביתי נאמן הוא<sup data-n=\"10866\">149</sup>, וגנוזים שם כל כלי יקר [מ]אוצר הנעלם בטנת\"א דתשב\"כ כמ\"ש<sup data-n=\"10867\">150</sup> בהם הנחמדים מזהב ומפז<sup data-n=\"10868\">151</sup> וכתיב יקרה היא מפנינים<sup data-n=\"10869\">152</sup>, וכמו אור הגנוז לצדיקי' כו' וכמו ושמתי כדכד<sup data-n=\"10870\">153</sup> כו' שזהו שה\"ם ישפ\"ה<sup data-n=\"10871\">154</sup> והוא כאבן ספיר<sup data-n=\"10872\">155</sup> שתחת רגליו כמעשה לבנת הספיר<sup data-n=\"10873\">156</sup>, שהוא ח\"ע וח\"ת ב' מיני אוצרות אוצר העליון ואוצר התחתון (שהן ב' ארצות [החיים]<sup data-n=\"10874\">157</sup> ארץ החיים העליון והתחתון<sup data-n=\"10875\">158</sup> ). והוא ג\"ע<sup data-n=\"10876\">159</sup> שלמעלה מן [ה]השגה דבינה שיהי' בהעברה שע\"י משיח שיפתח ה' אוצרו הטוב<sup data-n=\"10877\">160</sup> כו', והן אוצרות החכ', ונק' אוצר התחתון לגבי עוה\"ב שיהי' בהעברה הב' בנה\"פ<sup data-n=\"10878\">161</sup> שהוא נהר שיוצא מעדן [ה]עצמ[י] שהוא התענוג הפשוט שבעצמות א\"ס שנק' שעשועי המלך בעצמותו<sup data-n=\"10879\">162</sup> כו' והיינו ת' עלמין דכסופין<sup data-n=\"10880\">163</sup> כו' או ש\"י עולמות<sup data-n=\"10881\">164</sup>. והיינו אוצרותיהם ב' מיני אוצרות<sup data-n=\"10882\">165</sup> הנ\"ל אמלא אותן מעצמות אוא\"ס שמגלה כל העומקי' כו' <span data-k=\"pg\">654</span> ּ כאשר יתגלה למטה כמו שהוא למעלה [כו'], וזהו אהי' בימוהמ\"ש אנא זמין אשר אהי' בעוה\"ב<sup data-n=\"10883\">166</sup> כידוע. אך גם במ\"ת הי' גילוי ההעלם דאוצרות העליונים דסדכ\"ס אעפ\"י שהן באוצרות המלך שלא נתגלה לעולם (אף למשיח ומשה כעדן דעין לא ראתה<sup data-n=\"10884\">167</sup> וכן גנזי נסתרות שבח\"ע הק[דומה] כו') שע\"כ<sup data-n=\"10885\">168</sup> או'<sup data-n=\"10886\">169</sup> נותן התורה כו'), מ\"מ במ\"ת נתגלה לשעשע בהם, כמו ביום חתונתו או חתונת בנו [ב]הראות[ו] את יקר תפארת גדולתו<sup data-n=\"10887\">170</sup> כו'. כך במ\"ת הי' קצת",[["10856","139","<b>דאצי'</b>: שם: דא\"ס."],["10857","140","<b>שלתבונתו אין מספר</b>: תהלים קמז, ה."],["10858","141","<b>נגנז</b>: דח: גנוז."],["10859","142","<b>ח\"ע בדוגמא</b>: שם: החכמה העליונה כדוגמא."],["10860","143","<b>שנתן ה' חכ'. . האדם</b>: מל\"א ג, יב. ה, ט-יא."],["10861","144","<b>חכ' שבדבור כמ\"ש וידבר שלמה</b>: ראה גם מאמרי אדה\"א בראשית ע' קלה."],["10862","145","<b>וידבר שלמה</b>: מל\"א ה, יב [בהוספת תיבת שלמה — ראה תו\"ח וישב רו, ב. מאמרי אדה\"א בראשית ע' קלב. וש\"נ]."],["10863","146","<b>כו' בתוך גילוי הדיבור</b>: דח: בדבור."],["10864","147","<b>הון יקר</b>: משלי א, יג. כד, ד."],["10865","148","<b>אם יתן איש</b>: שה\"ש ח, ז. ראה גם לעיל קנה, ד. וש\"נ."],["10866","149","<b>בכל ביתי נאמן הוא</b>: בהעלותך יב, ז."],["10867","150","<b>כמ\"ש</b>: דח: כו' שנאמר."],["10868","151","<b>הנחמדים מזהב ומפז</b>: תהלים יט, יא."],["10869","152","<b>יקרה היא מפנינים</b>: משלי ג, טו."],["10870","153","<b>ושמתי כדכד</b>: ישעי' נד, יב. ב\"ב עה, א."],["10871","154","<b>ישפה</b>: ד: או ישפה. ח: וישפה."],["10872","155","<b>כאבן ספיר</b>: יחזקאל א, כו."],["10873","156","<b>שתחת רגליו כמעשה לבנת הספיר</b>: משפטים כד, י."],["10874","157","<b>ח\"ע וח\"ת. . ארצות [החיים]</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' יז."],["10875","158","<b>ארצות [החיים]. . העליון והתחתון</b>: תהלים קטז, ט. ראה גם לקמן פ' משפטים רצה, ב בשם הזהר. תו\"ח וישב קצח, א ובהערה 4."],["10876","159","<b>ג\"ע</b>: ד: ח\"ע. ח: בחי' ח\"ע."],["10877","160","<b>שיפתח ה' אוצרו הטוב</b>: נסמן לקמן הערה 637."],["10878","161","<b>בהעברה הב' בנה\"פ</b>: נסמן לעיל פ' שמות מ, ד."],["10879","162","<b>בעצמותו</b>: דח: ליתא."],["10880","163","<b>ת' עלמין דכסופין</b>: נסמן לעיל כה, ד."],["10881","164","<b>ש\"י עולמות</b>: עוקצי' ספ\"ג."],["10882","165","<b>אוצרות</b>: בתו\"ח כאן נכפל עוה\"פ: והיינו ב' מיני אוצרות."],["10883","166","<b>אהי' בימוהמ\"ש אנא זמין. . בעוה\"ב</b>: ראה גם לעיל א, ב. וש\"נ."],["10884","167","<b>כעדן דעין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["10885","168","<b>שע\"כ או' נותן התורה</b>: ראה לעיל לב, ד הערה 270."],["10886","169","<b>או'</b>: דח: ליתא."],["10887","170","<b>[ב]הראות[ו] את יקר תפארת גדולתו [דב</b>: ליתא]: ע\"פ אסתר א, ד."]]],[2300540424,"גילוי מאותן הע[ו]מקים שגנוזים בעצמות א\"ס כמו בקול השופר שהי' הולך וחזק<sup data-n=\"10888\">171</sup> וכתיב וכל העם רואים<sup data-n=\"10889\">172</sup> את הקולות ואת הלפידים כו'. ואעפ\"י שהי' גם זה מתוך בחי' ההעלם דענן וערפל ואש הגדולה [ו]כמ\"ש ויהי קולות וברקים<sup data-n=\"10890\">173</sup> וענן כבד על ההר אך משה לבדו נגש אל הערפל, אבל לע\"ל יתגלה מהו\"ע ית' שלא בבחי' ההעלם וחשך ולא בקולות [וברקי'] כלל ובלא ביטול כלל שהוא בחי' מיש ליש כמ\"ש להנחיל אוהבי יש עד\"מ<sup data-n=\"10891\">174</sup> שא' מתנה טובה יש לי בבית גנזי ושבת שמה<sup data-n=\"10892\">175</sup> וכה\"ג וד\"ל.\n<b>והנה</b> ארז\"ל אין להקב\"ה בעולמו אלא אוצר של י\"ש בלבד<sup data-n=\"10893\">176</sup>, וי\"ל למה נק' י\"ש בשם אוצר שהוא טמון וגנוז ואיך יתכן שיראת ה' יהי' גנוז ונאצר באוצר המלך דוקא שזה פלא לכאורה. אך הנה כתיב אם תבקשינה ככסף וכמטמונים תחפשינה<sup data-n=\"10894\">177</sup> אז תבין יראת ה'<sup data-n=\"10895\">178</sup>, וי\"ל מה[ו] ענין המשל למטמונים עם יראת ה', וגם מ\"ש אז תבין יראת ה' בינה זו מה היא דאיך שייך יראה<sup data-n=\"10896\">179</sup> לבינה רק לחכ' ולא יתכן כלל ענין בינה ביראת ה' שיאמר ע\"ז<sup data-n=\"10897\">180</sup> אז תבין יראת ה' כו' (וכן מ\"ש ודעת אלקים תמצא<sup data-n=\"10898\">181</sup> למה בשם אלקים כו'). אך הנה ארז\"ל אם אין יראה<sup data-n=\"10899\">182</sup> אין חכמה ואם אין חכ' אין יראה משמע [ד]שניהם א' ממש כמ\"ש ראשית חכ' יראת ה'<sup data-n=\"10900\">183</sup> הרי היראה קודמת לחכ' וכתיב הן יראת ה' היא חכ'<sup data-n=\"10901\">184</sup> שקדמה דאם אין חכ' כו'. והענין הוא כידוע שיש ב' מדרגות בחכמה ח\"ע וח\"ת, וכמ\"כ ב' מדריגות ביראה יר\"ע ויר\"ת, ובב' מדריגות א' אם אין [יראה] יר\"ע אין ח\"ע ואם אין ח\"ע אין יר\"ע [ד]הכל א', וכן ביר\"ת וח\"ת אם אין יר\"ת אין ח\"ת ואם אין ח\"ת אין יר\"ת כו' (ולא יקשה באיזה יקדים<sup data-n=\"10902\">185</sup> דאם אין יראה איך יגיע לחכ' כו' הענין דבאיזה שיקדים אם ביראה כבר קנה חכ' לפי שאם אין חכ' אין יראה וכן אם אין יראה<sup data-n=\"10903\">186</sup> כו' דהא בהא תליא והכל א').\n<b>והנה</b> תחלה י\"ל ההפרש בין יראה לאהבה, כידוע דאה' היא מקרוב<sup data-n=\"10904\">187</sup> להתקרב ולהתדבק בקירוב שהוא בחי' המשכה",[["10888","171","<b>בקול השופר שהי' הולך וחזק</b>: יתרו יט, טז. יט."],["10889","172","<b>וכל העם רואים</b>: יתרו כ, טו."],["10890","173","<b>ויהי קולות וברקים</b>: יתרו יט, טז."],["10891","174","<b>עד\"מ</b>: דח: האמיתי ע\"ד."],["10892","175","<b>מתנה טובה. . ושבת שמה</b>: שבת י, ב."],["10893","176","<b>אין להקב\"ה. . י\"ש בלבד</b>: ראה שבת לא, ב. ברכות לג, ב. שע\"ת פא, ד הערה 51."],["10894","177","<b>אם תבקשינה ככסף וכמטמונים תחפשינה</b>: משלי ב, ד."],["10895","178","<b>אז תבין יראת ה'</b>: משלי ב, ה."],["10896","179","<b>דאיך שייך יראה</b>: דח: דאין שייכות (ד: ניתוסף: כלל)."],["10897","180","<b>ע\"ז</b>: שם: ליתא."],["10898","181","<b>ודעת אלקים תמצא</b>: המשך הכתוב אז תבין."],["10899","182","<b>אם אין יראה</b>: אבות פ\"ג מי\"ז כגי' מחזור ויטרי."],["10900","183","<b>ראשית חכ' יראת ה'</b>: תהלים קיא, י."],["10901","184","<b>הן יראת ה' היא חכ'</b>: איוב כח, כח."],["10902","185","<b>ולא יקשה באיזה יקדים</b>: ראה גם מאמרי אדה\"א בראשית ע' כח. וש\"נ. שע\"ת מח, ד."],["10903","186","<b>אין יראה</b>: דח: בחכ'."],["10904","187","<b>דאה' היא מקרוב</b>: ראה גם לקמן פ' משפטים רפג, א: הכלל בכל מקום. תו\"א ויחי מה, ב. סע\"ד. מאמרי אדה\"א בראשית ע' תקב וע' תקיב ואילך. ע' תקלד. דברים ח\"א ע' קעז. וש\"נ."]]],[2300540444,"והתפשטו' דבחי' החסדים שנמשך כמים<sup data-n=\"10905\">188</sup> שטבע המים לדבק<sup data-n=\"10906\">189</sup>, וכל שיש קירוב יותר יותר יומשך אור האהבה ואה' גורמת הקירוב בגילוי יותר. ואמנם בחי' היראה הוא בבחי' ההעלם מרחוק<sup data-n=\"10907\">190</sup> דוקא, כאשר נפלא ונבדל הדבר מאד למעלה מכלי השגתו ולא יוכל לבא לגשת בקירוב כלל אדרבה [מרחוק] יעמוד[ו] באימה ופחד, והוא בבחי' הכיווץ בעצמו בתכלית היפך בחי' ההתפשטו' וההמשכה דאהבה שמתקרב ומתדבק כו' (כמו<sup data-n=\"10908\">191</sup> וירא העם וינועו ויעמדו מרחוק<sup data-n=\"10909\">192</sup> דוקא, וכל אימה ופחד יתירה אינה אלא מרחוק יותר שאז יגדל ויפלא בהפלאה והפלגה יתירה כשומע <span data-k=\"pg\">שכז</span> ּ מרחוק גדולת המלך ותקפו כמו שהוא סגור בהיכל מלך<sup data-n=\"10910\">193</sup> אז נורא מאד יותר מבקירוב כו', אבל בהגלות נגלות המלך ומקרב בימין אז הכל יכולים לדבר עמו בלא ביטול ויראה כלל. ואמנם יש הפרש בזה בין יראה פנימי' ובין יראה חיצוני'<sup data-n=\"10911\">194</sup> דביראה חיצוני' בביטול היש לאין מרחוק יותר יפול היראה ופחד, אבל ביראה הפנימי' שהוא פנימי' הביטול<sup data-n=\"10912\">195</sup> בעצם כביטול השר הרואה פני המלך או כתלמיד לפני רבו כו' כל שהוא מקרוב יותר מתבטל בעצם עד שאינו מרגיש א\"ע כלל, כמו וארכובותיו דא לדא נקשן<sup data-n=\"10913\">196</sup> כו' שהוא בעומק הלב בהעלם אחר העלם בפנימי' הלב והמוח עד שיוכל להתבטל [מ]מציאותו לגמרי, וכמו במשה שאמר ונחנו מ\"ה<sup data-n=\"10914\">197</sup> בעצם כו' לפי שהוא בבחי' ראי' מקרוב כמ\"ש פא\"פ אדבר בו<sup data-n=\"10915\">198</sup> כו' (ומש\"א דיראה לגבי משה מילתא זוטרתי היא<sup data-n=\"10916\">199</sup> כו' דמשמע אפי' יר\"ע לפי שידעו ה' פא\"פ כאשר ידבר איש<sup data-n=\"10917\">200</sup> כו' בלא ביטול כלל כמו במשיח דכתיב והריחו ביראת ה'<sup data-n=\"10918\">201</sup> כו' (וכמשי\"ת). וזהו ג\"כ ההפרש בין ח\"ע לח\"ת, שח\"ע הוא בבחי' יראה פנימית ביטול דמ\"ה בעצם שהוא כמו שהחכ' הוא בבחי' אין ונק' כח מ\"ה<sup data-n=\"10919\">202</sup> כו' (וכמו אור צח אוכם הוא לגבי עה\"ע כשהוא בקירוב דוקא כנ\"ל שזהו בראשית ירא בשת<sup data-n=\"10920\">203</sup> כידוע), אבל ח\"ת שנמשך החכ'<sup data-n=\"10921\">204</sup> מאין ליש בדיבור זהו כמו בחי' יר\"ת שהוא מרחוק דוקא כנ\"ל שאז מתבטל יותר מאין ליש (וכך הי' במ\"ת שנגלה בקול ודיבור [מ]תוך האש והענן כו' כנ\"ל לא היו יכולים לקבל ועמדו מרחוק כו' [ו]כמ\"ש אם יוספים אנחנו לשמוע קול אלקי' מתוך האש<sup data-n=\"10922\">205</sup> כו' דכל שמיעה מרחוק (ואע\"פ שהיו רואים את הנשמע<sup data-n=\"10923\">206</sup> כמ\"ש וכל העם רואים את הקולות כו') (משא\"כ בעוה\"ב שיראו עין",[["10905","188","<b>החסדים שנמשך כמים</b>: ראה זהר תרומה קסז, א. קעה, ב. שמיני מא, א. מאמרי אדה\"א דברים ח\"ד ע' א'שצב. וש\"נ."],["10906","189","<b>שטבע המים לדבק</b>: נסמן לעיל פ' וארא סח, א."],["10907","190","<b>היראה. . מרחוק</b>: ראה גם מאמרי אדה\"א בראשית ע' תקד. שמות ח\"ב ע' תרעו. לעיל הערה 187."],["10908","191","<b>(כמו</b>: דח: וכמו."],["10909","192","<b>וירא העם וינועו ויעמדו מרחוק</b>: יתרו כ, טו. ראה גם לעיל קסד, ג."],["10910","193","<b>המלך. . שהוא סגור בהיכל מלך</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתצא בשם הה\"מ. תו\"ח תולדות קמב, ג."],["10911","194","<b>הפרש. . יראה פנימי'. . חיצוני'</b>: ראה גם לעיל פ' בא קב, ד."],["10912","195","<b>פנימי' הביטול</b>: דח: ביטול הפנימי."],["10913","196","<b>וארכובותיו דא לדא נקשן </b>[ד: ליתא]: ע\"פ דניאל ה, ו."],["10914","197","<b>ונחנו מ\"ה</b>: נסמן לעיל פ' שמות מג, א."],["10915","198","<b>פא\"פ אדבר בו</b>: בהעלותך יב, ח."],["10916","199","<b>דיראה לגבי משה מילתא זוטרתי היא</b>: ראה גם לעיל קנז, א. וש\"נ."],["10917","200","<b>כאשר ידבר איש</b>: תשא לג, יא."],["10918","201","<b>והריחו ביראת ה'</b>: ישעי' יא, יג."],["10919","202","<b>שהחכ'. . כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["10920","203","<b>בראשית ירא בשת</b>: בראשית א, א. ת\"ז ת\"ז ותכ\"ח. ראה מאמרי אדה\"א בראשית ע' א וס\"ע לה ואילך. דברים ח\"ד ע' א'תט."],["10921","204","<b>החכ'</b>: ד: בחכ'. ח: בבחי' חכ'."],["10922","205","<b>אם יוספים. . קול אלקי' </b>[ח ניתוסף: מדבר]<b> מתוך האש</b>: חיבור שני כתובים: ואתחנן ה, כב. ד, לג."],["10923","206","<b>רואים את הנשמע</b>: נסמן לעיל קפ, ב."]]],[2300540464,"בעין במהו\"ע ית' (וכמ\"ש הנה אלקינו זה<sup data-n=\"10924\">207</sup> וכן בקי\"ס שאמרו זה אלי<sup data-n=\"10925\">208</sup> כו') ולא יהי' בבחי' ביטול כלל כנ\"ל כמ\"ש להנחיל אוהבי יש כמו במשה ומשיח כו' וד\"ל). וזהו אם אין ח\"ע אין יר\"ע ביטול הפנימי' דאין ומ\"ה בעצם דהכל א' ממש [ו]אם אין יר\"ע אין ח\"ע וכמ\"ש ראשית חכמה יראה<sup data-n=\"10926\">209</sup>, וכן ביר\"ת וחכ\"ת שהוא מרחוק משמיעה כמו שמעתי שמעך יראתי<sup data-n=\"10927\">210</sup> כו' אם אין יר\"ת אין ח\"ת כמ\"ש ויאמר לאדם<sup data-n=\"10928\">211</sup> בקבלת התו\"מ בפו\"מ הן יראת ה' היא חכ', משום דנעוץ תחב\"ס<sup data-n=\"10929\">212</sup> [ד]דחילו עילאה וח\"ע נעוץ בדחילו תתאה וח\"ת<sup data-n=\"10930\">213</sup> [ו]כמ\"ש ועתה ישראל מה ה'<sup data-n=\"10931\">214</sup> כו' כ\"א ליראה כו' וראי' מ[ן] עוה\"ב שהוא התגלות אור העצמות ממש שאינו רק ע\"י קבלת עומ\"ש במצות בפו\"מ ביר\"ת לבד וד\"ל.\n<b>ושרש</b> הענין הוא שיש הפרש בזה בין בחי' העליות דאו\"ח בבחי' הגבו' דאוא\"ס כמו שהיא עולה למעלה בעומק אחר עומק שהוא בהעלם אחר העלם כמו עומק החכ' לעומק הכתר, כמו שכל עלול עולה ונתבטל<sup data-n=\"10932\">215</sup> ונכלל בעילתו כו' בבחי' ביטול והתכללו' מיש לאין כנ\"ל בענין העומקים כו' שמזה נמשך בחי' היראה ופחד שהוא מחמת הרוממו' וההתנשאות דאלקי' בעילוי אחר עילוי כו' וכל הקרוב קמי' יותר כלא כו', לפי שאוא\"ס מופלא ונעלם בהעלם אחר העלם<sup data-n=\"10933\">216</sup> עד אין שיעור למעלה שנק' סדכ\"ס, עד ששם אמר שמים לא זכו בעיניו<sup data-n=\"10934\">217</sup> כו' וכמו וסביביו נשערה מאד<sup data-n=\"10935\">218</sup> כו' שזהו בחי' יראה פנימי' למעלה <span data-k=\"pg\">656</span> ּ בקירוב יותר ויראה חיצוני' מרחוק שהוא מופלא ביותר למטה כו'. והן ב' מיני חכ' ח\"ע וח\"ת פנימי' חכ' כמו שיהי' במשיח דכתיב ישכיל עבדי כו' יהי' בו בחי' יראה פנימית שהוא מקרוב יותר בבחי' ראי' מקרוב כו', וזהו יראה פנימי' שבאה מן ההעלם ביותר לגילוי כמו משל המטמון שצריך חיפוש גדול בעומק הארץ ביותר שכל החופר בעומק הארץ יותר ימצא המטמון שנטמן שם, כך צ\"ל בחיפוש גדול בעומק תעלומות הלב<sup data-n=\"10936\">219</sup> להיות בלב [נשבר] בעמקות הרצון שבלב ביותר עד שיבוא כל בחי' ההעלם שאחר ההעלם לגילוי אור. וזהו שאמר ממעמקים קראתיך כו' מעומקא [דעומקא] דליבא<sup data-n=\"10937\">220</sup> שנק' תעלומות נקודת הלב בבחי' לב נשבר ונדכה<sup data-n=\"10938\">221</sup> מצד יראת הרוממות כמו שהוא ית' בבחי' הרוממות והעילוי מעומק לעומק שמשם יבוא לגילוי",[["10924","207","<b>הנה אלקינו זה</b>: ישעי' כה, ט."],["10925","208","<b>זה אלי</b>: בשלח טו, ב."],["10926","209","<b>יראה</b>: דח: כו'."],["10927","210","<b>שמעתי שמעך יראתי</b>: חבקוק ג, ב."],["10928","211","<b>ויאמר לאדם</b>: התחלת הכתוב הן יראת ה' היא חכ' נסמן לעיל 184."],["10929","212","<b>דנעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["10930","213","<b>[ד]דחילו עילאה וח\"ע נעוץ בדחילו תתאה וח\"ת</b>: ראה גם לעיל קלח, א."],["10931","214","<b>ועתה ישראל מה ה'</b>: עקב י, יב."],["10932","215","<b>שכל עלול עולה ונתבטל</b>: דח: כל עלול שעולה."],["10933","216","<b>אחר העלם</b>: דח: ליתא."],["10934","217","<b>שמים לא זכו בעיניו</b>: נסמן לעיל קסז, ג."],["10935","218","<b>וסביביו נשערה מאד</b>: תהלים נ, ג."],["10936","219","<b>תעלומות הלב</b>: נסמן לעיל פ' בא קו, ב."],["10937","220","<b>מעומקא [דעומקא] דליבא</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תשעא־ נ\"ך ע' תפו ובהנסמן בהנ\"ל."],["10938","221","<b>לב נשבר ונדכה</b>: תהלים נא, יט."]]],[2300540483,"אור. וז\"ש ממעמקים כו'<sup data-n=\"10939\">222</sup> כמ\"ש מגלה עמוקות מני חשך שבאתעדל\"ת אתדל\"ע<sup data-n=\"10940\">223</sup>, וזה שיהי' במשיח דכתיב והריחו ביראת ה' ביראה פנימי' וביטול אמיתי בפנימי' חכ' שזהו דמורח ודאין<sup data-n=\"10941\">224</sup> בריח שבחוטם שלמעלה מן החכ', והוא בחי' העלם המקיף דתענוג כו' והוא בחי' גילוי דמל' דא\"ס שיאיר במשיח מבחי' ההעלם דסדכ\"ס. וזהו אם כמטמונים תחפשינה כו' כמו נחפשה דרכינו ונשובה<sup data-n=\"10942\">225</sup> כמו המפשפש בעיון דק מאד לברר גם הדק שבדקות שנשאר בהעלם גדול כמו השם אורחותיו<sup data-n=\"10943\">226</sup> בעוה\"ז<sup data-n=\"10944\">227</sup> זוכה ורואה בישועתו כו' כמ\"ש ושם דרך אראנו בישע אלקים<sup data-n=\"10945\">228</sup> ששימה זו בבחי' הדין והגבו' עד אין שיעור למעלה, וזהו בכל ר\"ה ויוהכ\"פ ששם אורחותיו מאד נעלה<sup data-n=\"10946\">229</sup> כי בר\"ה הוא זמן העלי' דאוא\"ס בעצמות ברום המעלות ששם שמים לא זכו כמ\"ש ושמך נורא<sup data-n=\"10947\">230</sup> על כל מה שבראת<sup data-n=\"10948\">231</sup> וכמו למען תורא<sup data-n=\"10949\">232</sup> כמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> אם כמטמונים מן ההעלם ביותר ע\"י לב נשבר בעומק יותר (וכמו במ\"ש<sup data-n=\"10950\">233</sup> הטבעי' שמואס בחייו ממש) אז תבין יראת ה' כו'<sup data-n=\"10951\">234</sup>, פי' יראת ה' היא יר\"ע שהיא בפנימי' ח\"ע שהוא בהעלם דאי\"ן ומ\"ה כנ\"ל (כמ\"ש כבוד אלקי' הסתר דבר<sup data-n=\"10952\">235</sup> ) כמ\"ש הן יראת ה' היא חכ' וצריך להביא לגילוי מן ההעלם שבתוך העלם, והוא מ\"ש אז תבין בבינה שהוא התגלות העלם ואין דחכ' וז\"ש וסו\"מ בינה<sup data-n=\"10953\">236</sup> כו' והיינו כאשר כמטמונים תחפשינה מן ההעלם דעומק הלב כו' וד\"ל (ודעת אלקי' שבגילוי מאין ליש כמו והחכ' מאין תמצא<sup data-n=\"10954\">237</sup> אלקים הבין דרכה<sup data-n=\"10955\">238</sup> שזהו בחי' דע\"ת שהוא מאין ליש מהעלם לגילוי והוא דעת אלקים המצומצם ומוסתר כמ\"ש כבוד אלקים הסתר דבר כו' וד\"ל). אך הנה כ\"ז הוא בבחי' העליות דאו\"ח הנ\"ל, אבל בבחי' הירידות דאו\"י הנ\"ל<sup data-n=\"10956\">239</sup> [ש]מגלה עמוקות מני חשך כנ\"ל שכל העלם בא לגילוי, והוא לפי שנגלה מעצמות אוא\"ס ב\"ה מקור כל העמקים למטה כמו למעלה בלי הסתר והפלא כלל, כמו גילוי עצמות א\"ס ב\"ה בתו\"מ למטה בדברים גשמיים כמו שהתו\"מ הן למעלה בעצמות ממש [ו]בגילוי שכינה בהיכל ק\"ק ובנביאים ולע\"ל במשיח וכה\"ג, אזי הוא בבחי' הקירוב דאהבה ולא ביראה מרחוק הנ\"ל, וכל מה שהי' נק' בשם מטמון ואוצר גנוז מתגלה לע\"ל בעוה\"ב ולימהמ\"ש כמ\"ש להנחיל אוהבי יש [יש] האמיתי כמו שהוא ממש למעלה ולמטה [ב]שוה ממש. ואוצרותיהם אמלא",[["10939","222","<b>כו'</b>: דח: ממעמקי' (ה)עליונים."],["10940","223","<b>שבאתעדל\"ת אתעדל\"ע</b>: נסמן לעיל פ' שמות מא, א."],["10941","224","<b>במשיח. . דמורח ודאין</b>: ראה גם לעיל קנח, ג. וש\"נ."],["10942","225","<b>נחפשה דרכינו ונשובה</b>: איכה ג, מ [בדילוג]."],["10943","226","<b>השם אורחותיו בעוה\"ז</b>: מוע\"ק ה, א. סוטה ה, ב."],["10944","227","<b>בעוה\"ז</b>: דח: ליתא. וכן ליתא במוע\"ק שם. מאמרי אדה\"א שמות ח\"ב ר\"ע תרכט. אוה\"ת תהלים נ, כג (ע' קצג)־ ויחי ע' 740 (ומציין למוע\"ק)."],["10945","228","<b>ושם דרך אראנו בישע אלקים</b>: תהלים נ, כג."],["10946","229","<b>נעלה</b>: דח: ליתא."],["10947","230","<b>ושמך נורא</b>: תפלת העמידה לימים נוראים."],["10948","231","<b>על כל מה שבראת</b>: דח: ליתא."],["10949","232","<b>למען תורא</b>: תהלים קל, ד. ראה גם עט\"ר נה, א ואילך. ע, א. מאמרי אדה\"א בראשית ע' מב. נ\"ך ע' תקמט ובהנסמן בהנ\"ל."],["10950","233","<b>במ\"ש</b>: במרה שחורה — ראה זהר (רע\"מ) פינחס רכז, ב. לקמן פ' ויקהל תח, א. תט, ג. תי, א. תו\"ח וישב רט, ג ובהערה 40."],["10951","234","<b>כו'</b>: דח: ליתא."],["10952","235","<b>כבוד אלקי' הסתר דבר</b>: משלי כה, ב."],["10953","236","<b>וסו\"מ [ וסור מרע] בינה</b>: המשך הכתוב הן יראת ה'."],["10954","237","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["10955","238","<b>אלקים הבין דרכה</b>: איוב שם, כג."],["10956","239","<b>הנ\"ל</b>: חט: ליתא."]]],[2300540501,"היינו כל אוצרות החיים העליונים הגנוזים בהעלם [ה]עצמות שנק' סדכ\"ס אמלא אות[ם] שיבאו בגילוי להתענג ולהשתעשע בהם בנשמות <span data-k=\"pg\">שכח</span> ּ של הצדיקים כמו ת' עלמין דכסופין דנהרין לע\"ל (והיינו ב' אוצרות אוצר העליון דח\"ע ואוצר עולם התענוג הפשוט דעוה\"ב בשעשועי המלך בעצמו שלמעלה מבחי' השעשועים שבתוה\"ק שיתגלה במשיח, והוא ראי' המהות שיהי' בעוה\"ב דוקא שזהו מי\"ש לי\"ש בלא ביטול כנ\"ל במשה<sup data-n=\"10957\">240</sup>. אך זהו דוקא בא מצד יר\"ת בעומ\"ש בחיצוניות דוקא כמו הקים עול<sup data-n=\"10958\">241</sup> כו' כי נתב\"ס דוקא וע\"כ יהי' היראה לע\"ל בקירוב דוקא יותר מבריחוק בבחי' או\"ח, וכמו המלך שמתגלה בכבודו ובעצמו שנ[ו]פל פחדו ואימתו למעלה מכפי השגה<sup data-n=\"10959\">242</sup> שהי' לו תחלה. וכמו בר\"ה דגם שאז עליות העולמות נמשך מפחד אלקי' על כל גוים<sup data-n=\"10960\">243</sup> מעל<sup data-n=\"10961\">244</sup> הרשעים שישובו בתשובה שלימה מפני שישבר [לבבם ו]גאונם, כמו לע\"ל שיהי' פחד ה' על כל הברואים<sup data-n=\"10962\">245</sup> כו' לפי שיתאחד אז יראה פנימי' עם יראה חיצוניות לפי שמבחי' ההעלם יבוא לגילוי כו' וד\"ל). וזהו שאין להקב\"ה בעולמו אלא אוצר של י\"ש בלבד<sup data-n=\"10963\">246</sup> כו' די\"ש הוא בחי' יראת הרוממות [ב]עוצם גדולת ורוממות א\"ס ב\"ה למעלה מעלה עד אין שיעור שצריך שיחופש הדבר בעומק הלב והמוח כמו חיפוש האוצר שיבוא מן ההעלם לגילוי, ולפי שאין לו<sup data-n=\"10964\">247</sup> שיעור לעליות המדריגות הנק' עומקים ע\"כ גם יראה פנימי' ויראה חיצוני' שנולד מזה הוא ג\"כ נק' אוצר הגנוז בריבוי גדול מאד ונגלה ליראי ה' מן ההעלם וסוד ה', כמ\"ש סוד ה' ליריאיו<sup data-n=\"10965\">248</sup> שהוא אוצר הח\"ע שתלוי באוצר היראה כמ\"ש יראת ה' היא אוצרו<sup data-n=\"10966\">249</sup> כו' משום דהכל א' ממש כנ\"ל. וכן באוצר הע[ליון] דבחי' התענוג הפשוט ג\"כ נגלה רק ליראי ה' כמ\"ש מה רב טובך<sup data-n=\"10967\">250</sup> אשר צפנת ליריאך דוקא, והוא העוה\"ב שאינו רק עבור המצות שהיא ביראת אלקים כמ\"ש סוף דבר<sup data-n=\"10968\">251</sup> את אלקי' ירא<sup data-n=\"10969\">252</sup> כו' וכן ועתה ישראל מה ה' כו' כנ\"ל וד\"ל.\n<b>ומעתה</b> י\"ל מ\"ש דאין לו בעולמו רק אוצר של י\"ש דוקא, דלכאו' הרי א[מר] בהיפך דהכל בידי שמים חוץ מי\"ש<sup data-n=\"10970\">253</sup>, וא\"כ אוצר זה של י\"ש אינו בי\"ש רק בידי אדם דוקא שהוא תלוי בבחירה שלו כו'. אך הענין הוא יובן<sup data-n=\"10971\">254</sup> עד\"מ הנ\"ל בענין הנצח ששרשו מגיע בפנימיות ועצמות הנפש עד שיוכל לבזבז כל הון רכושו כמלך שמבזבז כל אוצרותיו בשביל הניצוח",[["10957","240","<b>כנ\"ל במשה</b>: ח: כלל כמשה ומשיח."],["10958","241","<b>הקים עול</b>: ראה גם לעיל פ' שמות ט, א. וש\"נ."],["10959","242","<b>מכפי השגה</b>: ח: מכלי השגתו. דט: מכפי ההשגה."],["10960","243","<b>מפחד. . גוים</b>: ט: פחד אלקים."],["10961","244","<b>מעל</b>: ח: גם על. ט: גם על כל."],["10962","245","<b>לע\"ל שיהי' פחד ה' על כל הברואים</b>: נסמן לעיל קפה, ב."],["10963","246","<b>בלבד</b>: חט: ליתא."],["10964","247","<b>לו</b>: שם: ליתא."],["10965","248","<b>סוד ה' ליריאיו</b>: תהלים כה, יד."],["10966","249","<b>יראת ה' היא אוצרו</b>: ישעי' לג, ו."],["10967","250","<b>מה רב טובך</b>: תהלים לא, כ. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תיג ואילך."],["10968","251","<b>סוף דבר</b>: קהלת יב, יג."],["10969","252","<b>את אלקי' ירא</b>: חט: ליתא."],["10970","253","<b>דהכל בידי שמים חוץ מי\"ש</b>: ברכות לג, ב."],["10971","254","<b>הוא יובן</b>: ד: הוא. ח: יובן."]]],[2300540519,"כו'. וכך יובן למעלה ולמטה בנפש האדם דהנה כל עיקר הכוונה דבריאת האדם בעוה\"ז הוא רק כדי שיברר לק\"נ שזהו לברר לגוף החומרי שמעורב טו\"ר מנוגה דעשי' כדי לאכפיא לס\"א כו' כמאמר הזהר כד אתכפיא סט\"א<sup data-n=\"10972\">255</sup> אסתלק יקרא דקוב\"ה בכולהו עלמין כו', ואע\"פ שכל עיקר ומקור היניקה דק\"נ שנק' סט\"א אינו רק מחיצוני' ואחוריים דפסולת הנמשך מכלים החיצונים דמל' דקדושה (ממ\"ח צירופי' האחרונים<sup data-n=\"10973\">256</sup> דשם אלקי' כידוע בענין ארץ חם<sup data-n=\"10974\">257</sup> ), אך בחי' הניצוח [ה]אלקי יש בזה לאכפייא לסט\"א שמזה יהי' יתרון האור הרבה מכל אורות התענוגי' העליונים הגנוזים למעלה מעלה עד שבשביל הניצוח הזה יגלה כל עמוקות ונסתרות שנק' אוצרות [ה]עליונים, כמו שמבזבז המלך אוצרות[יו] בשביל ניצוח המלחמה עם שר ומלך קטן הערך מאד שנק' (מלך זקן וכסיל<sup data-n=\"10975\">258</sup> כו'). וענין הבזבוז הזה היינו שמגלה מבחי' [ה]העלם כל בחי' [ה]אוצרות [ה]עליונים כמו מגלה עמוקות מני חשך [שזהו] כמלך שמוציא כל כחו וגבורתו ברוב עשרו וגדולתו אשר <span data-k=\"pg\">658</span> ּ בגנזי היכלו שאצרו אבותיו כדי להביא מכח אה\"פ<sup data-n=\"10976\">259</sup> הניצוח שלו בדבר קטן מאד כנ\"ל וד\"ל.\n<b>ויובן</b> בזה בא[תע]דל\"ת מתחלה בנפש האדם שהוא הנשמה [ה]אלקי' שנק' אדם<sup data-n=\"10977\">260</sup> אדמה לעליון<sup data-n=\"10978\">261</sup> לפי ששרשם מבחי' אדם העליון דאצי' כידוע בע\"ח דהנשמה עצמה א\"צ תיקון<sup data-n=\"10979\">262</sup> ובירור כי שרשה בבחי' עולם התיקון דאדם<sup data-n=\"10980\">263</sup> הע'<sup data-n=\"10981\">264</sup> שהוא שם מ\"ה וכמ\"ש כי נר ה' נשמת אדם<sup data-n=\"10982\">265</sup> כו', וא\"כ לא הי' ירידת הנשמה למטה בגוף החומרי בעוה\"ז בשביל עצמה רק בשביל תיקון ובירור [ד]נה\"ט [ש]בגוף החומרי דוקא (רק שעי\"ז יגיע גם לנשמה האלקי' יתרון מעלה ומדריגה גבוה משרשה הראשון בשם מ\"ה גם שמברר לב\"ן דנה\"ב, לפי ששרש הנה\"ב בחי' ב\"ן דנוגה בבחי' ס\"ג דתהו שלמעלה מבחי' שם מ\"ה<sup data-n=\"10983\">266</sup> דתיקון כידוע ומבואר במ\"א בענין אדם כי יקריב<sup data-n=\"10984\">267</sup> קרבן<sup data-n=\"10985\">268</sup> מן הבהמה כו'). והנה ידוע דכל נשמה ונשמה היתה דבוקה למעלה מעלה בשרשה באלקי' חיים בדביקות אמיתי' ותמידי' בלי פירוד כלל וכלל והיינו שלא הי' לה רק רצון א' לה' לבדו ואין זר אתו (וגם עכשיו שהנשמה מלובש[ת] בגוף החומרי דיוקנאה חקוק למעלה הנק' מזלא והיינו מ\"ם ולמ\"ד דצלם<sup data-n=\"10986\">270</sup> כמ\"ש שימני כחותם<sup data-n=\"10987\">269</sup> כו' וע\"כ או' חבוקה ודבוקה בך<sup data-n=\"10988\">271</sup> וכתיב כולך יפה רעייתי<sup data-n=\"10989\">272</sup> כו'). אך בהתלבשות וירידת הנשמה בגוף מצד חומר הגוף הגס ש[ל ה]נה\"ט הוא שיש לנה\"ט רצונות זרות החומריים",[["10972","255","<b>כד אתכפיא סט\"א</b>: ראה זהר תרומה קכח, ב. יתרו סז, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' ה."],["10973","256","<b>ממ\"ח צירופי' האחרונים</b>: נסמן לעיל פ' שמות ל, ב."],["10974","257","<b>כידוע בענין ארץ חם</b>: ט: כמ\"ש בענין אדמת בני חם — נסמן לעיל פ' שמות כ, ב."],["10975","258","<b>מלך זקן וכסיל</b>: קהלת ד, יג."],["10976","259","<b>אה\"פ</b>: חט: אל הפועל."],["10977","260","<b>הנשמה. . אדם</b>: ראה זהר יתרו עו, רע\"א."],["10978","261","<b>אדם אדמה לעליון</b>: נסמן לעיל פ' שמות מו, ב."],["10979","262","<b>בע\"ח דהנשמה עצמה א\"צ תיקון</b>: בתניא פל\"ז (מח, ב) מציין לשער כ\"ו [שער הצלם פ\"א]. ראה ש\"א ט, א ובהערה 4. לקמן פ' תרומה שו, א."],["10980","263","<b>דאדם. . שם מ\"ה</b>: נסמן לעיל ד, ב."],["10981","264","<b>הע'</b>: ח: העליון. ט: אדמה לעליון."],["10982","265","<b>כי נר ה' נשמת אדם</b>: משלי כ, כז [בהוספת תיבת: ”כי\" — ראה לקמן פ' תצוה שיח, ד. מאמרי אדה\"ז תקע\"א ע' כג וע' כח. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'קסו. ש\"א לד, ב ובהערה 3]."],["10983","266","<b>ס\"ג דתהו שלמעלה. . מ\"ה</b>: נסמן לעיל פ' שמות מ, ד."],["10984","267","<b>אדם כי יקריב</b>: ויקרא א, ב. ראה גם מאמרי אדה\"א שמות ח\"א ע' צה. וש\"נ."],["10985","268","<b>קרבן</b>: דחט: ליתא."],["10986","270","<b>מ\"ם ולמ\"ד דצל\"ם</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תצח ואילך (ובהנסמן בריש המאמר שם)."],["10987","269","<b>דיוקנאה חקוק. . שימני כחותם</b>: נסמן לעיל קפ, ג."],["10988","271","<b>חבוקה ודבוקה בך</b>: הושענא אום אני חומה [ליום ג]."],["10989","272","<b>כולך יפה רעייתי</b>: שה\"ש ד, ז."]]],[2300540537,"שלא לה' המה המבלבלי' לנשמה האלקי' ומונעי' ומעכבים מכל עבודה האלקי' בתכלית, היינו מיד שנתעורר הנשמה באוי\"ר אלקי' יומשך לב החומרי אחר מ\"ז, והוא מחלק הרע שבנה\"ט שנק' יצה\"ר שכל חפצו ומגמתו להחטיא לאדם ולהפילו בשאול תחתית בכל עומק רע כו' כידוע. ולזאת צריך האדם לבוא במלחמה גדולה להתגבר על היצה\"ר ואין התגברות גדולה יותר מע\"י מדת הניצוח דוקא, והוא לנצח את הרצון הזר העולה מצד הרע הגמור דיצה\"ר ולבטלו לגמרי והוא רק בבחי' תוקף ועוז הרצון בניצוח זה (בל\"א שטארקייט). וכן בוע\"ט להיות [ב]תוקף וחיזוק בנפשו בעבודת ה' בתו\"מ ובתפלה וכה\"ג לבל יפול וישונה משום דבר המבלבל כו' (והוא הנק' הסכם חזק ביותר עד שישאר ברצונו והסכם שלו לעולם מבלי שינוי ונטי' אפי' [כ]קש\"י<sup data-n=\"10990\">*273</sup>, ודוקא מצד שעומד היצה\"ר לנגד יבוא בלבו התגברות הניצוח זה ביותר (וכמו שרואה אדם בנפשו שכאשר יצרו מתגבר עליו ביותר להחטיאו באיזה דבר רע, או שיפול עליו הבלי תענוגי עוה\"ז להתגשם ביותר [או] טרדת עול הפרנסה ביותר לבלבלו ולנתקו מחבל עוז התקשרותו באלקים לגמרי, אז דוקא יתעורר בלבו הנצחון גדול מאד בהסכם חזק ותקיף ביותר שיהי' סו\"מ בתכלית ולא יזיז מעבודתו התמה משום דבר המנגד, כי זהו עיקר מדת הנצחון שיתחזק רק כנגד המנגד דוקא כו').\n<b>והוא</b> משארז\"ל לעולם ירגיז אדם<sup data-n=\"10991\">273</sup> יצ\"ט על יצה\"ר פי' ירגיז יצ\"ט ברוגז וכעס גדול על [ה]יצה\"ר, והענין הוא שזהו עיקר מדת הנצחון להפיל שכנגדו בדברי רוגז וכעס ובדברי חירופים ובזיונות גדולים עד שצריך ליפול לבבו מקושי' וחוצפה ועזות שלו, כי כל חוצפה ועזות קשה אין לו <span data-k=\"pg\">שכט</span> ּ נפילה רק מדברי רוגז וחירופים בחרון אף גדול עד שיפול מעזותו מחמת זה וכמו יגער ה' בך השטן<sup data-n=\"10992\">274</sup> וכה\"ג, כי אין הרע בשרשו רק בחי' עזות וחוצפה בעלמא, כי לעזות פנים אין תיקון ועצה רק להפילו בדברי רוגז ובזיונות וחירופי' גדולים והרחקה יתירה בשמאל דוחה, והוא לבזותו ולהשפילו בתכלית עד ש[י]כנע לבו הגס, וכמו האב המוכיח לבנו כאשר לבו גס ביותר שו[ב]ב בדרך רע לא יכנ[י]ע אותו רק [בדברי] רוגז וכעס ושפלות כמו שהי' משה מוכיח לישראל בדברי רוגז ושפלות נשפל ונשבר לבבם וא' חטאנו<sup data-n=\"10993\">275</sup> כו'. וכך צריך אדם לרגוז בלבו מאד על בחי' הרע שבנפשו שנמשך אחר כל תאוות רעות בפר\"ע והוללות שהן רק",[["10990","*273","<b>[כ]קש\"י</b>: אוצ\"ל: [כ]קש\"י)."],["10991","273","<b>לעולם ירגיז אדם</b>: ברכות ה, א. ראה גם תניא פכ\"ט. לקו\"ת שלח מא, א. דרך חיים קא, ב ואילך. לקמן פ' משפטים רפ, סע\"ב ואילך. רפד, א. רפט, ד."],["10992","274","<b>יגער ה' בך השטן</b>: זכרי' ג, ב."],["10993","275","<b>וא' חטאנו</b>: שלח יד, מ. דברים א, מא."]]],[2300540555,"בחוצפא ועזות לבד דחוצפא אפי' כלפי שמיא<sup data-n=\"10994\">276</sup> כו', והוא ע\"י [ה]שפלות ובזיונות שמשפיל לרע מגיאותו אחר שגיאותו בחנם כי אחריתו רימה ותולעה ויתמרמר בנפשו ברוגז וכעס גדול ע\"ע על עצם הגיאות ועזות לבו למרוד בקונו כו' (ולא יחפה ע\"ע להקל בדבר מצד אהבת עצמו עד שאין רואה חוב לעצמו<sup data-n=\"10995\">277</sup> או מצד הקלות שאינו חושש על נפשו אם למות ואבדון תלך כו' או מצד מיעוט הדעת ועיקר הכלל הוא מיעוט היראה וכמשי\"ת), וברוגז וכעס זה יגבר על [ה]יצה\"ר בניצוח גדול לעמוד עליו [ו]להפילו מגיאותו בתכלית עד שנשבר הגסות לגמרי ומכניעו לימשך גם הוא אחר הטוב ויהי' סו\"מ שלא להתגאל בחומרית עוה\"ז רק מה שמן ההכרח, ויהי' ביטול הרצון רק לה' לבדו וכמ\"ש בכל לבבך בב' יצריך<sup data-n=\"10996\">278</sup> דוקא שגם היצה\"ר יהי' לו התפעלות אהבה אלק[י]ת כו' והיינו לאכפיי' לס\"א כנ\"ל וד\"ל. אך מאין יהי' לו הרוגז וכעס אמיתי' על היצה\"ר כנ\"ל עד שיוכל להכניעו אליו ולהפילו כנ\"ל, הענין הוא דזהו רק ע\"י הניצוח הגדול שיבוא מחמת יראת אלקים הצפון בלבו בהעלם בתוקף ועוז בעומק תוך עומק כו'.\n<b>והנה</b> אנו רואים שבחי' היראה אלקי' אינה בגילוי בלב רק בהעלם מוסתר הוא [מאד והוא] מצד שבא מחמת יראת הרוממות בגדולת הבורא ית' כמו שהוא למעלה בעילוי אחר עילוי כנ\"ל שהשגה זו באה בדרך הפלאה והבדלה, דהיינו איך שהוא מובדל ומרומם מכל ההשתל' ונק' סדכ\"ס כנ\"ל, שמזה גם היראה ופחד אלקי' יבוא בבחי' ההעלם הצפון וגנוז בפנימי' הלב והמוח בעומק גדול כו'. וע\"כ אנו רואים שכל צדיק שהוא ירא אלקים ביותר הכל הוא בבחי' ההעלם בתוך תוכו ולא נגלה כלל לזולתו, אבל העובד באהבה יהי' בהתגלות עצומה ברשפי אש התשוקה הנגלית כו' וכמ\"ש וכל הלבבות ייראוך<sup data-n=\"10997\">279</sup> כו' שהיראה בפנימי' הלב עמוק עמוק כו' (והוא כמו מ\"ש הטבעי', וכמו שידאג אדם בפנימי' הלב בעומק גדול עד שנוגע לחייו ממש. ולכן כאשר צריך האדם לבוא למלחמה על היצה\"ר שעומד לנגדו לעמוד עליו ברוגז וכעס אין זה רק כפ\"ע היראה הפנימי' שבלבו ביראת הרוממות האלקי' בפחד יצחק כו', שמחמת זה יכעס וירגז ברוגז גדול על המנגד שהוא הרע לדחותו ולהשפילו בתכלית [ב]שמאל דוחה כנ\"ל, [ו]הוא יראת חטא שתלוי ביראת הרוממות הגנוז בלב בהעלם תמיד ומוציאו מן ההעלם לגילוי גמור כאשר יבוא [ל]מלחמה דוקא עם המנגד שהוא בחי' הרע שמבלבל ומדיחו שיבוא <span data-k=\"pg\">660</span> ּ לכלל ניצוח גדול מאד כנ\"ל). וזהו ענין נצח הגם שהוא ענף החסד שבקו הימין<sup data-n=\"10998\">280</sup> שהוא",[["10994","276","<b>דחוצפא אפי' כלפי שמיא</b>: סנהדרין קה, א."],["10995","277","<b>שאין רואה חוב לעצמו</b>: שבת קיט, א."],["10996","278","<b>בכל לבבך בב' יצריך</b>: נסמן לעיל סה, ג."],["10997","279","<b>וכל הלבבות ייראוך</b>: תפלת נשמת (לשויו\"ט)."],["10998","280","<b>החסד שבקו הימין</b>: נסמן לעיל פ' וארא פד, ד."]]],[2300540572,"שמתפעל<sup data-n=\"10999\">281</sup> ביראה ופחד אלקי' שהוא בבחי' הגבו' בקו השמאל<sup data-n=\"11000\">282</sup> לעמוד בדין קשה ברוגז וכעס לנגד המנגד בניצוח גדול כמו ימינך תרעץ אויב<sup data-n=\"11001\">283</sup> (וכמשי\"ת), וההוד שהוא ענף הגבו'<sup data-n=\"11002\">284</sup> בקו השמאל מתכלל באהבה שנולדה בהתבוננו' דבינה בהתהוות מאין ליש היפך בחי' הרוממות. ונמצא שההודאה נמשך מן האהבה והנצח מן היראה<sup data-n=\"11003\">285</sup> שמתחלפים זו בזו כמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> ענין אוצר של י\"ש שגנוז בלב האדם בפנימיות בהעלם כל בחי' נקודות<sup data-n=\"11004\">286</sup> הפנימי' של י\"ש גנוז מאד וצפון בלב ומוח האדם ולא נגלה ונק' תעלומות [ה]לב שלמעלה מן השכל והרצון, והוא בחי' לב נשבר בעומק כנ\"ל מצד שיפול בלבו פחד אלקים בלתי יוכל לחטוא בפו\"מ [כמ\"ש] והי' יראת ה' על פניכם<sup data-n=\"11005\">287</sup> לבלתי תחטאו<sup data-n=\"11006\">288</sup> כו' ולעמוד בנסיון כשיבא לידי [איזה] חטא ועון שיסור ממנו מיד (וכמו פחד ה' שנופל בלב כאו\"א [בעשי\"ת] לשוב בתשובה [שלימה] כמו שיהי' לע\"ל שיהי' פחד ה' בגילוי על כל הברואים, וכמו הפרות שנשאו את הארון<sup data-n=\"11007\">289</sup> כו', שכמו זה ממש יהי' ג\"כ בע\"ש<sup data-n=\"11008\">290</sup> על כל<sup data-n=\"11009\">291</sup> מלכי ארץ כו', [ו]לפי שיגלה מן ההעלם ממל' דא\"ס עצמו שהוא בחי' ההתנשאו' [ש]מצד עצמו ממש שנק' מלך מרומם לבדו<sup data-n=\"11010\">292</sup> כו' או מלך הקדוש<sup data-n=\"11011\">293</sup> וזהו קדוש אתה ונורא שמך<sup data-n=\"11012\">294</sup> כו' בר\"ה ויוהכ\"פ כידוע). ולהיות כי בשעת המלחמה בניצוח קשה לנצח למנגד צריך להוציא כל כחו הפנימי' דוקא כדרך הנלחמי' יחד, שכאו\"א יתגבר על חבירו בכל כח ועוז עד שיבוז בעיניו כל אשר לו ויוציא בזה מפנימי' כחו בשביל ניצוח זה. כך הוא ג\"כ בענין ניצוח האדם לנצח ולהתגבר על הרע שבנפשו שנק' יצה\"ר כו' שיוציא כל בחי'<sup data-n=\"11013\">295</sup> הפנימי' בזה, והוא גילוי אוצר של י\"ש שגנוז ונעלם בתעלומות לבו מצד יראת הרוממות כמו שהוא למעלה שנק' נורא בעצם כו', שבמלחמה זו דוקא אנו רואים שנגלה מהאוצר הגנוז של י\"ש שבלבו בהעלם ובא לגילוי גמור בבחי' עומק לב נשבר ונדכה מצד יראת הפנימי' מעצמות הרוממות דוקא, שמכח יראה הגדולה הזאת שנופל פחד אלקים יכול להתגבר מאד ולבער ולגרש הרע או להכניעו בתכלית כנ\"ל (אפי' הרע שבבחי' מקיף דיחידה כמו הוללות וליצנות ופר\"ע כקליפת פלשתים<sup data-n=\"11014\">296</sup> שלנגד אור התענוג האלקי באה\"ר כו' כידוע בבארות דאברהם שסתמום פלשתים<sup data-n=\"11015\">297</sup> עפר אחר מותו שהוא בהסתלקות [ה]אהבה אחר התפלה, אבל בבחי' פחד יצחק חפר הבארות בעומק יותר להיות לנגד קליפה דפלשתים ממש, וז\"ש וישב יצחק ויחפור<sup data-n=\"11016\">298</sup>",[["10999","281","<b>שמתפעל</b>: ט: מתכלל."],["11000","282","<b>הגבו' בקו השמאל</b>: נסמן לעיל שם."],["11001","283","<b>ימינך </b>[ט: ניתוסף: ה']<b> תרעץ אויב</b>: בשלח טו, ו."],["11002","284","<b>וההוד שהוא ענף הגבו'</b>: נסמן לעיל רכא, ב."],["11003","285","<b>שההודאה נמשך מן האהבה והנצח מן היראה</b>: ראה מאמרי אדה\"ז תקס\"ז ע' נא ואילך."],["11004","286","<b>כל. . נקודות</b>: חט: כי. . נקוד'."],["11005","287","<b>והי' </b>[ט: תהי']<b> יראת ה' על פניכם</b>: יתרו כ, יז [ושם: ובעבור תהי' יראתו על פניכם — ראה שע\"ת ח, ג ובהערה 29]."],["11006","288","<b>תחטאו</b>: דט: ליתא."],["11007","289","<b>הפרות שנשאו את הארון</b>: נסמן לעיל פ' וארא עד, א."],["11008","290","<b>בע\"ש</b>: בע' שרים — נסמן לעיל פ' שמות לז, ג."],["11009","291","<b>על כל</b>: ט: וכל."],["11010","292","<b>מלך מרומם לבדו</b>: ראה גם לעיל פ' בא צ, א. וש\"נ."],["11011","293","<b>מלך הקדוש</b>: ראה גם לעיל ק, ג. וש\"נ."],["11012","294","<b>קדוש אתה ונורא שמך</b>: תפלת העמידה לימים נוראים. ראה סידור שער יוהכ\"פ רנ, ב ואילך."],["11013","295","<b>בחי'</b>: דחט: כחו."],["11014","296","<b>הוללות. . כקליפת פלשתים</b>: ראה לעיל קלז, ב. וש\"נ."],["11015","297","<b>בבארות דאברהם שסתמום פלשתים</b>: תולדות כו, טו."],["11016","298","<b>וישב יצחק ויחפור</b>: שם, כו. יח. ראה תו\"ח תולדות קמג, ד ואילך (ובהנסמן במ\"מ בריש המאמר שם)."]]],[2300540588,"כו' ונק' מ\"ח<sup data-n=\"11017\">299</sup> וע\"כ לע\"ל יאמרו על יצחק [כי] אתה אבינו<sup data-n=\"11018\">300</sup> כו'), וכידוע במעלת היראה הפנימי' שהי' בבעש\"ט ז\"ל<sup data-n=\"11019\">301</sup> שהי' מעין יראה של משיח כו' (וסימן לגודל כוחה הוא שגם בשתויי יין או אונס שינה כמו בנ\"י בזמן הגלות נתעוררו מפני פחד ה' כמו בר\"ה ויוהכ\"פ כמ\"ש במ\"א).\n<b>וזהו</b> ענין בזבוז האוצרות בשביל ניצוח זה לנצח היצה\"ר והוא לבזבז האוצר של י\"ש להיות שהי\"ש הוא בא בהתבוננו' דסוכ\"ע שלמעלה מהשגת [ה]שכל ונק' פלא וסדכ\"ס כו', <span data-k=\"pg\">של</span> ּ ובחי' התגלות הזאת מן ההעלם תלוי בהתגלות היראה הזאת בלב האדם בעומק עפר הגוף המכסה ומסתיר ביותר כמטמון הטמון בעומק הארץ ונק' עו[מ]\"ת, והוא ע\"י שמשפיל א\"ע בשפלות ולב נשבר ביותר ונגלה יותר ההעלם די\"ש הצפון וגנוז מאד והוא שמביאו ליראה ופחד בגילוי בלב מן ההעלם כו' כנ\"ל (וזהו הכלל דבכל גילוי הנעלם ונפלא ביותר כנ\"ל<sup data-n=\"11020\">302</sup> ע\"י היראה וביטול היש בתכלית, כמו קולות וברקים שבמ\"ת שעשה בכנ\"י יראה ופחד<sup data-n=\"11021\">303</sup> אלקי' שמזה הי' גילוי אור הח\"ע בסדכ\"ס שנק' אנכי<sup data-n=\"11022\">304</sup> כו', וכן [א'] מה להלן באימה וביראה וברתת<sup data-n=\"11023\">305</sup> כו', כן<sup data-n=\"11024\">306</sup> גם עתה קודם גילוי אור החכ' דתורה ממקור הנעלם צ\"ל תחלה אימה ורתת כו', כרבא דיתיב באימתא<sup data-n=\"11025\">307</sup> ופתח בשמעתא כו'<sup data-n=\"11026\">308</sup>. וכנראה בחוש שע\"י היראה דוקא נגלה ההעלם דאוצר החכ' שכל חכם אינו מתחכם בחכמה<sup data-n=\"11027\">309</sup> ממקורה כזקן שקנה חכ'<sup data-n=\"11028\">310</sup> כו', וכן אמר קנה חכמה<sup data-n=\"11029\">311</sup> רק ע\"י היראה שירא מאד מענין אלקי ע\"כ מדקדק בכל כחו לידע הדין וההלכה על בוריו ולהוסיף בה דינין מחודשי' בעיון רב ופלפול גדול לבוא לאמיתית הרצון העליון דוקא, ומזה יחודש חכמה רבה לחדש דינין והלכות חדשי' לאין שיעור כר\"ע שהי' דורש על כל קוץ<sup data-n=\"11030\">312</sup> כו'. וכ\"ז היינו רק מצד היראה שז\"ש אם אין יר\"ת אין ח\"ת [דהיינו] חכ' דתושבע\"פ בחי' מל'<sup data-n=\"11031\">313</sup> דבינה יתירה ניתנה באשה<sup data-n=\"11032\">314</sup> כו' [ו]כמ\"ש במ\"א עמ\"ש לבך יהגה אימה<sup data-n=\"11033\">315</sup> כו'<sup data-n=\"11034\">316</sup> אי' סופר אי' שוקל<sup data-n=\"11035\">317</sup> שזהו עיקר סיבה של הגזירות וסייגים כי\"ח דבר<sup data-n=\"11036\">318</sup> וכה\"ג כו' וד\"ל. וכך יובן בענין היר\"ע שגורם המשכות מאוצר בח\"ע<sup data-n=\"11037\">319</sup> כמ\"ש ראשית חכמה יראת ה' כו' וכמ\"ש בתד\"א שכל מי שיש בו",[["11017","299","<b>ונק' מ\"ח </b>[ט: מים חיים]: תולדות שם, יט."],["11018","300","<b>יצחק [כי] אתה אבינו</b>: שבת פט, ב. ישעי' סג, טז."],["11019","301","<b>היראה הפנימי' שהי' בבעש\"ט ז\"ל</b>: ראה גם בענין היראה מאמרי אדה\"ז על ענינים ע' קפז. מאמרי אדה\"א דרושי חתונה ח\"א ע' רסו. שבחי בעש\"ט — ירושלים תשמ\"ב — ע' 254 הערה 52."],["11020","302","<b>כנ\"ל</b>: דחט: צ\"ל."],["11021","303","<b>קולות וברקים. . יראה ופחד</b>: ראה גם לעיל פ' בא קטז, א. וש\"נ."],["11022","304","<b>אנכי</b>: יתרו כ, ב."],["11023","305","<b>מה להלן באימה וביראה וברתת</b>: ברכות כב, א."],["11024","306","<b>כן</b>: חט: כי."],["11025","307","<b>כרבא דיתיב באימתא</b>: ראה שבת ל, ב. תניא פ\"ז ובמ\"מ, הגהות והערות קצרות שם. מאמרי אדה\"א קונטרסים ע' שפא. וש\"נ. ש\"א מא, א ובהערה 35."],["11026","308","<b>כו'</b>: אוצ\"ל: כו')."],["11027","309","<b>בחכמה</b>: ט: כ\"א בחכמה."],["11028","310","<b>כזקן שקנה חכ'</b>: נסמן לעיל פ' שמות לא, ד."],["11029","311","<b>קנה חכמה</b>: משלי ד, ה. ז."],["11030","312","<b>כר\"ע שהי' דורש על כל קץ</b>: ראה מנחות כט, ב."],["11031","313","<b>דתושבע\"פ בחי' מל'</b>: ת\"ז בהקדמה (יז, א)."],["11032","314","<b>דבינה יתירה ניתנה באשה</b>: נסמן לעיל י, ב."],["11033","315","<b>לבך יהגה אימה</b>: ישעי' לג, יח. ראה ד\"ה זה במאמרי אדה\"א נ\"ך ע' נה ואילך. לעיל יג, ב."],["11034","316","<b>כו'</b>: חט: ליתא."],["11035","317","<b>אי' שוקל</b>: שם: ליתא."],["11036","318","<b>כי\"ח דבר</b>: ראה שבת יג, ב."],["11037","319","<b>מאוצר בח\"ע</b>: חט: האוצר דח\"ע."]]],[2300540604,"י\"ש<sup data-n=\"11038\">320</sup> כל התורה וכל החכ' בלבו כו', וכן אמר כל ת\"ח שאין בו י\"ש<sup data-n=\"11039\">321</sup> דומה לגזבר<sup data-n=\"11040\">322</sup> כו' וכמ\"ש לקנות חכ' ולב אין<sup data-n=\"11041\">323</sup> וכמו פתח לבי בתורתיך<sup data-n=\"11042\">324</sup> וראי' מר\"ע שהי' ע\"ה<sup data-n=\"11043\">325</sup> כו' וכן אמר חכם לכשירצה<sup data-n=\"11044\">326</sup> כו'. וז\"ש שאין לו בעולמו רק אוצר של י\"ש כי ע\"י אוצר של י\"ש נמשך בחי' ח\"ע וח\"ת לבריאת העולמות<sup data-n=\"11045\">327</sup> וכמ\"ש יראת ה' לחיים<sup data-n=\"11046\">328</sup> [כו', וראי' מן המלאכי' שהם נצחיי' יותר מן הנשמות] לפי שיש בהם מבחי' היראה דמל' יותר וזהו קיום כל העולמות<sup data-n=\"11047\">329</sup> וכמ\"ש מלכותך מלכות כ\"ע<sup data-n=\"11048\">330</sup> כו' והיראה נמשך מבחי' המל' כו', וע\"כ גם משיח שאמר [בו] חיים נתת לו<sup data-n=\"11049\">331</sup> בבחי' נצחיות כמש\"א דוד מלך ישראל חי וקיים<sup data-n=\"11050\">332</sup> ש[י]איר בו מבחי' מל' דא\"ס עצמו שע\"ז אמר ימלוך לע\"ו<sup data-n=\"11051\">333</sup> כו' וד\"ל.\n<b>וזהו</b> ענין הבזבוז של האוצר די\"ש שהי' בהעלם ויצא לגילוי בשביל ניצוח דוקא כמו שמשתמשים באוצר להוציאו לפרקים בשביל ניצוח מלחמה [ב]לבד מפני שהניצוח הוא מגיע למעלה מן הרצון ותענוג כנ\"ל, וע\"כ כדי לאכפייא לס\"א דוקא מתעורר ביראת אלקים מן ההעלם כדי לנצח הרע ברוגז וכעס כנ\"ל בענין לעולם ירגיז אדם כו', שאין רוגז זה רק בגילוי היראה מן ההעלם דוקא. משא\"כ כשהיראה בהעלם ואין לו דבר המנגד לבוא בניצוח זה אינו בא לרוגז זה כלל (אך הנה עדיין י\"ל מה שיש לכאורה סתירה על מאמר [זה] דאוצר של י\"ש שיש לו בעולמו ממ\"ש דהכל בי\"ש חוץ מי\"ש שהוא בידי אדם ולא בידי שמים כו'. אמנם באמת הנה עיקר אוצר זה <span data-k=\"pg\">662</span> ּ של י\"ש הוא למעלה בעולם העליון הנעלם ומופלא וכל שעליון יותר שם גנוז בחי' יר\"ע יותר, והוא מטעם הנ\"ל מאחר שזהו בבחי' או\"ח העולה למעלה דוקא עד בחי' סדכ\"ס דלית מחת\"ב שנק' נורא תהלות ואדון הנפלאות<sup data-n=\"11052\">334</sup> העליונים כו', וע\"ד שאמר שגם אור צח [כו'] אוכם הוא כו' בבחי' יראה בושת כנ\"ל (והוא בחי' מל' דא\"ס שיאיר במשיח כנ\"ל), עד שנמשך היראה למטה מטה גם במלאכים דבי\"ע כמ\"ש ואימתך עליהם<sup data-n=\"11053\">335</sup>, וכן גם על ע\"ש כמ\"ש תפול עליהם אימתה<sup data-n=\"11054\">336</sup> כו' וכמ\"ש מלך אלקים על גוים<sup data-n=\"11055\">337</sup> כו' וכתיב מי לא ייראך מלך הגוים<sup data-n=\"11056\">338</sup> כו'. וזהו שא' שאין לו בעולמו רק אוצר של י\"ש העליונה, אך עכ\"ז נק' אוצר שהוא",[["11038","320","<b>בתד\"א שכל מי שיש בו י\"ש</b>: ראה דב\"ר פי\"א, ו."],["11039","321","<b>כל ת\"ח שאין בו י\"ש</b>: נסמן לעיל פ' בא צא, ב."],["11040","322","<b>ת\"ח. . לגזבר</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשטו."],["11041","323","<b>לקנות חכ' ולב אין</b>: משלי יז, טז."],["11042","324","<b>פתח לבי בתורתיך</b>: ברכות יז, א (תפלת אלקי נצור)."],["11043","325","<b>מר\"ע שהי' ע\"ה</b>: פסחים מט, ב. ראה גם תו\"ח וישב רט, ב ובהנסמן במ\"מ לשם."],["11044","326","<b>חכם לכשירצה</b>: גיטין סז, א. ראה הנסמן בהערה שלפנ\"ז."],["11045","327","<b>העולמות</b>: ח: ניתוסף: וזהו קיום כל העולמות. וראה להלן הערה 329."],["11046","328","<b>יראת ה' לחיים</b>: ראה גם לעיל פ' בא ק, א. וש\"נ."],["11047","329","<b>וזהו קיום כל העולמות</b>: ח: ליתא. וראה לעיל הערה 327."],["11048","330","<b>מלכותך מלכות כ\"ע</b>: תהלים קמה, יג."],["11049","331","<b>משיח. . חיים נתת לו</b>: תהלים כא, ה [בדילוג]. סוכה נב, א. ראה לקמן רלד, א. פ' משפטים ש, ב. שג, ב. מאמרי אדה\"א ויקרא ח\"א ע' קיג־ דברים ח\"ג ע' תשנב־ קונטרסים ע' שנא ובהנסמן בהנ\"ל."],["11050","332","<b>דוד מלך ישראל חי וקיים</b>: ר\"ה כה, א. נוסח קידוש לבנה. ראה גם לעיל פ' וארא עה, ד. וש\"נ."],["11051","333","<b>ימלוך לע\"ו</b>: בשלח טו, יח. ראה גם לעיל קנה, ב."],["11052","334","<b>נורא תהלות ואדון </b>[דח: ניתוסף: כל]<b> הנפלאות</b>: ע\"פ ברכת יוצר. ראה גם לעיל קסה, א ואילך."],["11053","335","<b>ואימתך עליהם</b>: נסמן לעיל פ' וארא עה, ב."],["11054","336","<b>תפול עליהם אימתה</b>: בשלח טו, טז."],["11055","337","<b>מלך אלקים על גוים</b>: תהלים מז, ט."],["11056","338","<b>מי לא ייראך מלך הגוים</b>: ירמי' י, ז."]]],[2300540618,"גנוז ונעלם ואינו נגלה כלל רק לפרקים רחוקים כמו להטיל אימה יתירה על המנגד כמו פרעה וסנחריב וכה\"ג להשפיל גאים במלחמה כמו כי עליון יתן קולו<sup data-n=\"11057\">339</sup> ישלח חיציו<sup data-n=\"11058\">340</sup> כו' וכן אש לפניו תלך<sup data-n=\"11059\">341</sup> כו' וכה\"ג. אמנם כדי שיעורר שיבוא מבחי' ההעלם דעו[מ]\"ר הנ\"ל למטה מטה כ\"כ זהו תלוי באתדל\"ת דוקא והוא בגילוי ההעלם שלמטה בעו[מ]\"ת שנתב\"ס דוקא, והיינו בגילוי היראה מן ההעלם שבתוך נקודת הלב המוסתר בחומר עפר הגוף כמים שמתחת לארץ שבוקעים ויוצאים מן ההעלם מלמטה למעלה בבחי' או\"ח כו' עי\"ז יעוררו אתדל\"ע בגילוי מן ההעלם דאוצר של הי\"ש שלמעלה מעלה שיומשך עד למטה מטה. וכמו שהי' כבר לעולמים בעת הנצרך לניצוח להשפיל למנגד כנ\"ל וכן במכ\"ב<sup data-n=\"11060\">342</sup> דמצרים דכתיב ועברתי כו' אני ולא מלאך<sup data-n=\"11061\">343</sup> כו' והוא מ\"ש מוציא רוח מאוצרותיו<sup data-n=\"11062\">344</sup> כו'<sup data-n=\"11063\">345</sup> שהכה בכורי מצרים<sup data-n=\"11064\">346</sup> כו' [שע\"י רוח זה העליון שהי' גנוז ונעלם באוצרותיו בא לגילוי ומזה הי' מפלת י' כתרין דק\"נ<sup data-n=\"11065\">347</sup> במכת בכורות כו'] (וכה\"ג במחנה סנחריב דכתיב והשמיע ה'<sup data-n=\"11066\">348</sup> את הוד קולו כו', וכה\"ג וכן לע\"ל שיפול פחד אלקים על כל כו' וכמ\"ש כל העמים תקעו כף<sup data-n=\"11067\">349</sup> כו' כי ה' עליון נורא<sup data-n=\"11068\">350</sup> כו' וזה בכל ר\"ה למעלה כידוע). והכל ע\"י אתעדל\"ת בהגלות אוצר של י\"ש באדם למטה בעו\"ת<sup data-n=\"11069\">351</sup> דוקא, ועז\"א הכל בידי שמים חוץ מי\"ש דהיינו אוצר של יר\"ש הגנוז למטה בעו[מ]\"ת שזה אינו בידי שמים כמ\"ש השמים שמים לה'<sup data-n=\"11070\">352</sup> והארץ נתן לבנ\"א, שזהו הניתן בבחירה שבאדם כמאמר ואילו צדיק ורשע<sup data-n=\"11071\">353</sup> לא קאמר. ואע\"פ שכבר יש האוצר של י\"ש למעלה בעו[מ]\"ר עד רום המעלות כנ\"ל אבל גילוי שלו תלוי בגילוי דעו[מ]\"ת דוקא כו', והוא מ\"ש אז ראה ויספרה<sup data-n=\"11072\">354</sup> [ש]זהו אוצר היראה והח\"ע הכינה וגם חקרה אבל עיקר שלימות שלה הוא למטה דוקא והוא בבירור התחתון דאדם שלמטה בגילוי בעו[מ]\"ת, כמ\"ש ויאמר לאדם התחתון דוקא הן יראת ה' ה[י]א ח\"ע וסו\"מ בפו\"מ הוא בינה ש\"מ<sup data-n=\"11073\">355</sup> כו' לפי שנעוץ תחב\"ס דוקא וכמ\"ש ביום ההוא יצאו מ\"ח<sup data-n=\"11074\">356</sup> כו' וכמ\"ש במ\"א. וא\"כ [ב'] המאמר[ים] הנ\"ל אמת דהכל בי\"ש חוץ מי\"ש שלמטה באדם וגם זה אמת דאין לו רק אוצר כנ\"ל ואינם סותרים זא\"ז כלל וד\"ל.\n<b>והנה</b> ע\"ד כל הנ\"ל בענין הבזבוז אוצר של י\"ש לניצוח מלחמה באדם למטה עם היצה\"ר כו', כך יובן מזה למעלה [ש]באתעדל\"ת נעשה אתעדל\"ע עד\"ז ממש דהיינו בשביל ניצוח",[["11057","339","<b>כי </b>[ט: ליתא]<b> עליון יתן קולו</b>: שמו\"ב כב, יד־ תהלים יח, יד [ושם: ועליון יתן קולו]."],["11058","340","<b>ישלח חיציו</b>: תהלים יח, טו [ושם: וישלח חיציו]. שמו\"ב כב, טו [ושם: וישלח חיצים]."],["11059","341","<b>אש לפניו תלך</b>: תהלים צז, ג."],["11060","342","<b>וכן במכ\"ב</b>: חט: וכמו במכת בכורות."],["11061","343","<b>ועברתי כו' אני ולא מלאך</b>: נסמן לעיל פ' וארא נד, ב."],["11062","344","<b>מוציא </b>[ח: מוצא]<b> רוח מאוצרותיו</b>: תהלים קלה, ז [ושם: מוצא — אבל כ\"ה גם במאמרי אדה\"ז תקס\"ה כאן (ע' תתקצד)]. וראה בסמוך בפנים ליד הערה 358."],["11063","345","<b>כו'</b>: חט: ליתא."],["11064","346","<b>שהכה בכורי מצרים</b>: תהלים שם, ח."],["11065","347","<b>י' כתרין דק\"נ</b>: נסמן לעיל קלו, ד."],["11066","348","<b>במחנה סנחריב. . והשמיע ה'</b>: ישעי' ל, ל. ראה גם לעיל פ' שמות ל, ג. וש\"נ."],["11067","349","<b>כל העמים תקעו כף</b>: תהלים מז, ב."],["11068","350","<b>כי ה' עליון נורא</b>: תהלים שם, ג."],["11069","351","<b>בעו\"ת</b>: חט: ליתא."],["11070","352","<b>השמים שמים לה'</b>: תהלים קטו, טז."],["11071","353","<b>ואילו צדיק ורשע</b>: ראה נדה טז, ב. תניא פ\"א. תו\"א משפטים עח, ד. מאמרי אדה\"א דברים ח\"א ע' רכג. וש\"נ. שעה\"י קלה, א ובהערה 9."],["11072","354","<b>אז ראה ויספרה</b>: איוב כח, כז."],["11073","355","<b>ש\"מ</b>: ח: שלמעלה."],["11074","356","<b>ביום ההוא יצאו מ\"ח</b>: זכרי' יד, ח."]]],[2300540632,"לאכפייא לסט\"א המנגד לרצון אלקי ד[א]זלעו\"ז <span data-k=\"pg\">שלא</span> ּ עשה [ה]אלקים<sup data-n=\"11075\">357</sup> כידוע אז מוציא ה' מאוצרותיו העליונים הגנוזים למעלה מעלה והוא מיר\"ע שנמשך מבחי' ההעלם דסדכ\"ס הנק' נורא שממנו נמשך היראה וביטול על כל העליונים ותחתונים וכנ\"ל בענין מגלה עמוקות מני חשך כו', וכמו במכ\"ב שהוציא רוח מאוצרותיו וכנ\"ל (ואעפ\"י שז\"ש מוציא רוח כו' קאי אדסמיך לי' בפסוק שלמעלה<sup data-n=\"11076\">358</sup> מעלה נשיאים מקצה הארץ<sup data-n=\"11077\">359</sup> ברקים למטר עשה וגם רוח לגשם מוציא רוח מאוצרותיו שהוא בורא רוח כו' כפשוטו מ\"מ יכול להתפרש דקאי על של אחריו שא' שהכה בכורי כו').\n<b>ובכ\"ז</b> יובן המאמר על והנצח זו בנין ירושלים דלע\"ל שירושלים דלעתיד יהי' נצחי' לפי שיבנה ממדת<sup data-n=\"11078\">360</sup> הנצח העליון דוקא (והיינו כמשל מלך ב\"ו שמבזבז כל אוצרותיו שלו שלא ה[י' מ]שתמש [בהם] אף לצורך גדול או להשתעשע בהם כנ\"ל, ולמעלה היינו אוצר העליון דיר\"ע ביראת הרוממות וההתנשאו' שמצ\"ע ממש שלא נגלה כלל בעולמות [ד]אבי\"ע, כי כללות המשכת [ה]אורות דקו\"ח ממל' דא\"ס אינה באה רק ע\"י צמצום העצמי' כמ\"ש ה' מלך גאות לבש<sup data-n=\"11079\">361</sup> כו' (וע\"כ אומר גלה כבוד מלכותך ממש עלינו<sup data-n=\"11080\">362</sup> לע\"ל והופע לעיני כל חי שיהי' בחי' פחד ה'<sup data-n=\"11081\">363</sup> עד שייראוך כל המעשים<sup data-n=\"11082\">364</sup> כו'). וזהו כמשל האוצרות שגנוזי' בהעלם<sup data-n=\"11083\">365</sup>, כי מה שנמשך בעולמות שנק' קנין כמו קונה שמים וארץ<sup data-n=\"11084\">366</sup>, וכן בפנימי' העולמות כתיב תורה<sup data-n=\"11085\">367</sup> קנין א'<sup data-n=\"11086\">368</sup> כמ\"ש ה' קנני ראשית דרכו<sup data-n=\"11087\">369</sup> כו', וכל קנין בכסף וזהב שזהו העלאות בירורים דרפ\"ח<sup data-n=\"11088\">371</sup> כו' והוצאה זו הכנסה קרי לי' שמרויח בכפלי כפליים בבירורים<sup data-n=\"11089\">370</sup> והעלאות העולמות בכלל ובפרט כו'. אבל האוצר העליון הוא למעלה מהוצאה זו הנצרך כו', וגם בעת השמחה כמועדים ורגלים וגם בר\"ה ויוכ\"פ לא נגלה מן בחי' ההעלם הזה רק אפס קצהו כו', וגם רואי פני המלך כנביאים וחכמי התורה לא נגלה להשתעשע בזה אפי' לעצמו כמו בג\"ע העליון, וגם כשיושב ועוסק בתורה ומצות ש\"מ כו', רק בעת חתונתו או חתונת בנו כמו במ\"ת ולע\"ל כו', ועכ\"ז למלחמה מוציא ומבזבז כל אוצרותיו של י\"ש העליונים בשביל ניצוח שיהי' כרצונו דוקא כו'). ומבואר למעלה במשל מלך ב\"ו שגם עם שר ומלך קטן שאין בזה קיבוץ הון ועושר דכלא חשיב גם לא גדולה וממשלה יתירה כו' רק שלא יהי'",[["11075","357","<b>ד[א]זלעו\"ז עשה [ה]אלקים</b>: נסמן לעיל פ' שמות לד, ג."],["11076","358","<b>שלמעלה</b>: ט: ליתא."],["11077","359","<b>מעלה נשיאים מקצה הארץ</b>: תהלים קלה, ז."],["11078","360","<b>ממדת</b>: ט: מבחי'."],["11079","361","<b>ה' מלך גאות לבש</b>: ראה גם לעיל פ' וארא עה, א. וש\"נ."],["11080","362","<b>גלה כבוד מלכותך. . עלינו</b>: מוסף ליו\"ט."],["11081","363","<b>ה'</b>: ט: ניתוסף: על כל חי."],["11082","364","<b>שייראוך כל המעשים</b>: תפלת העמידה לימים נוראים."],["11083","365","<b>בהעלם</b>: ח: לעולם."],["11084","366","<b>קונה שמים וארץ</b>: לך יד, יט. כב."],["11085","367","<b>כתיב תורה</b>: דח: בתורה. ט: כמו תו'."],["11086","368","<b>תורה קנין א'</b>: אבות פ\"ו, י."],["11087","369","<b>ה' קנני ראשית דרכו</b>: משלי יח, כב. הובא באבות שם."],["11088","371","<b>דרפ\"ח</b>: נסמן לעיל פ' שמות לו, ג."],["11089","370","<b>וכל קנין. . בבירורים</b>: ראה גם ד\"ה וישב יעקב תקס\"ג נדפס במאמרי אדה\"ז על פרשיות התורה ח\"א ע' קפד ואילך. תו\"א וישב כו, ג ואילך."]]],[2300540645,"כרצון המנגד שעומד לנגד רצונו גם בדבר קטן שאין רצונו כ\"כ בזה כו'.\n<b>וכך</b> יובן למעלה דהנה באמת גם בזלעו\"ז<sup data-n=\"11090\">372</sup> הכל ממנו ית' כמ\"ש כי ממך הכל<sup data-n=\"11091\">373</sup> ולא יתכן לומר בזה שיהי' לו מנגד באמת<sup data-n=\"11092\">374</sup> כמו במלך בו\"ד כו'<sup data-n=\"11093\">375</sup>, ואין המשל דומה לנמשל כלל שבמלך ב\"ו הניצוח הוא הכרחי מצ\"ע לפי שיש לו מנגד באמת שמורד בו ומולך מעצמו כו'. אבל באלקים חיים ומלך עולם<sup data-n=\"11094\">376</sup> שאין לך דבר חוץ ממנו ית'<sup data-n=\"11095\">377</sup> ח\"ו כו', וגם מה שיש לעומת הקדושה האלקי' הכל עשה האלקי' עצמו ע\"י ריבוי הצמצומים שהפרידן מיחודו העצמית כידוע, ועכ\"ז גם הם נכנעים ובטלים אליו בכל עת כמו מלך אלקים כו', וגם בלעם אמר לא אוכל לעבור<sup data-n=\"11096\">378</sup>, <span data-k=\"pg\">664</span> ּ וכתי' ייראו מה' כל הארץ<sup data-n=\"11097\">379</sup> ממנו יגורו כל יושבי תבל<sup data-n=\"11098\">380</sup> וכתיב מי לא יראך מלך הגוים כו', וא\"כ איך יקרא בשם מנגד כו'. אך הענין הוא שגם זה שעשה אלקים לעומת הקדושה והפרידן מאחדותו ית', זה הי' בכוונה בתחלה שיהי' בחי' נפרד גמור בק\"נ דעשי' שרובו רע<sup data-n=\"11099\">381</sup> כו' עד שיוכל למרוד ולומר לאל סור ממנו<sup data-n=\"11100\">382</sup> כו' כדור הפלגה וכה\"ג, כדי שיוחל ע\"ז בחי' מדת הניצוח [ה]עליון האלקי בהיותם מסתירים ומונעים גילוי אור אלקי ויבא לכלל ניצוח לנצחם במלחמה ברוגז וחרון אף כמו ה' כגבור יוצא כאיש מלחמות כו' על אויביו יתגבר<sup data-n=\"11101\">383</sup> כו' וכמ\"ש מי זה בא מאדום<sup data-n=\"11102\">384</sup> כו' פורה דרכתי לבדי כו' ויז נצחם על בגדי<sup data-n=\"11103\">385</sup> כו' (נצח דק\"נ שמקבלים מאחוריים דנצח דקדושה כשנגע בירך יעקב<sup data-n=\"11104\">386</sup> כו', וז\"ש וגם נצח ישראל לא ישקר<sup data-n=\"11105\">387</sup> כו' כמ\"ש במ\"א בענין שמואל הנביא שתיקן מעט הפגם הזה דנצח ושלימותו יתוקן בביאת משיח, שזהו טעם אריכות הגלות דעכשיו ותיקן בזה דנצח<sup data-n=\"11106\">388</sup> דקדושה בבזבוז כל האוצרות כמו מגלה עמוקות כו' כנ\"ל שזהו אוצר של י\"ש (וכמ\"ש במ\"א דאיהו בנצח<sup data-n=\"11107\">389</sup> כו'). והוא ענין הסכם [ה]חזק בניצוח זה שמגיע למעלה מן הרצון ותענוג כנ\"ל והוא בבחי' יחידה עד שיכול למסו\"נ ע\"ז כו'), וכל בזבוז אוצרות העליונים לא יגלה כ\"א במדות הניצוח דוקא כמשל בזבוז אוצרות המלך כו' בשביל ניצוח מלחמה כנ\"ל. וזהו לך הוי' הגדולה<sup data-n=\"11108\">390</sup> כו' עד והנצח דמשמע דכמו שבחי' הגדולה והגבורה בטל לגבי עצמות דשם הוי' כך לך הוי' הנצח כו' שבטל גם מדת הנצח הע[ליון] לגבי עצמות המאציל דלאו מכא\"מ כלל כידוע. והענין הוא דגם שהנצח שרשו בעצמו' הנפש ממש שלמעלה מן הרצון ו[ה]תענוג כו', אבל [גם] הוא בבחי' התפעלות המדות עכ\"פ שהוא תוקף הרצון שבא מתוקף הנפש עצמה כמו",[["11090","372","<b>בזלעו\"ז</b>: חט: (במה) שא' זלעו\"ז (עשה) כו'."],["11091","373","<b>כי ממך הכל</b>: דהי\"א כט, יד."],["11092","374","<b>באמת</b>: חט: ממש."],["11093","375","<b>כו'</b>: שם: ליתא."],["11094","376","<b>באלקים חיים ומלך עולם</b>: ע\"פ ברכת יוצר."],["11095","377","<b>ית'</b>: חט: ליתא."],["11096","378","<b>לא אוכל לעבור</b>: בלק כב, יח."],["11097","379","<b>ייראו מה' כל הארץ</b>: תהלים לג, ח."],["11098","380","<b>כל יושבי תבל</b>: חט: כו'."],["11099","381","<b>בק\"נ דעשי' שרובו רע</b>: ראה ע\"ח (שער ציור עולמות) שמ\"ג, בהקדמה. (שער סדר אבי\"ע) שמ\"ז, פ\"ד. (שער ק\"נ) שמ\"ט, פ\"ו."],["11100","382","<b>לאל סור ממנו</b>: איוב כא, יד."],["11101","383","<b>ה' כגבור. . יתגבר</b>: ישעי' מב, יג."],["11102","384","<b>מי זה בא מאדום</b>: ישעי' סג, א."],["11103","385","<b>פורה דרכתי. . בגדי</b>: ישעי' שם, ג."],["11104","386","<b>כשנגע בירך יעקב</b>: וישלח לב, כו."],["11105","387","<b>וגם נצח ישראל לא ישקר</b>: ראה גם לעיל פ' שמות יד, ד. וש\"נ."],["11106","388","<b>ותיקן בזה דנצח</b>: דח: והתיקון הזה בניצוח."],["11107","389","<b>דאיהו בנצח</b>: נסמן לעיל טו, א."],["11108","390","<b>לך הוי' הגדולה</b>: דהי\"א כט, יא."]]],[2300540657,"לעמוד על נפשו [ו]להשליך כל אשר לו מפני הניצוח כו', ובאמת א\"א לומר זה למעלה שאין מנגד כלל באמת מאחר שהוא ית' פעל ועשה כל זאת שיהי' בבחי' נפרד ויהי' חל עליו בחי' מדת הניצוח כו', ע\"כ א' לך הוי' הנצח שגם בחי' מדת הנצח בטל לגבי עצמות דש' הוי' שלפני ההשתל' כמו לך הוי' הגדולה שהוא החסד שמתפשט מאוא\"ס להיות התהוות מאין ליש כידוע וד\"ל. אך עכ\"ז בחי' מדת הניצוח גבוה בשרשו מן בחי' החסד וגם מן התענוג שבעצמות עד שיוכל להניח כל התענוגים רק מפני מדת הניצוח ע\"כ א' והנצח זו בנין ירושלים דלע\"ל שיהי' ע\"י מדת הנצח דוקא ע\"כ יהי' נצחי דנצח הוא ל' נצחית כו'.\n<b>והענין</b> הוא כידוע שיש ב' מיני רצון, א' רצון המורכב בשכל וטעם או תענוג המלובש ברצון עד שכל נפשו נמשך בדבר הזה שרוצה להיותו בבחי' פנימיות ועצמיות שבו ממש. וכך יש רצון ותענוג העליון [שמלובש] בחכמה וטעם שהן התו\"מ ובנש\"י שעלו בפנימי' הרצון והתענוג כו' בבחי' עצמי', כידוע דישראל <span data-k=\"pg\">שלב</span> ּ עבמ\"ח<sup data-n=\"11109\">391</sup> כו', וזהו ג' קשרין<sup data-n=\"11110\">392</sup> דס\"ר אותיות התורה<sup data-n=\"11111\">393</sup> וס\"ר נש\"י<sup data-n=\"11112\">394</sup> כו', והוא ענין הבחירה שבחר בתורה ובישראל ובבהמ\"ק וירושלים עיר קדשו וכמ\"ש גדול ה' כו' בעיר אלקינו הר קדשו<sup data-n=\"11113\">395</sup> כו', וכ\"ה למעלה בירושלים ובבהמ\"ק של מעלה כידוע. אך עכ\"ז בחירה זאת יכולה לבוא בהשתנות מהיפוך להיפוך כאשר לא הלכו בנ\"י בדרך ה' בתו\"מ בא\"י ועבדו ע\"ז כו', כמו שהי' בב\"ר וב\"ש שנשתנה מרצון לרצון היפוכו למאוס בישראל ובירושלים [ו]השליכם לארץ אחרת, וגם המקום שבחר בו שזה<sup data-n=\"11114\">396</sup> הוא ירושלים ובהמ\"ק הי' לחורבן ושממה כו'. וזהו לפי שבחירה זו הי' מצד רצון המורכב בחכמה שבתו\"מ בטעם ותענוג, אע\"פ שהוא בבחי' פנימי' כו' יש לו הפסק וחילוף. אבל בנין בהמ\"ק וירושלים דלע\"ל יהי' מלמעלה מן הרצון המורכב בחכ' שבתו\"מ ולא מצד התענוג ואה\"ר העצמות, רק מצד בחי' מדת הניצוח שהוא למעלה מן הרצון לגמרי ולמעלה גם מן התענוג הפנימי ביותר שהרי משליך כל התענוגי' הפנימים בשביל הניצוח כו', ע\"כ אין לו שינוי והפסק לעולם. כי גם שישראל אינם ראוים כלל לגאולה ולבנין ירושלים ובהמ\"ק ואף שכבר נפסק מהם עוז אה\"ר העצמי' מפני רוע מעשיהם כו', עכ\"ז מצד הניצוח שלא יהי' כרצון המנגד שהוא ס\"א שנק' שטן שעומד לנגדו למשול בישראל ובירושלים (כי כל יניקה שלו אינו רק מחורבנה של ירושלים דאזלעו\"ז כו', וכמ\"ש אמלאה<sup data-n=\"11115\">397</sup> כו' לא נתמלא צור<sup data-n=\"11116\">398</sup> שהוא אדום<sup data-n=\"11117\">399</sup> כתר דק\"נ<sup data-n=\"11118\">400</sup> רק",[["11109","391","<b>דישראל עבמ\"ח</b>: נסמן לעיל פ' שמות לב, ב."],["11110","392","<b>ג' קשרין</b>: נסמן לעיל ב, ד."],["11111","393","<b>דס\"ר אותיות התורה</b>: נסמן לעיל לב, ב."],["11112","394","<b>וס\"ר נש\"י</b>: נסמן לעיל קפג, ג."],["11113","395","<b>גדול ה'. . קדשו</b>: תהלים מח, ב."],["11114","396","<b>שזה</b>: חט: ליתא."],["11115","397","<b>אמלאה</b>: יחזקאל כו, ב."],["11116","398","<b>לא נתמלא צור</b>: נסמן לעיל קלה, ד."],["11117","399","<b>צור שהוא אדום</b>: ראה זכרי' ט, ה וברש\"י שם. פסחים מב, ב וברש\"י ד\"ה אמלאה (וביעב\"ץ שם). מגילה ו, א וברש\"י שם (מהרש\"א שם. תוד\"ה עקרון בע\"י שם). מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתלז."],["11118","400","<b>אדום כתר דק\"נ</b>: ראה גם מאמרי אדה\"א דברים ח\"א ס\"ע י."]]],[2300540669,"מחורבנה שהוא גלות השכינה בע\"ש כו' אשר שלט האדם באדם<sup data-n=\"11119\">401</sup> כו', וז\"ש מי זה בא מאדום כו' ויז נצחם כו' כנ\"ל) יעמוד לנגדו בכל כח וגבורה בהגלות אוצרות עליונים כדי לבנות בנין ירושלים ובהמ\"ק כמ\"ש יגער ה' בך השטן ויגער בך הבוחר בירושלים<sup data-n=\"11120\">402</sup>. ובחירה זו למעלה מן הרצון והטעם לגמרי רק תוקף הרצון בזה אינו רק מצד מדת הניצוח שנוגע בעצמות ממש, וע\"כ יהי' בנין ירושלים דלע\"ל נצחי' דא\"ס ממש וכמ\"ש וגם נצח ישראל לא ישקר, פי' לא יופסק ויבוטל לעולם כו' כי לא יהופך כלל מרצון לרצון היפוכו מטעם זו שבחי' הנצח אין בו שינוי ותמורה וזהו לא יכזב<sup data-n=\"11121\">403</sup> כו' כמו אשר לא יכזבו מימיו<sup data-n=\"11122\">404</sup> כו'. וזהו כי לא אד\"ם הוא להנח\"ם<sup data-n=\"11123\">405</sup> ולהתהפך מהרצון<sup data-n=\"11124\">406</sup> ע\"פ שינוי החכ' וטעם כלל, אבל ניצחו[ן] זה הוא למעלה מבחי' אדם כי בחי' אדם הוא [ברצון] המורכב בחו\"ב ותענוג כו' (שהוא [ה]תו\"מ שנק' אדם פנימי וחיצוני<sup data-n=\"11125\">407</sup> כידוע) וז\"ש במשיח וגבה מאד<sup data-n=\"11126\">408</sup> בהיפוך אותיות אדם<sup data-n=\"11127\">409</sup> כו' וד\"ל.\n<b>והנה</b> מבואר מכל הנ\"ל שכל עיקר סיבת בנין ירושלים דלע\"ל שיהי' נצחיות ויהי' בנינה בתכלית היופי והעושר גדול ו[ת]תפשט בכל א\"י וא\"י בכל העולם כמ\"ש בגמ'<sup data-n=\"11128\">410</sup> וכמ\"ש פרזות תשב ירושלים<sup data-n=\"11129\">411</sup> (כמשי\"ת) היינו רק ממדת הנצח שעי\"ז<sup data-n=\"11130\">412</sup> הוציא ובזבז כל אוצרות העליונים כו', וממילא מובן מזה כאשר יבנה ירושלים דלע\"ל יתגלה בה כל אוצרות חמדה וכל טוב העליון הגנוז למעלה ברוחניות בא יבא<sup data-n=\"11131\">413</sup> בהגשמה (בגעה\"ע וגעה\"ת דעכשיו), והוא בחי' היופי והעושר המופלא שיהי' בירושלים דלע\"ל שיקובץ בה מלמעלה ומלמטה <span data-k=\"pg\">666</span> ּ מכל הטוב הנברר בע\"ש דק\"נ שכולם יביאו מנחה מכל טוב הארץ לירושלים כמבואר בכתובים [רבים] כל הנשאר בציון<sup data-n=\"11132\">414</sup> ובירושלים קדוש יאמר לו כו'. והטעם הוא מאחר שכל המכוון בכל ההשתל' דז' ימי הבנין דאצי' ובי\"ע ברצון וחכ' וחסד כו' הכל בשביל הניצוח שיהי' באחרונה, והוא כאשר יעמדו החיצונים לנגדו כי הכל פעל ועשה בעצמו. ולזאת הי' [ה]כוונה שיהי' מדת הנ[י]צ[ו]ח ויבנה עי\"ז דוקא בנין ירושלים, וע\"כ כשיושלם הניצוח יגלה בה כל אורות עליונים ביותר ויהי' בה שמחת עולם הנצחי' ממש שהוא בבחי' א\"ס ממש וכמ\"ש והביאנו לציון עירך ברנה<sup data-n=\"11133\">415</sup> ולירושלים בית מקדשך בש\"ע וד\"ל. ויובן זה עד\"מ מלך גדול שכבש כל העולם ונשאר לפניו מדינה א' קטנה לכובשה והוציא עליה כל אוצרות[יו] עד שכבשה שאז בגמר ניצוח המלחמה הזאת עשה משתה גדולה לכל שריו ועבדיו בכל מיני [כלי] יקר ואבני חפץ",[["11119","401","<b>אשר שלט האדם באדם</b>: נסמן לעיל פ' שמות ל, ד."],["11120","402","<b>יגער ה' בך. . בירושלים</b>: זכרי' ג, ב [בדילוג]."],["11121","403","<b>לא </b>[דחט: ולא]<b> יכזב</b>: משלי יד, ה. חבקוק ב, ג."],["11122","404","<b>אשר לא יכזבו מימיו</b>: ישעי' נח, יא."],["11123","405","<b>כי לא אד\"ם הוא להנח\"ם</b>: המשך הכתוב וגם נצח ישראל (שמו\"א טו, כט)."],["11124","406","<b>מהרצון</b>: חט: מרצון לרצון."],["11125","407","<b>[ה]תו\"מ שנק' אדם פנימי וחיצוני</b>: ראה גם לעיל קנט, ב."],["11126","408","<b>וגבה מאד</b>: ישעי' נב, יג."],["11127","409","<b>מאד. . אדם</b>: ראה זהר (רע\"מ) פינחס רמו, ב. ב\"ר פ\"ח, ה. פ\"ט, יב. ראה גם שה\"א ע' פט."],["11128","410","<b>ירושלים. . ו[ת]תפשט. . העולם כמ\"ש בגמרא</b>: ראה פסיקתא רבתי פ' שבת ור\"ח. יל\"ש ישעי' סו, כג (רמז תקג). הנסמן במאמרי אדה\"א שמות ח\"ב ע' תס. לקמן רלג, סע\"ג ואילך."],["11129","411","<b>פרזות תשב ירושלים</b>: זכרי' ב, ח."],["11130","412","<b>שעי\"ז</b>: אוצ\"ל: שע\"ז."],["11131","413","<b>בא יבא</b>: דט: יבא[ו] בה. ח: ובא בה."],["11132","414","<b>כל הנשאר בציון</b>: ראה להלן הערה 812."],["11133","415","<b>והביאנו לציון עירך ברינה</b>: מוסף ליו\"ט."]]],[2300540681,"ויין הטוב ומיני מעדנים וציווה לשמוח בשמחה גדולה ועצומה בכל מיני ניגון ובכל כלי שיר ינג[נו] לפניו, ושמחה זאת אינה גדולה כ\"כ רק מחמת שנשלם הניצוח שנצח למנגדו הגם שהוא קטן בערך מאד ולא השיג מזה הון וכבוד וגדולה כלל, אך מאחר שהוכרח להוציא כל אוצרותיו ע\"ז וכ\"ז הי' בתחבולה מכבר ע\"כ יקר בעיניו יותר מכל הון וכבוד שהוכרח<sup data-n=\"11134\">416</sup> ותגדל השמחה ביותר (והוא מטעם הנ\"ל שהנצח מגיע בעצמות הנפש ממש למעלה מכל התענוגי' הגדולים כו'). וכך יובן למעלה בבנין ירושלים דלע\"ל שיהי' בשמחת עולם לפי שיהי' אחר תשלום הניצוח העליון כשיכבוש לע\"ש דק\"נ שיהופך מרע לטוב וכמ\"ש אז אהפוך אל עמים<sup data-n=\"11135\">417</sup> כו' ורוח הטומאה יעב[י]ר<sup data-n=\"11136\">418</sup> לגמרי מן הארץ ויהי' נשלם הניצוח לאכפייא לסט\"א [ו]לאהפכא חשוכא לנהורא<sup data-n=\"11137\">419</sup> לגמרי, שאע\"פ שדבר קטן הוא כל יניקות הקליפות וגם מה שיבורר מהם. אך ניצוח הרצון הזה עולה למעלה מכל התענוגי' ש[ב]כל הון יקר כו', וע\"כ [בזבוז כל אוצרות העליוני' שהוא מה שמגלה עמוקו' מני חשך כנ\"ל ועיקר הכוונה הי' בתחלה בזה כדי שתבנה<sup data-n=\"11138\">420</sup> ] ירושלים שיהי'<sup data-n=\"11139\">421</sup> במדת הניצוח שיהי' בשמחת עולם דוקא, והוא כמ\"ש שיעשה סעודה לצדיקים מלויתן<sup data-n=\"11140\">422</sup> כו' וישמחו ביין המשומר מוי\"ב<sup data-n=\"11141\">423</sup> כו', וז\"ש והנצח זו בנין ירושלים וד\"ל.\n<b>אך</b> עדיין אינו מובן למה בנין ירושלים יהי' דוקא ע\"י מדת [הניצוח שהרי עיקר מדת] הנצחון אינו רק להשפיל למנגד ולהכניעו כנ\"ל וא\"ז שייך לבנין ירושלים דוקא (ואם מפני שלא נתמלא' צור כו', א\"כ הרי ממילא יהי' זה שבמפלת הסט\"א המנגד יהי' בנין ירושלים ואיך אמר והנצח זו בנין ירושלים דמשמע שזהו עיקר הנצחון דוקא). אך הנה באמת יש בזה ב' דברים, הא' ענין הכנעת והשפלת המנגד לאכפיי' לס\"א כנ\"ל. והב' הוא להוציא ממנ[ו] מה שבלע וגדל<sup data-n=\"11142\">424</sup> מן הקדושה הפנימי' ביותר והוא מה שעיקר חיותו הוא רק מחורבנה של ירושלים, ומזה בא עיקר הנצחון הגדול ש[י]בזבז כל האוצרות לבנות בנין ירושלים, אבל אם לא הי' מושל [בירושלים] ולא היו ישראל מובלעים בפיו כמו כי נבלע ישראל<sup data-n=\"11143\">425</sup> כו' לא הי' ניצוח זה כ\"כ, כי באמת כל הגוים כאין נגדו<sup data-n=\"11144\">426</sup> כו' רק מה שהנחיל עליון גוים<sup data-n=\"11145\">427</sup> בהפרידו בנ\"א והציב גבולות עמים הוא רק בשביל ישראל שהוא הפנ[ימ]י' וירושלים ובהמ\"ק, והי' להיפך שינחלו בירושלים <span data-k=\"pg\">שלג</span> ּ עיר קדשו ויהי' הטפל עיקר ועיקר טפל כו'. ולזאת יגדל הניצוח ביותר לבנות בנין ירושלים דוקא לעמוד הדבר",[["11134","416","<b>שהוכרח</b>: חט: ליתא."],["11135","417","<b>אז אהפוך אל עמים</b>: צפני' ג, ט."],["11136","418","<b>ורוח הטומאה יעב[י]ר</b>: זכרי' יג, ב."],["11137","419","<b>[ו]לאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["11138","420","<b>[בזבוז. . שתבנה]</b>: ד: ובתו\"ח כאן: בנין."],["11139","421","<b>שיהי'</b>: דח: ליתא."],["11140","422","<b>שיעשה סעודה לצדיקים מלויתן</b>: נסמן לעיל פ' שמות ו, ד."],["11141","423","<b>ביין המשומר מוי\"ב</b>: נסמן לעיל קסא, א."],["11142","424","<b>וגדל</b>: חט: וגזל."],["11143","425","<b>כי נבלע ישראל</b>: הושע ח, ז-ח."],["11144","426","<b>כל הגוים כאין נגדו</b>: ישעי' מ, יז."],["11145","427","<b>שהנחיל עליון גוים</b>: האזינו לב, ח."]]],[2300540693,"במקומו, כי אין השכינה שורה רק בישראל ובירושלים כמו שהי' מקודם. וזהו כמשל בן המלך ואמו שנשבו ביחד ביד אויב אע\"פ שסיבת השבי' הי' מצד הבן שלא הלך בדרכי אביו וציוה לאויב להשתעבד בו, עכ\"ז י[כ]מרו רחמי האב על הבן ואמו שגרשם ויבא בנצחון גדול ליקחם מיד האויב אם הוא יעמוד לנגדו דוקא כנ\"ל וזהו ויגער ה' בך הבוחר בירושלים דוקא.\n<b>והנה</b> עם כל הנ\"ל יובן מ\"ש צדקת פרזונו פזרונו<sup data-n=\"11146\">428</sup> שפזרן<sup data-n=\"11147\">429</sup> לבין אוה\"ע, דהנה [בזמן] ב\"ר וב\"ש חטאו ישראל בע\"ז וג\"ע וש\"ד ושאר עבירות חמורות ופגמו הרבה מאד למעלה באו\"כ דע\"ס דקדושה שהוא ש[ם] הוי' בכלל, כידוע דיו\"ד דש' הוי' הוא בחכ'<sup data-n=\"11148\">430</sup> (וקש\"י בכתר<sup data-n=\"11149\">431</sup>, וזהו הפושעים בי בגופא דמלכא<sup data-n=\"11150\">432</sup> שהוא הפגם באור הכתר כמו קרקפתא דלא מנח תפילין<sup data-n=\"11151\">433</sup> כו' שנק' פושעי ישראל בגופן כו') (וכה\"ג בכל בחי' מקיף מאד<sup data-n=\"11152\">434</sup> דאור הכתר שהוא בראש בל\"ת<sup data-n=\"11153\">435</sup> כמו גילוח הזקן ולבושי' דשעטנז וכלאים כו'). וכמ\"כ בעריות החמורות<sup data-n=\"11154\">436</sup> [ו]ע\"ז וש\"ד וכה\"ג, וכן מחלל שבת<sup data-n=\"11155\">437</sup> בפרהסיא שגם [ה]שבת נק' קדש<sup data-n=\"11156\">438</sup> שהוא ביו\"ד דשם הוי' עיקר הפגם הוא בכתר שבחו\"ב<sup data-n=\"11157\">439</sup> שנק' אין כמ\"ש והחכ' מאין תמצא<sup data-n=\"11158\">440</sup> כו'. אבל ביטול ת\"ת<sup data-n=\"11159\">441</sup> ומבזה ת\"ח שהוא הפגם ביו\"ד דחכמה, וכן בביטול המילה כו' וביטול ק\"ש<sup data-n=\"11160\">442</sup> הוא הפגם ביו\"ד וה\"א<sup data-n=\"11161\">443</sup>, וכן בציצית במקיף דחכמה, וכמה מצות שהן במדות ונק' גופי תורה כו' וכללותן הן בו\"ה שז\"ש והנגלות לנו<sup data-n=\"11162\">445</sup> כו' שכולל רמ\"ח מ\"ע<sup data-n=\"11163\">444</sup> ושרש השס\"ה ל\"ת<sup data-n=\"11164\">446</sup> בי\"ה<sup data-n=\"11165\">447</sup> כידוע, והפגם במצות צדקה הוא בה\"א אחרונה<sup data-n=\"11166\">448</sup>, וכן בהעדר קעומ\"ש כידוע. והנה לא הי' אפשר להיות התיקון לפגמים רבים הללו שפגמו בשם הוי' דע\"ס דאצי' שנק' חילול שם קדשו כו' כ\"א ע\"י המשכות מלמעלה משם הוי', והוא ממקום [ומ]מדריגה עליונה ועמוקה ביותר כדי שמשם ימולא ויתוקן כל הפגמים והחסרו[נות] הנ\"ל. וז\"ש ממעמקים קראתיך ה' [פי'] מעומק כל [העומקי'] שהוא מקור כל העומקים דע\"ס כו' משם קראתיך למלאות הפגם דשם הוי' כו' וד\"ל.\n<b>והענין</b> יובן עד\"מ הידוע במעיינות ומי<sup data-n=\"11167\">449</sup> בארות שנסתמו בעפר במקורם ואינן נובעין בו<sup data-n=\"11168\">450</sup>, חופרי' בעומק יותר במקורם שמשם יש כח להחזיר הנביעה גם במקום הסתימה",[["11146","428","<b>פזרונו</b>: ד: ליתא. — ראה לעיל על יד הערה 3."],["11147","429","<b>שפזרן</b>: חט: ניתוסף (ל)ישראל. ד: כבפנים."],["11148","430","<b>דיו\"ד. . בחכ'</b>: נסמן לעיל פ' שמות יב, ד."],["11149","431","<b>וקש\"י בכתר</b>: נסמן לעיל פ' בא קכב, א."],["11150","432","<b>הפושעים בי בגופא דמלכא</b>: נסמן לעיל פ' שמות ו, ב. לקמן פ' תצוה שמג, ב הערה 849."],["11151","433","<b>קרקפתא דלא מנח תפילין</b>: ר\"ה יז, א."],["11152","434","<b>מאד</b>: דחט: ליתא."],["11153","435","<b>בל\"ת</b>: שם: ליתא."],["11154","436","<b>בעריות החמורות</b>: ט: בעבירות החמורות כעריות."],["11155","437","<b>מחלל שבת. . ביו\"ד</b>: ראה גם לקמן פ' ויקהל תכ, ב. וש\"נ."],["11156","438","<b>[ה]שבת נק' קדש</b>: נסמן לעיל פ' בא קג, ב."],["11157","439","<b>שבחו\"ב</b>: חט: שבחכ'."],["11158","440","<b>תמצא</b>: חט: ליתא."],["11159","441","<b>ביטול ת\"ת. . ביו\"ד דחכמה</b>: ראה גם הנסמן לעיל קנב, ד."],["11160","442","<b>וביטול ק\"ש. . ביו\"ד</b>: ראה סדר ק\"ש עהמ\"ט בסידור אדה\"ז."],["11161","443","<b>וביטול ק\"ש. . וה\"א</b>: ראה גם בסמוך (פיסקא וביאור הענין). מאמרי אדה\"א שמות ח\"ב ע' תפג. דברים ח\"ג ע' א'פה. מכתב לר\"י פייגין י\"ט אייר תרצ\"ט (נדפס ברשימות לפ' עקב חוב' קנח)."],["11162","445","<b>והנגלות לנו</b>: נצבים כט, כח."],["11163","444","<b>בו\"ה. . רמ\"ח מ\"ע</b>: נסמן לעיל פ' בא קיד, א הערה 152."],["11164","446","<b>רמ\"ח מ\"ע. . השס\"ה ל\"ת</b>: מכות כג, סע\"ב."],["11165","447","<b>השס\"ה ל\"ת בי\"ה</b>: נסמן לעיל פ' בא קיד, א."],["11166","448","<b>צדקה הוא בה\"א אחרונה</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תפג. דברים ח\"ג ע' א'פה."],["11167","449","<b>ומי</b>: חט: או."],["11168","450","<b>בו</b>: שם: ליתא."]]],[2300540705,"לדחות העפר המכסה ולשטוף כל הסתימה (כמו וישב יצחק ויחפור את בארות דאברהם שסתמום פלשתים כו' לפי שחפר בעמקות הב[א]ר בעומק הארץ יותר דארעא חלחולי מחלחלא<sup data-n=\"11169\">451</sup> כו', ויש מעיינות סתומים בהעלם עומק הארץ עד שמגיע לתהום ונק' מעיינות תהום רבה<sup data-n=\"11170\">452</sup> שפקעו<sup data-n=\"11171\">453</sup> בזמן המבול, שהוא מקור כל המעיינו' ההולכי' בתחלה<sup data-n=\"11172\">454</sup> ע\"פ הארץ וזהו שחפר יצחק ויצאו<sup data-n=\"11173\">455</sup> מ\"ח כו' בבחי' היראה והתשובה שהוא למעלה ממעלת אהבה דאברהם כנ\"ל). וכ\"ש בנהר שנמשך מן המעיין שכאשר מתקלקל הילוכו מפני מקומות הנסתמים בעפר הנובע<sup data-n=\"11174\">456</sup>, שחופרי' המעיין שלו דוקא בעומק יותר שיומשך משם הנביעה בכח ותוקף גדול ביותר <span data-k=\"pg\">668</span> ּ ואז יתמלא הנהר בגובה ורוחב ומתמלא [על] כל גדותיו עד שיפתח וישטף לכל המקומות הסתומים והמקולקלים שבנהר ולא יחזור להסתם עוד בשום סיבה. וכל שחופרין במעיין בעומק ביותר, יותר יהי' הילוך הנהר בתגבורת חזקה ובריבוי גדול וכמאמר דנהרא מכיפי' מבריך<sup data-n=\"11175\">457</sup> (וכן מן הנהר אל הבריכות שמקבלים ממנו אם נפסקו הבריכות מן הנהר ע\"י הסתימה כנ\"ל בענין<sup data-n=\"11176\">458</sup> במעיין, מתמלא ע\"י הגדלת הנהר במקורו במעיין כנ\"ל). וכך יובן בנמשל למעלה [ב]מ\"ש ממעמקים קראתיך הוי' שאומרים בעי\"ת<sup data-n=\"11177\">459</sup> דוקא שהוא לעורר ההמשכה ממקור העומקים של המעיינות העליונים כמ\"ש כי עמך מקו\"ח<sup data-n=\"11178\">460</sup> כו' וכתיב באר מ\"ח ונוזלים מן לבנון<sup data-n=\"11179\">461</sup> כו', וע\"י הפגמים הגדולים שפגמו נסתמו אורות [ה]עליונים ואין לזה תיקון כ\"א מעומק כל המעיינות ונהרות שלמעלה מן ההשתל' דע\"ס דאצי' ובי\"ע, שמשם דוקא ממילא יתוקן כל הפג[מי]ם ויתגלה<sup data-n=\"11180\">462</sup> כל חסרון אור שבכל ההשתל' דאבי\"ע והוא ע\"י שיעורר רוח ממרום העליון ביותר שז\"ש ממעמקים דוקא קראתיך כו' כנ\"ל וד\"ל.\n<b>וביאור</b> הענין הזה<sup data-n=\"11181\">463</sup> מבואר למעלה בענין מגלה עמוקות מני חשך, שיש עומק אחר עומק עד עומקא דכולא שהוא בחי' עולם הא\"ס עצמו והוא בחי' [ה]עלי' באור העלם העצמי' שקודם הצמצום בקו\"ח להאציל ע\"ס ולברוא כו', שנק' ע\"ס הגנוז[ו]' בעצמות המאציל שהם בכלל בחי' העומקי' דע\"ס דאבי\"ע. אמנם בד\"פ<sup data-n=\"11182\">464</sup> הנה יש עומק למעלה מעומק גם [ב]ע\"ס דאצי', והיינו בחי' ההעלם דאור הכתר שנק' אין לגבי גילוי",[["11169","451","<b>דארעא חלחולי מחלחלא</b>: חגיגה כב, א."],["11170","452","<b>מעיינות תהום רבה</b>: נח ז, יא."],["11171","453","<b>שפקעו</b>: חט: שנבקעו."],["11172","454","<b>בתחלה</b>: שם: בנחלים."],["11173","455","<b>ויצאו</b>: שם: ומצא."],["11174","456","<b>הנובע</b>: שם: בגובה."],["11175","457","<b>דנהרא מכיפי' מבריך</b>: שבת סה, ב. ראה לקו\"ת שה\"ש לט, א. אמ\"ב שער התפילין קכא, סע\"ג."],["11176","458","<b>בענין</b>: חט: ליתא."],["11177","459","<b>ממעמקים. . בעי\"ת</b>: ראה סידור אדה\"ז במקומו (לפני ברכו). מאמרי אדה\"ז תקס\"ה כאן (ע' תתקצו). פרשיות התורה ח\"ב ע' תתמא ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ע' תתסט. וש\"נ. ח\"ד ע' א'שעז. נ\"ך ע' רי."],["11178","460","<b>כי עמך מקו\"ח</b>: תהלים לו, י."],["11179","461","<b>באר מ\"ח ונוזלים מן לבנון</b>: שה\"ש ד, טו."],["11180","462","<b>ויתגלה</b>: דח: וימולא."],["11181","463","<b>הזה</b>: שם: הנה."],["11182","464","<b>בד\"פ</b>: ח: בדרך פרט."]]],[2300540717,"דאור החכ' שתמצא מאין ליש מבחי' אור הכתר, וכן [ה]העלם דאור החכ' שנק' אין לגבי בינה כידוע, וכן מבינה למדות כו' כידוע. וזהו כמשל הנ\"ל בג' דברים בריכה ונהר ומעיין שהמעיין הוא בחי' ההעלם לגבי הנהר שזהו בחי' מעיין דחכמה שנובע בהעלם מאין ליש בהשגה דבינה שנק' יש כידוע, וכמשל שחופרים בעומק המעיין נתמלא הנהר לכל גדותיו לתקן המקומות המקולקלים שבה הסתומים. כך הוא בבחי' הפגמים שנעשים בה' עילאה דבינה (כמו בביטול ק\"ש וכה\"ג) כנ\"ל, יפתחו להאיר באמצעות החפירה בעומק המעיין דחכמה יותר שהוא בבחי' ח\"ס חכ' שבכתר שנק' שכל הנעלם מכל רעיון<sup data-n=\"11183\">465</sup>, כידוע שקודם ביאת השפע מאור החכמה לבינה שנק' מעיין סתום או מעיין חתום משא\"כ בגילוי אור דחכ' שנמשך לבינה נק' מעיין הגלוי כו', ונק' עומק הב'<sup data-n=\"11184\">466</sup> שממנו נעשה ממילא עומק בינה הנק' נהר<sup data-n=\"11185\">467</sup> כמ\"ש ונהר יוצא מעדן<sup data-n=\"11186\">468</sup> כו' ומחמת ריבוי האור העומק דחכ' בבינה שנק' נהר נתמלא כל חסרון ופגם שנעשה בבינה ממילא כנ\"ל. וכמו במצות ת\"ת או שב\"ת [ש]הוא בעומק דחכ' כנ\"ל ותיקון הפגם שבבינה הוא<sup data-n=\"11187\">469</sup> בתשו' מעומקא דאין דחכ' כמשי\"ת, וכשהפגם נעשה גם בחכ'<sup data-n=\"11188\">470</sup> כמו בחילול שבת ובביטול ת\"ת ובבזיון ת\"ח וכאפיקורסי' [כו'], יתוקן מעולם העליון ממנו והוא מעומק דחכ' שבכתר<sup data-n=\"11189\">471</sup> ונק' עכה\"ע<sup data-n=\"11190\">472</sup> [ד]אפי' אור צח אוכם הוא. וכמו בדוגמא שאמר יען ניגש העם בפיו ובשפתיו כבדוני ולבם רחוק<sup data-n=\"11191\">473</sup> ממני כו' והוא מצות אנשים מלומדה<sup data-n=\"11192\">474</sup> בלי כוונה כלל, שא\"ז רק בחי' אחוריים שנק' עורף [כמו] כי פנו <span data-k=\"pg\">שלד</span> ּ אלי עורף<sup data-n=\"11193\">475</sup> ולא פנים, ע\"כ יחזור גם הוא בחי' הפנים העליונים והוא בחי' ח\"ס הנ\"ל שז\"ש ואבדה חכמת חכמיו<sup data-n=\"11194\">476</sup> ובינת נבונים<sup data-n=\"11195\">477</sup> תס[ת]תר, מפני שנסתם ונפגם מעומק<sup data-n=\"11196\">478</sup> החכ' וכו'<sup data-n=\"11197\">479</sup> נבונים הנק' עומק דחו\"ב [ד]י\"ה שבנש\"י שזהו עומק חו\"ג<sup data-n=\"11198\">480</sup> שבלב ע\"כ אז אמר ואנכי הסתר אסתיר<sup data-n=\"11199\">481</sup> פני ביום ההוא כו', שזהו בזמן הגלות דכנ\"י בבחי' הסתר פנים לפי שהן בבחי' אחוריים כמ\"ש ניגש העם<sup data-n=\"11200\">482</sup> בפיו כו' מן השפה ולחוץ כו' ולבם רחוק לגמרי מן המצות רק מלומדה מאבותיהם כמו בגלות האחרון ועכ\"ז<sup data-n=\"11201\">*483</sup> והי' לאכול ומצאוהו רעות רבות וצרות ואמר על כי אין<sup data-n=\"11202\">483</sup> כו'. אך ע\"י תשובה האמיתי' מעומקא דלבא כמ\"ש ממעמקים קראתיך כו' כמו בעי\"ת נעשה החזרת פב\"פ כמ\"ש השיבנו<sup data-n=\"11203\">484</sup> כו' (וכמשי\"ת). וכמו\"כ ע\"י העומק דבינה נתמלא כל חיסרון ופגם שבמדות [העליוני' שהוא הוי\"ו שזהו כמשל הבריכה שנמשכה מן הנהר שנפסק כו', וכמו שבעומק בינה שבלב יתוקן",[["11183","465","<b>שכל הנעלם מכל רעיון</b>: נסמן לעיל פ' שמות מז, ג."],["11184","466","<b>הב'</b>: חט: חכ'. ד: כבפנים."],["11185","467","<b>בינה הנק' נהר</b>: ראה זהר (אדרא דמשכנא) משפטים קכג, ב."],["11186","468","<b>ונהר יוצא מעדן</b>: בראשית ב, י. ראה גם לעיל קמא, ב."],["11187","469","<b>הוא</b>: דחט: או."],["11188","470","<b>בחכ'</b>: דח: בח\"ס. ט: כבפנים."],["11189","471","<b>דחכ' שבכתר</b>: ד: דח\"ס דכתר שבכתר. ח: דכתר שבחכ'. ט: דכשב\"כ."],["11190","472","<b>עכה\"ע</b>: עילת כל העילות. חט: עה\"ע."],["11191","473","<b>יען ניגש. . ולבם </b>[ט: ולבו]<b> רחוק</b>: נסמן לעיל רג, ד."],["11192","474","<b>מצות אנשים מלומדה</b>: המשך הכתוב יען כי נגש (ישעי' כט, יג)."],["11193","475","<b>כי פנו אלי עורף</b>: ירמי' ב, כז."],["11194","476","<b>ואבדה חכמת חכמיו</b>: ישעי' שם, יד."],["11195","477","<b>נבונים</b>: דח: נבוני'."],["11196","478","<b>מעומק</b>: חט: מעיינות."],["11197","479","<b>וכו'</b>: שם: ובינת."],["11198","480","<b>חו\"ג</b>: שם: חו\"ב."],["11199","481","<b>ואנכי הסתר אסתיר</b>: וילך לא, יח."],["11200","482","<b>ניגש העם</b>: חט: ליתא."],["11201","*483","<b>ועכ\"ז</b>: ט: וע\"כ."],["11202","483","<b>והי' לאכול. . כי אין</b>: וילך שם, יז [בדילוג]."],["11203","484","<b>השיבנו</b>: איכה ה, כא."]]],[2300540729,"הפגם במדות] דאוי\"ר כו', וכן מעומק דמדות יתוקן הפגם שבמחדו\"מ שזהו בחי' בי\"ע<sup data-n=\"11204\">485</sup> למעלה וכידוע וד\"ל. אך כאשר נפגם גם אור הכתר עצמו שלמעלה גם מח\"ס הנ\"ל (וכמו הפושעי' בי ממש בגופא דמלכא שנק' פושעים<sup data-n=\"11205\">486</sup> בגופם כנ\"ל), אין תיקון רק בעומק העליון גם ממנו והוא מ\"ם דממעמקים שלמעלה מעומק דכתר שהוא לתקן הפגם שברצון עצמו כמו בפר\"ע גמור כמו והתברך בלבבו<sup data-n=\"11206\">487</sup> כו' בשרירות לבי אלך כו') שהוא בעצמות א\"ס שנק' מקור כל עומק דמעיינות העליוני' שנק' סדכ\"ס דלמתב\"כ. וז\"ש אנכי אנכי<sup data-n=\"11207\">488</sup> הוא מוחה פשעיך למעני ממש וב\"פ אנכי<sup data-n=\"11208\">489</sup> היינו למעלה גם מאנכי דכ\"ע<sup data-n=\"11209\">490</sup> כו' והיינו ע\"י התשובה ממעמקי' כמשי\"ת וד\"ל.\n<b>ואמנם</b> הנה עדיין י\"ל למה מבחי' ההעלם דעומקי' [הנ\"ל] דוקא יתוקן כל פגם וימולא כל חסרון דאו\"כ בעשי'<sup data-n=\"11210\">491</sup> בכלל ובפ[רט] כנ\"ל. אך הענין הוא לפי שכאשר בחי' ההעלם דעומקים הנ\"ל באים לבחי' גילוי הרי נעשה כל בחי' חושך והעלם דחשך סתרו בחי' גילוי אור [שזהו גם בחי' סדכ\"ס עצמו בא לגילוי למטה כמו] למעלה כנ\"ל בענין מגלה עמוקות מני חשך, שהוא בחי' היריד[ה] דאו\"י היפוך דאו\"ח ע\"כ גם כל בחי' פגם וחסרון שנעשה ע\"י העוונות למעלה שנק' חשך התחתון יאיר וכמ\"ש וגם חשך לא יחשיך ממך<sup data-n=\"11211\">492</sup> דקמי' כחשיכה כאורה ממש בשוה ממש כנ\"ל, וע\"כ מזה יכול להיות היפוך הרע עצמו לטוב [כ]זדונות שנעשו הן עצמן זכיות<sup data-n=\"11212\">493</sup> ע\"י המשכת י\"ג מדה\"ר שנושא עון ועובר ע\"פ<sup data-n=\"11213\">494</sup> כו' וכמ\"ש אם יהיו חטאיכם כשנים<sup data-n=\"11214\">495</sup> כו' לפי שיעביר כל לכלוך עד שיטהר גם לטמא כמ\"ש וזרקתי עליכם מים טהורים<sup data-n=\"11215\">496</sup> כו' (כמאן דמסתחי בימא רבא<sup data-n=\"11216\">497</sup> כו'). ואמנם אין כח זה רק בעומקא דכולא שהוא עצמות אוא\"ס שלפני הצמצום הראשון כנ\"ל כמ\"ש מי יתן טהור מטמא לא אחד<sup data-n=\"11217\">498</sup> ממש כנ\"ל<sup data-n=\"11218\">499</sup>, והוא בנעילה דיוכ\"פ שנמשך סליחת העוונות בפ\"מ למטה כמ\"ש לפני הוי' תטהרו<sup data-n=\"11219\">500</sup> לפני הוי' ממש שזהו ממעמקים (כמשי\"ת). אך הנה מהיכן יהי' [התעוררות] ההמשכה ממקורא דכולא שלמעלה מכל עומקים די\"ס כנ\"ל להפוך גם החושך<sup data-n=\"11220\">501</sup> לאור כנ\"ל, הנה ז\"ש ממעמקים קראתיך הוי' מצד אתעדל\"ת שקראתיך בתשובה שלימה מלמטה למעלה ג\"כ מעומק תעלומות נקודת הלב שנק' עומק[א] דעומק[א] שלמעלה גם מעומק דרצון ועומק <span data-k=\"pg\">670</span> ּ דחו\"ב כו', והוא מ\"ם דממעמקים כו' שהוא בחי' יחידה שבנפש (שהוא מ\"ם דצלם כו'",[["11204","485","<b>שבמחדו\"מ. . בי\"ע</b>: נסמן לעיל קמד, ב."],["11205","486","<b>פושעים</b>: דח: פושעי ישראל. ט: כבפנים."],["11206","487","<b>והתברך בלבבו</b>: נצבים כט, יח."],["11207","488","<b>אנכי אנכי</b>: ישעי' מג, כה."],["11208","489","<b>וב\"פ אנכי</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'פז. ע' א'א. ויקרא ח\"ב ע' תקל."],["11209","490","<b>דכ\"ע</b>: ט: דכתר עליון."],["11210","491","<b>בעשי'</b>: דחט: בע\"ס."],["11211","492","<b>וגם חשך לא יחשיך ממך</b>: נסמן לעיל פ' וארא סד, א."],["11212","493","<b>[כ]זדונות. . זכיות</b>: נסמן לעיל פ' בא קכג, ג."],["11213","494","<b>שנושא עון ועובר ע\"פ</b>: מיכה ז, יח."],["11214","495","<b>אם יהיו חטאיכם כשנים</b>: ישעי' א, יח."],["11215","496","<b>וזרקתי עליכם מים טהורים</b>: יחזקאל לו, כה."],["11216","497","<b>כמאן דמסתחי בימא רבא</b>: נסמן לעיל ריד, ד."],["11217","498","<b>מי יתן טהור מטמא לא אחד</b>: איוב יד, ד."],["11218","499","<b>כנ\"ל</b>: דחט: כו'."],["11219","500","<b>לפני הוי' תטהרו</b>: אחרי טז, ל."],["11220","501","<b>גם החושך</b>: דחט: כל חושך."]]],[2300540741,"שזהו ענין הבכי' בעשי\"ת בכאו\"א<sup data-n=\"11221\">502</sup> אפי' בקשב\"ק<sup data-n=\"11222\">503</sup> כידוע בענין שכל מי שאינו בוכה<sup data-n=\"11223\">504</sup> בעי\"ת אין נשמתו שלימה).\n<b>והענין</b> הוא כידוע שיש בתשובה שבלב כמה מדריגות זו למעלה מזו כמו תשובה דנר\"נ ומחדו\"מ<sup data-n=\"11224\">505</sup> עד בחי' מקיף דחי' ויחידה כו', וזהו ענין תשובה תשוב ה'<sup data-n=\"11225\">506</sup> שנק' תשו\"ת<sup data-n=\"11226\">507</sup> בתיקון הפגם בה' אחרונה בחי' מל'<sup data-n=\"11227\">508</sup> והוא בפר\"ע שישוב ויקבל עומ\"ש שלימה ביראה ופחד אלקי', [כמו] בר\"ה שירא מיוה\"ד<sup data-n=\"11228\">509</sup> והוא באמרו י\"פ דמלכיות שתמליכוני עליכם<sup data-n=\"11229\">510</sup> כו', ובזה נכלל התיקון דתשובה במחדו\"מ בפו\"מ [כמו יעזוב רשע דרכו<sup data-n=\"11230\">512</sup> ואיש און מחשבותיו, והיינו בוידוי שאו' אשמנו כו' עד תעבנו תעינו כו' מעומק הלב בלב נשבר מאד ובבכי' ולעורר ר\"ר על נפשו שנדחה ע\"י עונות שלו בפו\"מ וזהו מן המיצר<sup data-n=\"11231\">513</sup> קראתי<sup data-n=\"11232\">511</sup> ] מעומק תחתון [ש]זהו תשובה דנפש החוטאת בפו\"מ כו', ואח\"כ יש עומק עליון יותר בבחי' תשובה שבלב באוי\"ר והוא [בחי' ה]רוח שהרוח תשוב אל [ה]אלקים<sup data-n=\"11233\">514</sup> ונק' עומק הלב, ואח\"כ יש עומק עליון יותר והוא בחי' תשו' דבחי' נשמה דבינה במוח [ש]הוא [עומק] ההשגה האלקי' שנמשך בלב ונק' עומק בינה שבלב כמ\"ש והשבות אל לבבך<sup data-n=\"11234\">515</sup> כו' אחר שישוב הוי\"ו לה' תשוב ה' עילאה דבינה לבחי' עומק החכ' אחר שהוא הראי'<sup data-n=\"11235\">516</sup> שבלב כמ\"ש במ\"א. וזהו תשוב ה' ביו\"ד<sup data-n=\"11236\">*517</sup> שנק' תשו' עילאה<sup data-n=\"11237\">517</sup> כידוע, ואח\"כ גם העומק דחכ' דבחי' אין שבלב ישוב גם הוא למעלה בעומק העליון יותר שהוא עומק נקודת הרצה\"פ שבלב שאין טעם לרצון כלל כו', ואח\"כ תשובה דבחי' יחידה שלמעלה גם מהרצון והיינו בעצמות הנפש ממש שיצעק מקירות לבו ממש בעומק דעומק הלב שנק' תעלומות הלב שהוא עומק הלב נשבר ביותר עד שמגיע<sup data-n=\"11238\">518</sup> לחייו ממש כראב\"ד שיצאה נשמתו בבכיה<sup data-n=\"11239\">519</sup> וכה\"ג, וזהו כל שאינו בוכה בעשי\"ת אין נשמתו שלימה כו'. וזהו ענין היו\"ד עומקים בעי\"ת עד עומק כשב\"כ שהוא ביו\"כ בנעילה שאומרים ז\"פ הוי' הוא [ה]אלקים כו', כי הנה ע\"י אתעדל\"ת דוקא בתשו' בנרנח\"י כנ\"ל שזהו רק גילוי ההעלם מע[ומ]\"ת מלמטה למעלה בעומק אחר עומק עד עומק העליון שבהעלם עצמות הנפש ממש שממנו מקור כל רצון טו\"ר<sup data-n=\"11240\">520</sup> כו' כנ\"ל, כך יהי' עי\"ז אתעדל\"ע ג\"כ מלמעלה למטה עז\"א ממעמקים קראתיך מעומק לעומק הע[ליון]",[["11221","502","<b>בכאו\"א</b>: דח: בכל איש מישראל. ט: ניתוסף: מישראל."],["11222","503","<b>בקשב\"ק</b>: שם: בקלי קלים."],["11223","504","<b>שכל מי שאינו בוכה</b>: ראה פע\"ח (שער השופר) שכ\"ו, פ\"ה. מאמרי אדה\"א דברים ח\"א ע' שיט. וש\"נ. תו\"ח וישב ר, ג הערה 35."],["11224","505","<b>תשובה דנר\"נ ומחדו\"מ</b>: ראה גם לקו\"ת בלק עג, ב ואילך. מאמרי אדה\"א במדבר ח\"ד ס\"ע א'תקצה ואילך ובהנסמן בריש המאמר שם."],["11225","506","<b>תשובה תשוב ה'</b>: ראה זהר (רע\"מ) נשא קכב, א."],["11226","507","<b>תשו\"ת</b>: שם קכג, א."],["11227","508","<b>בה' אחרונה בחי' מל'</b>: נסמן לעיל קנח, א."],["11228","509","<b>מיוה\"ד</b>: חט: מיום הדין."],["11229","510","<b>י\"פ דמלכיות שתמליכוני עליכם</b>: ראה גם לעיל פ' בא צז, א. וש\"נ."],["11230","512","<b>יעזוב רשע דרכו</b>: ישעי' נה, ז."],["11231","513","<b>מן המיצר קראתי</b>: תהלים קיח, ה."],["11232","511","<b>כמו. . קראתי</b>: בתו\"ח כאן: כו' והוא."],["11233","514","<b>שהרוח תשוב אל [ה]אלקים</b>: קהלת יב, ז."],["11234","515","<b>והשבות אל לבבך</b>: ואתחנן ד, לט."],["11235","516","<b>החכ'. . הראי'</b>: נסמן לעיל פ' שמות כז, ג."],["11236","*517","<b>תשוב ה' ביו\"ד</b>: ראה גם לקמן פ' תצוה שסח, ג. מאמרי אדה\"א ויקרא ח\"א ע' פט. וש\"נ."],["11237","517","<b>תשו' עילאה</b>: נסמן לעיל בהערה 507."],["11238","518","<b>שמגיע</b>: חט: שנוגע."],["11239","519","<b>כראב\"ד. . בבכיה</b>: נסמן לעיל פ' שמות מ, ד."],["11240","520","<b>טו\"ר</b>: חט: טוב."]]],[2300540753,"דכשב\"כ<sup data-n=\"11241\">521</sup> כו', דהיינו שיגלה כל העומקי' העליוני' מן ההעלם הראשון שנק' סדכ\"ס שלמעלה גם מבחי' רצה\"ע הפשוט הנק' ר[ע]דכ\"ר<sup data-n=\"11242\">522</sup> והוא מ\"ם דממעמקי' (כמו בחי' יחידה שבאדם למטה), שמזה<sup data-n=\"11243\">523</sup> ניתקן כל פגם וחסרון בי\"ג מדה\"ר שנמשך מר[ע]דכ\"ר ואתגלי' במצחא כו' כמ\"ש כי ביום הזה יכפר<sup data-n=\"11244\">524</sup> סתם למעלה מש[ם] הוי' היינו לכפר על ש[ם] הוי' שימולא כל חסרון כנ\"ל. והסיבה להתעוררות התגלות עומקים הנ\"ל בא מאתעדל\"ת דוקא כמ\"ש ממעמקי' קראתיך<sup data-n=\"11245\">525</sup> הוי' ממעמקים מעומק דעומק נקודת הלב כמ\"ש לך אמר לבי<sup data-n=\"11246\">526</sup> בקשו פני בפנימיות [הלב ו]ממילא את פניך הוי' דוקא אבקש שי[ת]גלה מן ההעלם כו'. ואמנם באמת יש כח בעצמו' אוא\"ס ב\"ה שנק' עומקא דכולא שיתעוררו כנ\"י בתשו' שלימה שיקראו מעומק הלב והוא ענין להחזיר פב\"פ אעפ\"י שהן בבחי' חיצוני' ואחוריים כנ\"ל, והיינו בעי\"ת שנתעורר כאו\"א בתשובה שלימה ויצעק ויבכה מנקודת<sup data-n=\"11247\">527</sup> הלב כו' [וכמו השיבנו ה' אליך ונשובה ממילא פב\"פ כו', וזהו ע\"י שנמשך מעומקא דכולא מלמעלה למטה כמו] וכמ\"ש<sup data-n=\"11248\">528</sup> ישוב ירחמנו ישוב מלמעלה <span data-k=\"pg\">שלה</span> ּ למטה ואי' בזהר מאן אתר<sup data-n=\"11249\">529</sup> מההוא ע\"ס<sup data-n=\"11250\">530</sup> שנק' סדכ\"ס כו', שזהו מ\"ש בהמצאו קראוהו בהיותו קרוב<sup data-n=\"11251\">531</sup> כידוע, וע\"ז אמר ממעמקים קראתיך להיות בגילוי למטה כמו למעלה ממש ואז יוכלו לשוב בתשובה שלימה דוקא ממקור כל העומקים דכח\"ב כו', [ו]כמו כי או\"א עזבוני<sup data-n=\"11252\">532</sup> שהן פנימי' או\"א דאצי' מקור נש\"י והוי' יאספני מרעדכ\"ר שמשם מקור כל רצון טוב כו'. וזהו ענין כי הוי' הוא האלקי'<sup data-n=\"11253\">533</sup> שזהו עלי' דחו\"ב בכתר כ[מ]\"ש אם עוונות תשמר י\"ה<sup data-n=\"11254\">534</sup> אדנ\"י מי יעמוד שהוא שם אד' שבכתר כו', והן ז' עליות מהוי' לאלקי'<sup data-n=\"11255\">535</sup> העליון עד הכתר שבחכ'<sup data-n=\"11256\">536</sup> ומזה נמשך ז' ירידות מהוי' לאלקי' [ש]למטה להמתיק כל הדינין למלאות כל חסרון ופגם וכמ\"ש לפני הוי' תטהרו עד שגם הטמא יטהר והרחוק נעשה קרוב כנ\"ל וד\"ל.\n<b>וזהו</b> צדקה עשה ה' שפזרן בין אוה\"ע כו', כי הנה הפיזור שלהם בין אוה\"ע כו'<sup data-n=\"11257\">537</sup> היינו מה שעי\"ז הן בתכלית השפלות ותכלית המיצר לבין העמים, לפי שהן [מ]פוזרים בארצות לא להם בשעבוד הגלות והצרות ואינם נחשבים לעם בפ\"ע, ומאחר שנדחו בד' כנפות הארץ כמ\"ש בד' רוחות",[["11241","521","<b>דכשב\"כ</b>: שם: דכח\"ב."],["11242","522","<b>ר[ע]דכ\"ר</b>: נסמן לעיל פ' שמות ה, ג."],["11243","523","<b>שמזה</b>: שם: שממילא."],["11244","524","<b>כי ביום הזה יכפר</b>: אחרי טז, ל."],["11245","525","<b>כמ\"ש ממעמקי' קראתיך</b>: חט: במה שקראתיך."],["11246","526","<b>לך אמר לבי</b>: תהלים כז, ח."],["11247","527","<b>מנקודת</b>: חט: מקירת."],["11248","528","<b>וכמ\"ש</b>: שם: ליתא."],["11249","529","<b>ישוב ירחמנו. . מאן אתר</b>: נסמן לעיל קעז, ב."],["11250","530","<b>ע\"ס</b>: ט: עתיקא סתימאה."],["11251","531","<b>בהמצאו קראוהו בהיותו קרוב</b>: ישעי' נה, ו."],["11252","532","<b>כי או\"א עזבוני</b>: תהלים כז, י."],["11253","533","<b>כי הוי' הוא האלקי'</b>: ואתחנן ד, לה. לט."],["11254","534","<b>אם עוונות תשמר י\"ה</b>: תהלים קל, ג. ראה גם מאמרי אדה\"א בראשית ע' קעד. וש\"נ."],["11255","535","<b>ז' עליות מהוי' לאלקי'</b>: ראה פע\"ח (שער יוה\"כ) שכ\"ז, פ\"ה. מאמרי אדה\"א דברים ח\"ג ס\"ע א'סה ואילך. וש\"נ [וכן צ\"ל במאמרי אדה\"א נ\"ך ס\"ע כה בהערה]. תו\"ח בראשית לו, ג ובהערה 34."],["11256","536","<b>שבחכ'</b>: חט: שבכתר."],["11257","537","<b>כו'</b>: בתו\"ח כאן באים עוה\"פ התיבות: כי הנה. . אוה\"ע."]]],[2300540765,"השמים<sup data-n=\"11258\">538</sup> פרשתי אתכם נאום ה'<sup data-n=\"11259\">539</sup> (שאם היו כולם קבוצים יחד נק' עם בפ\"ע ויש להם התגברות כח מצ\"ע כי הם כמו ציור אדם שלם ברמ\"ח אברים שכ\"א עוזר לזה בשיתוף כולם ביחד) (כדוגמא דדור הפלגה שא' ונעשה לנו שם<sup data-n=\"11260\">540</sup> אדם כו' (וע\"כ פזרן<sup data-n=\"11261\">541</sup> כמ\"ש במ\"א), וזהו עיקר מעלת קיבוץ גליות שיהיו כולם יחד ש[י]אור אחדות ה' בהם בציור קומה דאדם שבצלם אלקים, כמו במ\"ת שהיו ת\"ר אלף<sup data-n=\"11262\">542</sup> כ\"א<sup data-n=\"11263\">543</sup> כאיש א' ממש<sup data-n=\"11264\">544</sup> כמ\"ש ויחן ישראל<sup data-n=\"11265\">545</sup> כו'. וזהו עיקר הגלות במה שנתפזרו בכל הארץ ואין לא' חיבור עם זולתו כלל כמו שאין ליד ורגל חיבור עם הראש). וזהו שהמן אמר ישנו עם א'<sup data-n=\"11266\">546</sup> מפוזר ומפורד בין העמים שאינם נחשבים בשם א'<sup data-n=\"11267\">547</sup> וגוי א'<sup data-n=\"11268\">548</sup> כלל, ובאמת פיזור זה לטובתם הוא שהרי גם שהן מפוזרים בין העמים נק' גוי אחד בארץ<sup data-n=\"11269\">549</sup>, לפי שכל העמים מתבררים מכל הפיזור הזה כמו בנוהי דיצחק בגלותא דישמעאל כו' ובנוהי דאברהם<sup data-n=\"11270\">550</sup> כו' שמתחלפי' הגבו' בחסדים כו'. וכך הוא ענין הפיזור בפרט בכל המון עם ישראל תחת כל העמים להיות כ\"א מברר [מ]מדריגתו בהיפוכו המנגדו כאשר יולדים בנים ונימולים ומקיימים תו\"מ תחת השר ההוא כו'. ונמצא שכל הע\"ש נכללים בהם ע\"י הפיזור הזה אבל אם הי' רק תחת שר א' לא היו מתבררים שאר עמים, וכתיב אז אהפוך אל עמים שפה ברורה כו' שהוא בחי' שם מ\"ה דאדם (וכמו שהי' בדור הפלגה שנא' ויהי כל הארץ שפה א' ודברים אחדים שהוא לה\"ק<sup data-n=\"11271\">551</sup> ) וכמ\"ש והייתם לי סגולה<sup data-n=\"11272\">552</sup> מכל העמים דוקא, דהיינו ע\"י בירור שיבוררו מכל העמים בהיותם בפיזור בגלות בין כל העמים כו' וכמ\"ש אז יאמרו בגוים<sup data-n=\"11273\">553</sup> דוקא הגדיל ה' כו' (כמ\"ש במ\"א). וע\"כ נק' גוי א' בארץ דוקא בהיותם בפיזור אוה\"ע שמעלים כולם כא' וכמו שיהי' לע\"ל, וזהו ענין הקיבוץ גליות אחר שהי' בגלות בפיזור דוקא שאז יבורר ע\"י כל הגוים כמ\"ש במשיח ונהרו אליו כל הגוים<sup data-n=\"11274\">554</sup> וכתי' כל העמים תקעו כף כו' כי ה' עליון כו' וד\"ל.\n<b>אך</b> באמת צדקה וחסד גדול הוא זה שפזרן לבין אוה\"ע כו', <span data-k=\"pg\">672</span> ּ כי מחמת הפיזור הזה נעשה בתכלית המיצר והשפלות בעיני כל העמים<sup data-n=\"11275\">555</sup>, ומתוך המיצר והחושך [ה]גדול יצעקו אל ה' בצר",[["11258","538","<b>בד' רוחות השמים</b>: זכרי' ב, י [ושם: כארבע — ראה תענית ג, ב: כארבע בארבע מיבעי' לי'. תו\"ח נח עד, א ובהערה 15]."],["11259","539","<b>נאום ה'</b>: חט: ליתא."],["11260","540","<b>ונעשה לנו שם</b>: נח יא, ד."],["11261","541","<b>וע\"כ פזרן</b>: ראה תו\"ח נח עד, א ואילך."],["11262","542","<b>במ\"ת שהיו ת\"ר אלף</b>: ראה שבת פח, א. לקמן פ' תרומה שיא, ד הערה 33."],["11263","543","<b>כ\"א</b>: ט: כולם."],["11264","544","<b>ממש</b>: חט: ליתא."],["11265","545","<b>ויחן ישראל</b>: נסמן לעיל יד, א."],["11266","546","<b>ישנו עם א'</b>: אסתר ג, ח."],["11267","547","<b>א'</b>: חט: עם."],["11268","548","<b>א'</b>: שם: ליתא."],["11269","549","<b>גוי אחד בארץ</b>: שמו\"ב ז, כג. דהי\"א יז, כא."],["11270","550","<b>בנוהי דיצחק. . דאברהם</b>: ראה גם לעיל פ' שמות יג, ג. וש\"נ."],["11271","551","<b>ויהי כל הארץ שפה א'. . לה\"ק</b>: נח יא, א ובת\"י ורש\"י שם. הנסמן בתו\"ח נח עה, ג הערה 20."],["11272","552","<b>והייתם לי סגולה</b>: יתרו יט, ה."],["11273","553","<b>אז יאמרו בגוים</b>: ראה גם לעיל לז, א. וש\"נ."],["11274","554","<b>ונהרו אליו כל הגוים</b>: ישעי' ב, ב."],["11275","555","<b>בעיני כל העמים</b>: דח: בעוני כל הימים."]]],[2300540777,"להם<sup data-n=\"11276\">556</sup> בתשו[בה] שלימה מעומקא דלבא שהוא שנק' עומ\"ת ביותר כמ\"ש בצר לך ומצאוך כל הדברים כו' ושבת עד הוי'<sup data-n=\"11277\">557</sup> כו'. וכל שישראל יורדי' בתחתית המדריגה ביותר זהו כמשל היושב בבור<sup data-n=\"11278\">558</sup> עמוק ביותר שבתוך [ה]עומק ההוא רק חושך ולא אור מפני עמקותו בתחתית הארץ, כך כשישראל בירידת המדריגות בתכלית השפלות והמיצר וטמאים<sup data-n=\"11279\">559</sup> בעיני הגוים ביותר כמ\"ש למתעב גוי<sup data-n=\"11280\">560</sup> כו', ומשם הם צועקים בתשו[בה] עמוקה מקרב הלב בעומק יותר, כידוע בגלות מצרים דכתיב וימררו [את] חייהם<sup data-n=\"11281\">561</sup> כו' ותעל שועתם לפני ה'<sup data-n=\"11282\">562</sup> כו' אחר השפלות בירידות המדריגות ביותר בעינוי<sup data-n=\"11283\">563</sup> ולחץ גדול שזה קשה יותר מעול העבודה שעבדו במצרים כו', לפי שהשפלות הוא שנק' עומ\"ת כו' ובאים לבחי' לב נשבר ביותר ועי\"ז מעוררים למעלה מבחי' עו[מ]\"ר דוקא, דהיינו שנגלה עמוקות העליונ[ות] מחושך העליון הוא מבחי' סדכ\"ס עצמו כנ\"ל ומשום דעו[מ]\"ר אינו שורה רק בעומ\"ת<sup data-n=\"11284\">564</sup> דוקא כמ\"ש אני מרום וקדוש<sup data-n=\"11285\">565</sup> כו' את דכא ושפל רוח<sup data-n=\"11286\">566</sup> כו' וכן אל מי אביט<sup data-n=\"11287\">567</sup> כו' וכה\"ג.\n<b>(אך</b> עדיין א\"ז מובן דאם עיקר הטעם הוא רק ענין המיצר והשפלות מה זה שאמר פזרונו שפזרן בין אוה\"ע דוקא, מה שייך ענין הפיזור לזה דהלא גם אם היו כולם תחת ממשלת שר א' היו יכולים להיות במיצר ושפלות כמו שהיו כולם כא' במצרים כו', או כמו שהיו בימי אחשורוש<sup data-n=\"11288\">568</sup> ובגלות בבל וכה\"ג, ולמה בגלות האחרון דוקא הן מפוזרים תחת כל העמים (כמ\"ש ויתהלכו מגוי אל גוי<sup data-n=\"11289\">569</sup> כו' שלא הי' כן בגלות הראשונות כו'). וצ\"ל משום דד' גליות הן בדוגמא דד' נהרות<sup data-n=\"11290\">570</sup> ונהר נילוס דמצרים שהוא פישון<sup data-n=\"11291\">571</sup> הי' הראשון, וגלות האחרון הוא הנק' נה\"פ<sup data-n=\"11292\">572</sup> שזה יהי' העברה הב' בימוהמ\"ש בנהר מצרים כו' שיהופך אל עמים כו', [ו]ע\"כ פיזרן לישראל לבין אוה\"ע כדי שיבררו ע\"י שם מ\"ה דאדם בתו\"מ לכל העמים דמ\"ה מברר לב\"ן<sup data-n=\"11293\">573</sup> דנוגה שהן ז\"מ דתהו<sup data-n=\"11294\">574</sup> שהן בבחי' ב\"ן, והן ז'<sup data-n=\"11295\">575</sup> אומות<sup data-n=\"11296\">576</sup> נגד ז' מדות<sup data-n=\"11297\">577</sup> דנוגה וכאו\"א כלולה מי' שהן ע' וכאשר יבורר גם בבחי' ג\"ר כח\"ב שהן קני קניזי<sup data-n=\"11298\">579</sup> וקדמוני<sup data-n=\"11299\">578</sup> שהן עמון ומואב ואדום<sup data-n=\"11300\">580</sup> שזהו שיהי' בהעברה שני' בנהר",[["11276","556","<b>יצעקו אל ה' בצר להם</b>: ע\"פ תהלים קז, ו. כח."],["11277","557","<b>בצר לך. . עד הוי'</b>: ואתחנן ד, ל."],["11278","558","<b>כמשל היושב בבור</b>: ראה גם מאמרי אדה\"ז תקס\"ה כאן ע' תתקצז."],["11279","559","<b>וטמאים</b>: חט: ושנואים."],["11280","560","<b>למתעב גוי</b>: ישעי' מט, ז."],["11281","561","<b>וימררו [את] חייהם</b>: שמות א, יד."],["11282","562","<b>ותעל שועתם לפני ה'</b>: שמות ב, כג [ושם — אל האלקים]."],["11283","563","<b>בעינוי</b>: דח: בעוני."],["11284","564","<b>דעו[מ]\"ר. . בעומ\"ת</b>: נסמן לעיל פ' וארא פג, ב."],["11285","565","<b>אני מרום וקדוש</b>: ישעי' נז, טו [בהוספת תיבת ”אני\" — ראה הנסמן לעיל קעא, ג]."],["11286","566","<b>את דכא ושפל רוח</b>: ישעי' שם [ושם: ואת — ראה גם לעיל פג, ב ובהנסמן לשם]."],["11287","567","<b>אל מי </b>[ט: זה]<b> אביט</b>: ישעי' סו, ב [ושם: ואל זה אביט — ראה הנסמן במאמרי אדה\"א בראשית ע' קנז]."],["11288","568","<b>כמו שהיו בימי אחשורוש</b>: ראה לעיל בפנים על יד הערה 546."],["11289","569","<b>ויתהלכו מגוי אל גוי</b>: תהלים קה, יג. דהי\"א טז, כ."],["11290","570","<b>דד' גליות. . דד' נהרות</b>: ראה גם לעיל פ' שמות לו, ד. מ, ג. וש\"נ."],["11291","571","<b>ונהר נילוס. . פישון</b>: נסמן לעיל לו, ד."],["11292","572","<b>נה\"פ</b>: חט: נהר פרת."],["11293","573","<b>דמ\"ה מברר לב\"ן</b>: נסמן לעיל ד, ב."],["11294","574","<b>ז\"מ דתהו. . ע' אומות</b>: ראה תו\"ח נח עג, ג."],["11295","575","<b>ז'</b>: חט: ע'."],["11296","576","<b>ע' אומות</b>: סוכה נה, ב."],["11297","577","<b>ע' אומות נגד ז' מדות</b>: ראה גם לקמן פ' יתרו ער, ג."],["11298","579","<b>קני קניזי וקדמוני</b>: לך טו, יט."],["11299","578","<b>כח\"ב שהן קני קניזי וקדמוני</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתג. מאמרי אדה\"א דברים ח\"א ע' י ואילך. וש\"נ. ח\"ד ע' א'תצא. שמות ח\"ב ע' תקמ."],["11300","580","<b>קני. . עמון ומואב ואדום</b>: ראה רש\"י לך שם. אוה\"ת דברים ע' כו. לקו\"ש מטו\"מ — כרך כח — ע' 214 הערה 57."]]],[2300540788,"מצרים שיקבץ מאשור<sup data-n=\"11301\">581</sup> כו' שיהי' מספר בנ\"י כחול הים<sup data-n=\"11302\">582</sup> כו', לפי שאמר בהנחל עליון גוים כו'<sup data-n=\"11303\">583</sup> בהפרידו בנ\"א שהן נפשות עשו<sup data-n=\"11304\">584</sup> טורי דפרודא<sup data-n=\"11305\">585</sup> מז' מדות דתהו שיצאו בבחי' תיקון אחר המבול שהן ג' בני נח שמאלה נפצה כל הארץ<sup data-n=\"11306\">586</sup> אזי יצב גבולות עמים כו' שהן ע' למספר בנ\"י שהן ע' נפש דיעקב<sup data-n=\"11307\">587</sup> כשמבררים לע\"ש דנוגה ע\"י שם מ\"ה (וכידוע במ\"ש ואעשה אותך שם דוקא לגוי גדול<sup data-n=\"11308\">588</sup>, דהיינו בדור הפלגה שהיו ס\"ר<sup data-n=\"11309\">589</sup> ורצו לעשות להם שם מ\"ה באחדות החיצוני' שלהם שלא יצטרכו להיות בבחי' ביטול<sup data-n=\"11310\">590</sup> לאין ומ\"ה דקדושה כמ\"ש במ\"א, והי' זה לפי שכל אומות היו מדברים בלה\"ק שמייחד את כולם וע\"כ בלל לשונם והפרידן זמ\"ז כמו שהן בשרשן ענפין מתפרדין<sup data-n=\"11311\">591</sup> <span data-k=\"pg\">שלו</span> ּ דז\"מ דתהו שהן זת\"ז<sup data-n=\"11312\">592</sup> כו'. וזהו פיזור לרשעים הנאה להם<sup data-n=\"11313\">593</sup> שלא יהיו בקומת אדם יחד שלא יחר[י]בו העולם כו', והן סיבת הפ[י]ר[ו]ד[י]ם בין כל העמים כו', ולהיפוך יש בהם אהבת רעים בפרט שהוא ענין האחדות שהי' בדור הפלגה היפוך אחדות האמיתי דקדושה האלקי' (כמו האפיקורסי') מצד גלות דשם מ\"ה דאדם דקדושה).\n<b>והנה</b> ידוע דס\"ר נשמות דדור הפלגה הוא שנתקנו בס\"ר נש\"י<sup data-n=\"11314\">594</sup> שנולדו במצרים (שנמשכו מניצוצות שנפלו בנהר נילוס שהובררו חלק החמישי<sup data-n=\"11315\">595</sup> שראוים המה לקבלת התו\"מ פב\"פ שזה יחוד דשם מ\"ה דהוי' דאדם העליון, ובזה נתק[נו] ס\"ר [של] דור הפלגה שרצו לעשות שם כו'. ודורות הבאים אחר דור דקבלת התורה בה\"ס עד בימי דוד ושלמה תיקנו יותר. ועשו הגדלה וריבוי באו\"כ עד למעלה מעלה מבחי' גדלות דאו\"א כו'. ואמנם כ\"ז רק בבירור ז\"מ שהי' בשבירה ונתקנו ע\"י א\"י, וחזרו לקלקולן בחורבן בהמ\"ק שחזרו ישראל להיות בגלות ארץ העמים לתקן ולברר לז\"מ דתהו שנכללים בהם כל הע\"ש דנוגה. אך שלימות הבירור הוא בגלות האחרון דוקא שפזרן בד' רוחות העולם בין כל העמים שפיזור זה לצדיקים דנש\"י מצד העצם א' ועמך כולם צדיקים<sup data-n=\"11316\">596</sup> שהן בציור אדם העליון, וע\"כ גם בפיזורם אינם נפרדים כלל זמ\"ז, ואדרבה פיזור זה לטובתם הוא שיהי' גוי",[["11301","581","<b>בנהר מצרים שיקבץ מאשור</b>: ישעי' יא, טו. טז."],["11302","582","<b>שיהי' מספר בנ\"י כחול הים</b>: הושע ב, א."],["11303","583","<b>כו'</b>: כ\"ה גם בדח."],["11304","584","<b>נפשות עשו</b>: וישלח לו, ו. ראה ויק\"ר פ\"ד, ו. רש\"י ויגש מו, כו. שע\"ת עג, ד ובהערה 87."],["11305","585","<b>טורי דפרודא</b>: זהר בראשית כט, ב. ויצא קנח, א. פקודי רלד, סע\"א."],["11306","586","<b>שמאלה נפצה כל הארץ</b>: נח ט, יט."],["11307","587","<b>ע' נפש דיעקב</b>: ויגש מו, כז."],["11308","588","<b>ואעשה אותך שם. . לגוי גדול</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תסא. וש\"נ. ויקרא ח\"א ס\"ע עב ואילך. מאמרי אדה\"ז תקע\"א ע' קד. וש\"נ. שע\"ת קמא, א. תו\"ח ח\"ש קכא, ג."],["11309","589","<b>בדור הפלגה שהיו ס\"ר</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ר\"ע עג. במדבר ח\"ב ע' תשטו וע' תשסה."],["11310","590","<b>שלא יצטרכו להיות בבחי' ביטול</b>: ראה תו\"ח נח עד, ב ואילך (ובהנסמן בריש המאמר שם)."],["11311","591","<b>ענפין מתפרדין</b>: זהר ח\"ש קכג, א."],["11312","592","<b>זת\"ז</b>: נסמן לעיל מד, ג."],["11313","593","<b>פיזור לרשעים הנאה להם</b>: סנהדרין עא, ב (במשנה). ראה גם שע\"ת נא, ג."],["11314","594","<b>דס\"ר נשמות דדור הפלגה. . בס\"ר נש\"י</b>: ראה גם לעיל פ' שמות מ, ב. וש\"נ."],["11315","595","<b>שהובררו חלק החמישי</b>: מכילתא בשלח יג, יח. הובאה ברש\"י שם."],["11316","596","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."]]],[2300540799,"א' בארץ בהיותם מפוזרים בין כל העמים דוקא, שאז יעלו ויבררו להביא כל הע\"ש דנוגה לאחדות אמיתי כל משך זמן גלות האחרון ע\"י תו\"מ ותפלה שלהם עד בימוהמ\"ש שיתקבצו אליו כל העמים כמ\"ש ולו יקהת עמים<sup data-n=\"11317\">597</sup> גם אדום ומואב כו' (וסימן ודוגמא לדבר זה הוא בכל חג הסוכות בע' פרי החג<sup data-n=\"11318\">598</sup> שהוא בשביל בירור דע\"ש<sup data-n=\"11319\">599</sup> דנוגה כמ\"ש הללו את ה' כל גוים<sup data-n=\"11320\">600</sup> כו' ואח\"כ בש\"ע נכללים כולם בישראל גוי א' בארץ והוא מלך הח' דמשיח שנק' הד\"ר<sup data-n=\"11321\">601</sup> שמברר לכל הז\"מ כו', וזהו ביום השמיני שלח<sup data-n=\"11322\">602</sup> המלך<sup data-n=\"11323\">603</sup> את העם כו' כמ\"ש במ\"א). וזהו הוא פר\"ת הוא דמעיקרא<sup data-n=\"11324\">605</sup> שהוא נהר נילוס<sup data-n=\"11325\">606</sup> דמצרים<sup data-n=\"11326\">604</sup> כמ\"ש למען תזכור<sup data-n=\"11327\">607</sup> כו' [ו]כמ\"ש כאשר הי' בעלותם<sup data-n=\"11328\">608</sup> כו', לפי שהן [היו] הס\"ר שנפלו מדור הפלגה כנ\"ל ועשו פרי למעלה והגדילו במאד עד שהי' [ל]מספר כחול הים שלא ימד כו' [כמו] עד דוד הגדיל<sup data-n=\"11329\">609</sup> וכתיב הגדיל ה' לעשות<sup data-n=\"11330\">610</sup> וכמ\"ש הקטן יהי' לאלף<sup data-n=\"11331\">611</sup> כו' וד\"ל.\n<b>וזהו</b> צדקת פרזונו כו' שפזרן כו' נק' צדקה כו' כמו זורע צדקות<sup data-n=\"11332\">612</sup> כו', כי נש\"י בכל דור נזרעים למטה מאור הזרוע לצ\"ע בכל [ה]ע\"ש שהם מפוזרים שם כמ\"ש וזרעתיה לי בארץ<sup data-n=\"11333\">613</sup> כזורע קב להוציא כמה כורין<sup data-n=\"11334\">614</sup> כידוע, וכמ\"ש הלוך ילך ובכה<sup data-n=\"11335\">615</sup> נושא משך הזרע שזהו אור הזרוע לצ\"ע להיות שרש<sup data-n=\"11336\">616</sup> נשמ[ו]ת רשעים שיאבדו כו', ולפי שבלתי ידח ממנו נדח<sup data-n=\"11337\">617</sup> כמ\"ש אז תעבורנה הצאן ע\"י מונה<sup data-n=\"11338\">618</sup> אעפ\"י שיהי' לאין מספר כו', ע\"כ אמר בא יבא ברינה<sup data-n=\"11339\">619</sup> כו' משום דזריעה זאת הוא בשביל בירור הניצוצות דע\"ש דק\"נ כו' ע\"כ נק' צדקה בה' להחיות רוח שפלים<sup data-n=\"11340\">620</sup> כו' שהוא בחי' מה שישפיע לכל כו', וזהו זורע צדקות מצמיח כו'. ויש צמיחה של צדקה כמו כי כארץ תוציא צמחה<sup data-n=\"11341\">621</sup> כו' כן יצמיח צדקה ותהלה <span data-k=\"pg\">674</span> ּ נגד כל הגוים דוקא (וזהו בכל ר\"ה שנק' מלך על כל הארץ<sup data-n=\"11342\">622</sup>, וזהו שא' שצדקה עשה עם ישראל שפיזרן כו' שבצדקה זו יצמחו לאין שיעור כאשר יהי' קיבוץ גליות כמ\"ש אם יהי' נדחך<sup data-n=\"11343\">623</sup> בקצה השמים כו'. וזהו הסימן לתכלית היחוד אמיתי שבנש\"י שנק' גוי א' בארץ למהוי אחד",[["11317","597","<b>ולו יקהת עמים</b>: ויחי מט, י."],["11318","598","<b>בע' פרי החג</b>: פינחס כט, יג ואילך."],["11319","599","<b>בע' פרי החג. . דע\"ש</b>: ראה סוכה נה, ב. זהר תצוה קפז, רע\"א. מאמרי אדה\"א דברים ח\"ד ע' א'שנו. וש\"נ."],["11320","600","<b>הללו את ה' כל גוים</b>: תהלים קיז, א."],["11321","601","<b>מלך הח' דמשיח שנק' הד\"ר</b>: ראה גם לעיל פ' שמות מג, ד. וש\"נ לקמן רלה, ג. פ' ויקהל שצט, א. תא, ד. מאמרי אדה\"א דברים ח\"ד ע' א'שפו. וש\"נ."],["11322","602","<b>ביום השמיני שלח</b>: נסמן לעיל מג, ד."],["11323","603","<b>ביום השמיני שלח המלך</b>: נסמן לעיל רח, ג."],["11324","605","<b>הוא פר\"ת הוא דמעיקרא</b>: בראשית ב, יד. בכורות נה, ב."],["11325","606","<b>פר\"ת. . שהוא נהר נילוס</b>: נסמן לעיל כו, ג."],["11326","604","<b>כמ\"ש. . דמצרים</b>: ניתוסף ע\"פ זט."],["11327","607","<b>למען תזכור</b>: פ' ראה טז, ג."],["11328","608","<b>כאשר הי' בעלותם</b>: ס' שופטים יא, יג [ושם: בעלותו ממצרים]. שם טז [ושם: כי בעלותם ממצרים]. שמו\"א טו, ב [ושם: בעלותו ממצרים]. שם ו [בעלותם ממצרים]."],["11329","609","<b>עד דוד הגדיל</b>: שמו\"א כ, מא."],["11330","610","<b>הגדיל ה' לעשות</b>: תהלים קכו, ב."],["11331","611","<b>הקטן יהי' לאלף</b>: ישעי' ס, כב."],["11332","612","<b>זורע צדקות</b>: ברכת יוצר."],["11333","613","<b>וזרעתיה לי בארץ</b>: הושע ב, כה."],["11334","614","<b>כזורע קב להוציא כמה כורין</b>: נסמן לעיל מ, ג."],["11335","615","<b>הלוך ילך ובכה</b>: ראה לעיל קלג, ד. וש\"נ."],["11336","616","<b>שרש</b>: דח: ליתא. ט: שיש."],["11337","617","<b>שבלתי ידח ממנו נדח</b>: שמו\"ב יד, יד."],["11338","618","<b>אז תעבורנה הצאן ע\"י מונה</b>: נסמן לעיל פ' וארא סח, א."],["11339","619","<b>בא יבא ברינה</b>: המשך הכתוב הלוך ילך ובכה."],["11340","620","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["11341","621","<b>כי כארץ תוציא צמחה</b>: ישעי' סא, יא [בדילוג]."],["11342","622","<b>מלך על כל הארץ</b>: נוסח ברכת היום דר\"ה ויו\"כ."],["11343","623","<b>אם יהי' נדחך</b>: נצבים ל, ד."]]],[2300540809,"באחד<sup data-n=\"11344\">624</sup> ממש והפיזור הזה אינו פיזור ופירוד כלל [וכלל] שהרי מיד ישובו כולם כא' ולא עוד אלא שיעלה עמהם כל העמים כמ\"ש לעבדו שכם א'<sup data-n=\"11345\">625</sup> כו' וכמ\"ש והחזיקו<sup data-n=\"11346\">626</sup> כו'). וזהו צדקה תרומם גוי<sup data-n=\"11347\">627</sup> כו' וכתיב בצדקה תכונני<sup data-n=\"11348\">628</sup> והיינו ע\"י צדקה שפיזרן בין האומות שמקיימים שם תו\"מ וכמ\"ש וצדקה תהי' לנו<sup data-n=\"11349\">629</sup> כו', ולמעלה צדקה העליונה שנק' צדקת פרזונו דבחי' צ\"ע הנ\"ל בישראל דוקא בכל מקומות מושבותיהם בפיזור בין כל העמים שפיזור זה עושה יחוד גמור (משא\"כ פיזור לרשעים שעושה פירוד גמור כפיזור דדור הפלגה, וא\"כ מובן דפיזור זה דישראל יתקן לפיזור ופירוד דדור הפלגה שהן ע' אומות מאחר שהן מס\"ר דדוה\"פ<sup data-n=\"11350\">630</sup> שנפלו בנהר נילוס כו' וד\"ל.\n<b>וזהו</b> והנצח זו בנין ירושלים דוקא כנ\"ל. דהנה עיקר הטעם [ל]מה שפיזרן לבין אוה\"ע הוא בשביל שיבואו עי\"ז לבחי' הנצח כדי שיגאלם ע\"י מדת הנצח ויהי' בנין ירושלים נצחיי' וכנ\"ל. כי הנה מ\"ש א\"ת פרזונו אלא פזרונו י\"ל הטעם למה לא נק' פרזונו כפשוטו שהוא בחי' ההתגלות בגילוי אור החכ' או הנבואה ורוה\"ק שנק' פרזון כמ\"ש חדלו פרזון בישראל<sup data-n=\"11351\">631</sup> כו' כמו ערי הפרזות<sup data-n=\"11352\">632</sup> שפרוז ופתוח<sup data-n=\"11353\">633</sup> בלי חומה מקפת ומסתרת כידוע). אך הענין הוא כמבואר למעלה בענין מגלה עמוקות מני חשך כו' שהוא בחי' גילוי ההעלם דחושך סתרו כו'. והנה יש בזה ב' אופנים, הא' כאשר ההתגלות בא מבחי' ההעלם שהוא המקיף, כמקיפים דכתר שהוא הרצון והתענוג שלמעלה מן השכל והטעם שבא בגילוי להיות בבחי' או\"פ כמו שהחכ' מאי\"ן דכת\"ר תמצא בגילוי, וכה\"ג בבחי' המדות שבכתר שבאים בבחי' גילוי אור, וכמו מדות דעצמו' הרצון שבהעלם מאירי' בגילוי. וזהו שהמקיף נעשה פנימי הוא שנק' פרזון כערי הפרזי שמגולה מן ההיקף, כך העומק של החכ' שבמוחין באי' מהעלם<sup data-n=\"11354\">634</sup> לגילוי כחכ' שניתן לשלמה ומשיח דכתי' בי' ישכיל עבדי כו' וכגילוי סוד ה' ליריאיו, וכן מדות דאה\"ר ורב חסד העליון שבא בגילוי<sup data-n=\"11355\">635</sup> במל', וכך הוא גילוי אור הנבואה. וזהו צדקת פרזונו בישראל ש[נ]פתח כל בחי' העלם דמקיפים דכח\"ב ומדות (וזהו מקול מחצצים<sup data-n=\"11356\">636</sup> בין משאבים שם יתנו כו'), והן כל אוצרות חיים העליונים כשהן גנוזים וסתומים בהעלם אחר העלם עד בחי' סדכ\"ס עצמו שיפתח מן ההעלם לגילוי כמו יפתח ה' לך<sup data-n=\"11357\">637</sup> את אוצרו הטוב כו' והוא אוצר החכ\"ע<sup data-n=\"11358\">638</sup> והיר\"ע כנ\"ל בענין מגלה עמוקות מעומק לעומק כו'. אך גילוי זה הוא בא בהגבלת הכלי בכלים מכלים שונים כמו לע\"ל שתמלא הארץ דעה את ה'<sup data-n=\"11359\">639</sup> וישפוך רוחו על כ\"ב<sup data-n=\"11360\">640</sup> כו', כמו עכשיו בגעה\"ע ובגעה\"ת וכך<sup data-n=\"11361\">641</sup>",[["11344","624","<b>למהוי אחד באחד</b>: זהר תרומה קלה, סע\"א."],["11345","625","<b>לעבדו שכם א'</b>: צפני' ג, ט."],["11346","626","<b>והחזיקו</b>: זכרי' ח, כג."],["11347","627","<b>צדקה תרומם גוי</b>: משלי יד, לד."],["11348","628","<b>בצדקה תכונני</b>: ישעי' נד, יד."],["11349","629","<b>וצדקה תהי' לנו </b>[ח: ניתוסף: כי נשמור לעשות]: ואתחנן ו, כה."],["11350","630","<b>דדוה\"פ</b>: ח: דדור הפלגה."],["11351","631","<b>חדלו פרזון בישראל</b>: ס' שופטים ה, ז."],["11352","632","<b>ערי הפרזות</b>: אסתר ט, יט [ושם: בערי]. דח: הפרזי — דברים ג, ה [ושם: מערי]."],["11353","633","<b>שפרוז ופתוח</b>: ד: שפרוז הוא פתוח. ח: כבפנים. ט: שפרזון הוא פתוח."],["11354","634","<b>שבמוחין באי' מהעלם</b>: חט: שבבחי' אין והעלם בא."],["11355","635","<b>בגילוי</b>: בתו\"ח נכפלו עוה\"פ: מהעלם לגילוי. . שבא בגילוי."],["11356","636","<b>מקול מחצצים</b>: ס' שופטים ה, יא."],["11357","637","<b>יפתח ה' לך</b>: תבוא כח, יב."],["11358","638","<b>החכ\"ע</b>: דחט: החכ'."],["11359","639","<b>שתמלא הארץ דעה את ה'</b>: ישעי' יא, ט."],["11360","640","<b>וישפוך רוחו על כ\"ב </b>[ט: כל בשר]: יואל ג, א."],["11361","641","<b>וכך</b>: דחט: ליתא."]]],[2300540818,"בריבוי <span data-k=\"pg\">שלז</span> ּ הכלים דנשמות ומלאכים, וכמו בכל חדש ושבת [נ]פתח פתחים ושערים העליונים שער הפונה קדים<sup data-n=\"11362\">642</sup> שסגור הוא כו' וביום השבת וחדש נפתח וכן במועדים ורגלים, ולפעמים נפסק הגילוי אור הזה כמו שנפסקה הנבואה ורוה\"ק בנביאים אחר החורבן<sup data-n=\"11363\">643</sup>. וכך בכלל ישראל נפסק צ\"פ<sup data-n=\"11364\">644</sup> כמ\"ש חדלו פרזון בישראל כו' וכה\"ג, ולא נגלה האור האלקי בנש\"י בניסים<sup data-n=\"11365\">645</sup> בפו\"מ כו' כמו אותותינו לא ראינו<sup data-n=\"11366\">646</sup> כו' רק בלבושים והעלמות נעלמות<sup data-n=\"11367\">647</sup> בדרך הטבע, ואם יבא לפרקים איזה גילוי מן ההעלם יבוא בגבול כו'. אבל אופן הב' בגילוי העמוקות בנפלאות הגנוזים באוצרות עליונים הוא ענין הבזבוז האוצרות העליונים, שזהו כמו במשל הבזבוז של אוצרות הגשמים שאין ניאותין מהם לעולם<sup data-n=\"11368\">648</sup> ולא נגלה לעולם בהיכל המלך ובית המלך רק בעת המלחמה ניתנו להוצאה, שזהו הנק' בזבוז שנעשה מן הקדש חול שהוקר<sup data-n=\"11369\">649</sup> מאד מאד שלא ראו עיני אדם נמסר ל[צורך] הוצאה בדברים פחותים הנצרכים למלחמה, ולפי שעה לבד שהולכים וכלים ונמכרים<sup data-n=\"11370\">650</sup> כי נמכר כל כלי יקר ונתנו ביד אחרים להחליפן בעד דברים פחותים כמו כלי מלחמה ומזון לעם וכה\"ג, שזהו כמו הבזבוז שבוזזין להון יקר וכל אבני חפץ לזרים בשוקים וברחובות שהכל קונין אותם, או יתן אותם בעבור הנצרך לפי\"ש<sup data-n=\"11371\">651</sup> למזון ולבוש וכלי מלחמה וכה\"ג וד\"ל.\n<b>והנמשל</b> מזה יובן בענין בזבוז האוצרות העליונים שיורדים מהעלמם מלמעלה מעלה למטה מטה ביותר והוא בשביל ניצוח מלחמה לכבוש ולאכפיי' לס\"א כו', כמו ליתן כח לנשמה האלקי' ע\"י יר\"ע וח\"ע כדי שיוכל לכבוש להרע דיצה\"ר ברוגז ולהפילו ולהכניעו, והוא כמו אוצר של יר\"ש או אוצר הח\"ע שמתלבש ונמשך רק<sup data-n=\"11372\">652</sup> בלבוש שק בדברים פחותי' שהוא [ל]לבוש כלי מלחמה לנצח הרע שבקרבו כו', רק בשביל ניצוח שהוא תוקף הרצון למעלה מן החכ' והטעם כנ\"ל, שלזה צריך בזבוז של אוצר י\"ש שלמעלה מגילוי אור דח\"ע שבא מן ההעלם דמקיף דכתר שאינה רק במדה וליח\"ס בהצנע לכת דוקא. אבל בחי' בזבוז של אוצר דיר\"ש בא לכל בשוה יהי' מי שיהי' מלביש לנפשו בכל תוקף ועוז לנצח את היצה\"ר שזהו בחי' תענוג גדול יותר מכל התענוגי' הפנימי' שברצון וחכ' הנק' פרזון כנ\"ל וד\"ל. וז\"ש א\"ת פרזונו אלא פזרונו דוקא שהוא בחי' פיזור דאוצר עומק העליון שמבזבז אותם למטה מטה שלא הי' מגלה כלל מבחי' פרזונו רק בשביל הניצוח לנצח למנגד דוקא וד\"ל (וכמו שיש בדוגמא זו בניסים ונפלאות העליונים שנתגלו למטה בכל דור גם עכשיו רק לנצח האויב ולא בזכות אהבת ישראל, כמו",[["11362","642","<b>שער הפונה קדים</b>: יחזקאל מו, א."],["11363","643","<b>שנפסקה הנבואה. . אחר החורבן</b>: נסמן לעיל פ' בא צח, ב."],["11364","644","<b>צ\"פ</b>: חט: צדקת פזרונו."],["11365","645","<b>בניסים</b>: דח: ליתא."],["11366","646","<b>אותותינו לא ראינו</b>: תהלים עט, ד."],["11367","647","<b>נעלמות</b>: חט: גדולות."],["11368","648","<b>לעולם</b>: שם: ליתא."],["11369","649","<b>שהוקר</b>: ד: שהיקר."],["11370","650","<b>ונמכרים</b>: חט: ליתא."],["11371","651","<b>לפי\"ש</b>: שם: לפי שעה."],["11372","652","<b>רק</b>: שם: ליתא."]]],[2300540827,"שהי' במפלת סנחריב לפי שנערי אשור גדפו<sup data-n=\"11373\">653</sup> כו' ולא בזכות חזקי', וכן במצרים לפי שפרעה הקשה לבו וא' מי הוי'<sup data-n=\"11374\">654</sup> כו' יצא הוי' בכבודו ובעצמו והכה כל בכור כו' כמ\"ש ועברתי באמ\"צ אני ולא מלאך כו', וכך כל האותות והמופתים שהיו במצרים ובקי\"ס שהוא ע\"י גילוי בחי' האורות העליונים הגנוזים כו' שנק' נפלאות העליונים כמ\"ש לעושה נפלאות <span data-k=\"pg\">676</span> ּ גדולות לבדו<sup data-n=\"11375\">655</sup> דוקא כו' וכן א' לע\"ל כימי צאתך מאמ\"צ אראנו נפלאות מבחי' סדכ\"ס שמגלה עמוקות כנ\"ל).\n<b>והנה</b> מבואר למעלה בעיקר בחי' מדת הניצוח שהוא מתעורר דוקא בהיות מנגד המנגד לרצונו<sup data-n=\"11376\">656</sup> (והוא מושל בדבר האהוב לו ויקר בעיניו כבנו וכה\"ג)<sup data-n=\"11377\">657</sup> וא\"ל הי' מנגד<sup data-n=\"11378\">658</sup> לא הי' בניצוח כלל, כי מצד עצם הדבר אין לו רצון ותענוג בזה כלל, ואין מי שעומד בעבורו ראוי כלל כמו כאשר אין זכות לישראל מצד עצמם כלל, ואמנם כשיש מנגד אז דוקא מתעורר הניצוח שגובר על כל רצון ותענוג לבזבז כל הון יקר כו'. וכך הוא גם כאן בפיזור ישראל בין כל העמים והן בשעבודים גדולים וירושלים ביד זרים אז מתעורר בחי' ניצוח העליון, והיינו לבזבז כל האוצרות העליונים הגנוזים למעלה מן זמן קדמון<sup data-n=\"11379\">659</sup> [כו'] כנ\"ל במ\"ש מגלה עמוקות מני חשך כו' שנק' אוצרות החיים העליונים [הנעלמים] בהעלם אחר העלם רק כדי לאכפייא לסט\"א אעפ\"י שאין זכות לישראל כלל. וזהו צדקת פזרונו ולא פרזונו, דהיינו מה שפזרן לבין אוה\"ע משום דפיזור זה כדי שיבוא לבחי' הניצוח עי\"ז אח\"כ מצד המנגד שמשתעבדי' בהם כו' ויגאלם ויבנה ירושלים בניצוח זה ע\"י שמגלה עמוקות שהוא בזבוז האוצרות כנ\"ל. וא\"כ הרי בחי' חסד וצדקה גדולה הוא הפיזור הזה בתחלה כי לזאת הכוונה פזרן שיהיו משועבדים תחת ע\"ש ויגאלם מהם ע\"י הניצוח וד\"ל (ובאמת עדיין אין זה מובן דמה שייך פיזור זה בין כל אוה\"ע דוקא לענין הניצוח נגד המנגד דגם בגלו' א' כמו בגלות מצרים וגלות בבל הי' מתעורר בחי' [מדת] הניצוח, ועוד מה שייך הניצוח לענין הפיזור דוקא ולמה פזרם<sup data-n=\"11380\">660</sup> כו'. אך הנה מבואר למעלה בפי' פזרונו שהוא בחי' פיזור שבזבז כל האוצרות עליונים בשביל הניצוח דמלחמה. והנה יש עוד פי' בפזרונו ע\"ד הנ\"ל בבזבוז של האוצרות העליוני', והוא מה שנתפזר אור הזרוע לצ\"ע להמשיך נשמות ישראל<sup data-n=\"11381\">661</sup> בכל דור ודור כפלי כפליים כיוצאי מצרים, ואעפ\"י שביצי\"מ היו רק ת\"ר אלף<sup data-n=\"11382\">662</sup> ונולד מהם [עוד] ת\"ר אלף<sup data-n=\"11383\">663</sup> [עד] שבאו לא\"י עם יהושע ובניהם אחריהם דור אחר דור עד חורבן ב\"ר וב\"ש עד זמן דור אחרון דביאת משיח, הכל",[["11373","653","<b>במפלת סנחריב. . גדפו</b>: מל\"ב יח, יז ואילך. פי\"ט. ישעי' פל\"ו. פל\"ז."],["11374","654","<b>מי הוי'</b>: שמות ה, ב."],["11375","655","<b>לעושה נפלאות גדולות לבדו</b>: תהלים קלו, ד. ראה גם לקמן פ' ויקהל שפח, א."],["11376","656","<b>המנגד לרצונו</b>: זט: (ה)עומד לנגד רצונו."],["11377","657","<b>(והוא. . וכה\"ג)</b>: ניתוסף ע\"פ: זטי."],["11378","658","<b>וא\"ל הי' מנגד</b>: שם: ולולי מצד המנגד."],["11379","659","<b>מן זמן קדמון</b>: ט: משנים קדמוני'."],["11380","660","<b>פזרם</b>: חט: פזרונו ולא פרזונו."],["11381","661","<b>יש עוד. . ישראל</b>: ניתוסף ע\"פ: זטי."],["11382","662","<b>שביצי\"מ היו רק ת\"ר אלף</b>: בא יב, לז."],["11383","663","<b>[עוד] ת\"ר אלף</b>: פינחס כו, נא."]]],[2300540836,"נמשך מאור צ\"ע שהוא מן הנשמות הגנוזים באוצרות עליונים שנק' אוצר הנשמות כמ\"ש אין בן דוד בא<sup data-n=\"11384\">664</sup> עד שיכלו כל הנשמות מן האוצר ששמו גוף כו' והרבה נשמות יורדים בגופים והן צדיקים והרבה הן רשעים והולכים לאיבוד כמ\"ש הלוך ילך כו' כנ\"ל. וידוע דכל הנשמות הנזרעים למטה הן משוקעים בשר של הארץ ההיא<sup data-n=\"11385\">665</sup> שהוא לבוש החשמ\"ל דבחי' נוגה דמל' דעשי' כמו ת\"ר אלף שנולדו במצרים שיצאו משר של מצרים כו'. וכך בכל דור ודור בכל מקומות גלות ישראל בין אוה\"ע כל אשר יולדו שם נמשך מאור הזרוע לצ\"ע בע\"ש שלמעלה ויורדים למטה בנה\"ט כידוע במארז\"ל דלא גלו ישראל בין אוה\"ע רק להוסיף גרים כו' שהן נשמות<sup data-n=\"11386\">666</sup> שבגופים שנק' גרים שבאו מנוגה דעשי' ונעשים ישראל בקדושה שבתו\"מ שעושים שם, ומזה שרש תוס' יניקת הע\"ש, וע\"כ פיזרן לישראל תחת כל ע\"ש שיוצאי' מהם הניצוצי' דקדושה כמ\"ש בהיותכם מתי מספר<sup data-n=\"11387\">667</sup> כו' ויתהלכו [הניצוצות] <span data-k=\"pg\">שלח</span> ּ מגוי אל גוי<sup data-n=\"11388\">668</sup> לא הניח לאיש לעשקם<sup data-n=\"11389\">669</sup> כו' שלא יאבד אפי' ניצוץ א' אע\"פ שיערימו סוד<sup data-n=\"11390\">670</sup> כו' והוא קיבוץ גליות כו' [מ]כל העמים כו'.\n<b>וזהו</b> צדקת פרזונו פזרונו בחי' צדקה וחסד מצ\"ע כמו כי צדיק ה'<sup data-n=\"11391\">671</sup> צדקות אהב כו', והוא מה שפיזרן לניצוצות קדושות<sup data-n=\"11392\">672</sup> בע\"ש מאור הזרוע לצ\"ע בכל דור שזהו הכל מאוצר הע[ליון] כו'. וזהו כמו בזבוז האוצרות כו' שמבזבז והפקיר הכל ולא ליח\"ס וצנועים<sup data-n=\"11393\">673</sup> שראוים לזה שזהו שנק' פרזונו בגילוי אור הגנוז לחכמים ונביאים כו', אבל נש\"י שיגלה אור הגנוז בהם [מ]סדכ\"ס למטה בגופים שנמשכו מנוגה דעשי' זהו כמו בזבוז האוצרות ממש הנ\"ל שנק' פיזור, כמו שמפזר הון רב לשפלים ולכל<sup data-n=\"11394\">674</sup> בשוה ומפזר רב תבואות בשני הרעב ולהחיות עם רב<sup data-n=\"11395\">675</sup> כיוסף צ\"ע שהוא השליט<sup data-n=\"11396\">676</sup> כו' [ו]הוא המשביר בר לכל [עם] הארץ, כדי שיקבלו ע\"ש יניקה ויצאו מהן אח\"כ בריוח גדול כמ\"ש חיל בלע ויקיאנו<sup data-n=\"11397\">677</sup> חיל רב דניצוצי' הנ\"ל ויקיאנו כו', והוא לע\"ל שיהופכו גם הם לקדושה. וזהו יתרון האור הבא מן החשך דק\"נ, וכן בהיפך הרע דנה\"ב כמ\"ש בכל לבבך בשני יצריך כו' שנק' טוב מאד כידוע, ולזה הטעם נתלבשו המצות בדברים גשמיי' דק\"נ שזהו ג\"כ ענין בזבוז אוצרות הנ\"ל שהרי שורש התו\"מ בפנימיות האור הגנוז באוצר החכ\"ע כו' וד\"ל.\n<b>ואחר</b> כל הנ\"ל<sup data-n=\"11398\">678</sup> יובן בתוס' ביאור מ\"ש והנצח זו בנין ירושלים שזהו ע\"י שפיזרן לבין אוה\"ע בתחלה שזהו כמו בזבוז האוצרות כנ\"ל כדי שירוויח בהן הון רב יותר, והוא",[["11384","664","<b>אין בן דוד בא</b>: נסמן לעיל קלג, ד."],["11385","665","<b>הנשמות. . בשר של הארץ ההיא</b>: ראה הערה 668."],["11386","666","<b>דלא גלו. . גרים. . נשמות</b>: ראה לעיל פ' שמות מ, ג. וש\"נ."],["11387","667","<b>בהיותכם מתי מספר</b>: דהי\"א טז, יט."],["11388","668","<b>ויתהלכו. . מגוי אל גוי</b>: ראה לעיל פ' שמות מ, ג. וש\"נ."],["11389","669","<b>לא הניח לאיש לעשקם</b>: דהי\"א שם, כא."],["11390","670","<b>שיערימו סוד</b>: תהלים פג, ד. ראה גם ש\"א צא, ב."],["11391","671","<b>כי צדיק ה'</b>: תהלים יא, ז."],["11392","672","<b>קדושות</b>: חט: נש\"י."],["11393","673","<b>וצנועים</b>: ט: ולצדיקי'."],["11394","674","<b>ולכל</b>: שם: כמו לגדולי'."],["11395","675","<b>ולהחיות עם רב</b>: ויחי נ, כ."],["11396","676","<b>כיוסף. . שהוא השליט</b>: מקץ מב, ו."],["11397","677","<b>חיל בלע ויקיאנו</b>: נסמן לעיל פ' שמות מ, ג."],["11398","678","<b>הנ\"ל</b>: חט: זה."]]],[2300540845,"כאשר יוציא[ו] מע\"ש כל הטוב הגנוז בהם מרפ\"ח ניצוצין כו' בהיפוך חשך לאור ע\"י נש\"י שבאו בגופים בכל מקומות מושבותיהם בין כל העמים, ולהיות שזה עיקר חיות של הע\"ש לא ירצו בגאולת ישראל להוציאם מרשותם ולא עוד אלא שישתעבדו בהם כו', ע\"כ יבוא לכלל ניצוח שבא מב' דברים. הא' להכניעו למנגד שיבוטל אליו והוא מה שיהפך אל העמים<sup data-n=\"11399\">679</sup> כו'. והב' מה שנש\"י חבל נחלתו הם בשעבוד תחתם וכל הכוונה הי' בפיזור זה שיצאו מהם ברכוש גדול ביתרון האור מן החשך כנ\"ל, ע\"כ יגדל מדת הניצוח ביותר שכל עיקר הניצוח הוא בסוף יותר מבתחלה, שכאשר יבזבז כל האוצרות ופיזרן כו' עתה ישארו כל הניצוצות ביד זרים ויחז[י]קו בזה לעמוד לנגדו כו', ע\"כ נתעורר מדת הניצוח ביותר לעמוד לנגד ריבוי כל המנגדים וכל הע\"ש שכולם כא' [י]עמדו לנגד ועוזרים זל\"ז להתפשט בנש\"י המפוזרים ולא להניחם לקבוץ יחד בירושלים כו'. וזהו ה' כגבור יצא כאיש מלחמות כו' על אויביו יתגבר יריע אף יצריח<sup data-n=\"11400\">680</sup> כו'<sup data-n=\"11401\">681</sup>, וכתיב הנה ה' עומד לריב עמים<sup data-n=\"11402\">682</sup> וכה\"ג א' ה' יחתו מריביו<sup data-n=\"11403\">683</sup> כו' (ודוגמא לזה בכל ר\"ה שבני האלקי'<sup data-n=\"11404\">684</sup> מארי דדינין<sup data-n=\"11405\">685</sup> מבחי' הגבורות דנוגה דע\"ש שנק' בני רברבניא<sup data-n=\"11406\">686</sup> עומדים לנגד ה' דבחי' חסד העליון הפנימי, ויבא גם השטן הוא היצה\"ר<sup data-n=\"11407\">688</sup> כו' בתוכם<sup data-n=\"11408\">687</sup> בגבורו' ודין קשה לגמרי. אך מפני שכולם עומדים לנגד בבחי' דין, אז דוקא מתעורר בחי' הניצוח שלמעלה מן הטעם ויגבר חסד על הדין ויגער בשטן הנ\"ל כמ\"ש<sup data-n=\"11409\">689</sup> [יגער ה' בך השטן] ויגער ה'<sup data-n=\"11410\">691</sup> בך הבוחר בירושלים כו' כנ\"ל<sup data-n=\"11411\">690</sup> ). וז\"ש בש\"ע תחלה ולמלשינים אל תהי <span data-k=\"pg\">678</span> ּ תקוה כו' שהן המקטרגים הרעים ביותר כו', ואח\"כ על הצדיקים ו[על] החסידים ראשי נש\"י עד הקטנים תשב\"ר ועל כל כו' שיהי' להם למשען ולמבטח להוציאם ולגאלם שזהו קיבוץ גליות, ואח\"כ [יהי' בנין ירושלים וכמ\"ש] ולירושלים עירך ברחמים תשוב (כמשי\"ת בסמוך בענין פרזות תשב ירושלים) ואח\"כ את צמח דוד עבדך כו' שכ\"ז ע\"י ניצוח דוקא. וכן בבהמ\"ז אומרים על הארץ ואח\"כ רחם ה' על ישראל ועל<sup data-n=\"11412\">692</sup> ירושלים שיבנה ירושלים ברחמים כו' דהא בהא תליא. והיינו פזרונו שיהי' פרזונו דבאמת ענין א' הוא שאותיות א' להם שיהי' פרזון בגילוי אור אלקי על כל בשר כמו ואשפוך את רוחי כו' ונבאו בניכם כו' וכן ונגלה כבוד ה' וראו כ\"ב<sup data-n=\"11413\">693</sup> כו' וכמו כי כולם ידעו אותי מקטנם<sup data-n=\"11414\">694</sup> כו' (וכמו בקרי\"ס שראתה שפחה על הים<sup data-n=\"11415\">695</sup> כו'), שזהו כמו בזבוז האוצרות לכל בשוה ונק' צ\"פ בישראל כמו שיהי' צדקת פזרונו שפזרן לבין אוה\"ע מפני",[["11399","679","<b>העמים</b>: ט: ניתוסף: שפה א' ברורה."],["11400","680","<b>ה' כגבור. . אף יצריח</b>: ישעי' מב, יג [ושם: יריע אף יצריח על אויביו יתגבר]."],["11401","681","<b>כו'</b>: כ\"ה גם בדחט."],["11402","682","<b>הנה ה' עומד לריב עמים</b>: ראה ישעי' ג, יג. לקמן פ' תצוה שלט, א [ושם הוגה מגוכתי\"ק]. מאמרי אדה\"א קונטרסים ע' שלח. וש\"נ. שה\"א עה, ב ובהערה 16."],["11403","683","<b>ה' יחתו מריביו</b>: שמו\"א ב, י."],["11404","684","<b>בכל ר\"ה שבני האלקי'</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' תקסח. וש\"נ. תו\"ח לך צט, ג ובהערה 24."],["11405","685","<b>מארי דדינין</b>: זהר בראשית מג, ב. נו, א. מקץ רא, ב. ויגש רו, ב. ויחי רמט, א."],["11406","686","<b>בני רברבניא</b>: וכ\"ה בתו\"ח וירא צט, ג. ט: רברביא — ת\"א בראשית ו, ד."],["11407","688","<b>השטן הוא היצה\"ר</b>: ב\"ב טז, א."],["11408","687","<b>ויבא גם השטן. . בתוכם</b>: איוב א, ו. ב, א."],["11409","689","<b>הנ\"ל כמ\"ש</b>: דח: כנ\"ל במ\"ש. ט: כמ\"ש."],["11410","691","<b>ה'</b>: ד: ניתוסף בין השיטין. ח: ליתא."],["11411","690","<b>השטן]. . כנ\"ל</b>: ט: כו'."],["11412","692","<b>על ישראל ועל</b>: חט: על."],["11413","693","<b>ונגלה כבוד ה' וראו כ\"ב</b>: ישעי' מ, ה."],["11414","694","<b>כי כולם ידעו אותי מקטנם</b>: נסמן לעיל לח, ג."],["11415","695","<b>שראתה שפחה על הים</b>: נסמן לעיל קמד, ב."]]]]});
